window.__D("text/tikkunei-zohar/c001",{"p":[[9500011047,"<p>חִבּוּרָא דִילָךְ, כַּד יִתְגַּלֵי לְתַתָּא בְּדָרָא בַתְרָאָה בְּסוֹף יוֹמַיָּא, וּבְגִינֵיהּ (ויקרא כה י) וּקְרָאתֶם דְּרוֹר בָּאָרֶץ וְגוֹמֵר.</p>\n<p>פָּתַח אֵלִיָּהוּ וְאָמַר, כַּד נָפִיק שַׁבַּתָא וְיוֹמִין טָבִין, וְיִשְׂרָאֵל אִינוּן תְּחוֹת מֶמְשָׁלָה דְסמא\"ל וְשַׁבְעִין מְמַנָּן, וְדָחֲקִין לְיִשְׂרָאֵל, קָלָא נָפִיק מִן שְׁמַיָּא לְגַבֵּיהּ, וְיֵימָא הָכִי, יְרָ\"א בֹּשֶׁ\"ת, וְדָא בְרֵאשִׁית, יְהֵא לָךְ כִּסּוּפָא מִן שְׁמַיָּא,</p>\n<p>וְדָא (בראשית)</p>\n<p>בְּרֵאשִׁית יְרָ\"א בֹּשֶׁ\"ת,</p>\n<p>וַוי לֵיהּ לְסמא\"ל, כַּד קוּדְשָׁא בְּרִיךְ הוּא יֵיתֵי לְמִפְרַק לִשְׁכִינְתָּא וּלְיִשְׂרָאֵל בְּנָהָא, וְתָבַע מִנֵּיהּ וּמִשַּׁבְעִין אוּמִין וּמִמְּמַנָּן דִּילְהוֹן, כָּל עָאקוּ דְעָאקוּ לְיִשְׂרָאֵל בְּגָלוּתָא,</p>\n<p>בְּגִין דְּקֳדָם דְּגָלוּ יִשְׂרָאֵל, גַּלִּי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דַהֲווֹ עֲתִידִין יִשְׂרָאֵל לְמֶהֱוֵי תְּחוֹת שִׁעִבּוּדַיְיהוּ, (ס\"א למפק מתחות שעבודייהו), וְאַחֲזֵי לֵיהּ וּלְשַׁבְעִין מְמַנָּן דִּתְחוֹת יְדֵיהּ, אַגְרָא דִלְהוֹן אִי הֲווֹ אוֹקְרִין לְיִשְׂרָאֵל בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (בראשית לט ה) וַיְבָרֶךְ יְיָ' אֶת בֵּית הַמִּצְרִי בִּגְלַל יוֹסֵף,</p>\n<p>וְאִיהוּ וּמְמַנָּן דִּילֵיהּ לָא עָבְדִין לְהוֹן יְקָרָא, אֶלָּא עָבְדִין בְּהוֹן וּבִשְׁכִינְתָּא קְלָנָא, דְאָמְרִין לוֹן כָּל יוֹמָא אַיֵּה אלהי\"ך,</p>\n<p>וּבְגִין דָּא קָלָא נָפִיק לְגַבֵּיהּ כָּל יוֹמָא מִן שְׁמַיָּא, וְאָמַר יְרָ\"א בֹּשֶׁ\"ת, יְהֵא לָךְ כִּסּוּפָא מִן שְׁכִינְתָּא, יְרֵ\"א שָׁמַיִם יְהֵא לָךְ כִּסּוּפָא מִקּוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ שָׁמַיִם, הֲדָא הוּא דִכְתִיב (מלכים א ח לב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם,</p>\n<p>וְדָא (בראשית)</p>\n<p>בְּרֵאשִׁית, ש' שָׁמַיִ\"ם, (יר\"א שמי\"ם), יְרֵ\"א בַּיִ\"ת דִּילֵיהּ, דְּאִיהוּ רֹא\"שׁ בַּיִ\"ת, דָּחִיל לֵיהּ בְּבֵיתֵיהּ, דָּא הוּא בְּרֵאשִׁי\"ת,</p>\n<p>וְאִיהוּ וּמְמַנָּן דִּילֵיהּ לָא דְחִילוּ מִנֵּיהּ, וַחֲרִיבוּ בֵיתֵיהּ בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי,</p>\n<p>וּבְגִין דָּא (ישעיהו כד כג) וְחָפְרָה הַלְּבָנָה דְאִיהִי נָחָשׁ אֵשֶׁת זְנוּנִים, וּבוֹשָׁה הַחַמָּה דְאִיהִי גֵיהִנָּם, דְּנָחָשׁ אֵשֶׁת זְנוּנִים חֲרִיבַת בֵּיתָא דִשְׁכִינְתָּא, וְחַמָּה דְאִיהִי גֵיהִנָּם סַם הַמָּוְת אוֹקִידַת הֵיכָלָא.</p>\n<p>וּבְזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא בָּנֵי לוֹן כְּמִלְּקַדְמִין, הֲדָא הוּא דִכְתִיב (תהלים קמז ב) בּוֹנֵה יְרוּשָׁלַםִ יְיָ', בְּהַהוּא זִמְנָא וְחָפְרָה הַלְּבָנָה וּבוֹשָׁה הַחַמָּה (ישעיה כד כג), אֵימָתַי, בְּזִמְנָא דְכִי מָלַךְ יְיָ' צבאו\"ת,</p>\n<p>דְּבִנְיָינָא קַדְמָאָה אִתְעֲבִיד עַל יְדָא דְבַר נַשׁ, וּבְגִין דָּא שַׁלִּיטוּ עֲלַיְהוּ, בְגִין (תהלים קכו א) דְּאִם יְיָ' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ,</p>\n<p>וּבְגִין דְּבִנְיָינָא בַתְרָאָה יְהֵא עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא, יִתְקַיַּים, וְעַל דָּא אָמַר קְרָא, (חגי ב ט) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן.</p>\n<p>וּבְהַהוּא זִמְנָא דְיִתְבְּנֵי בִנְיָינָא עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא לְעִילָא וְתַתָּא, אִתְּמַר בִּשְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה (ישעיהו ל כו),</p>\n<p>וְחָפְרָה הַלְּבָנָה וּבוֹשָׁה הַחַמָּה, דְאִינוּן נוּקְבִין דְּסמא\"ל, וּבְגִין דְּלָא דְחִיל סמא\"ל מִן קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ שָׁמַיִם, וּבַת זוּגֵיהּ לָא דְחִילַת מִשְּׁכִינְתֵּיהּ דְּאִיהִי אַרְעִיהּ, אִתְּמַר בְּהוֹן (שם נא ו), כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ, וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה, הוּא סמא\"ל וּבַת זוּגֵיהּ: בְּרֵאשִׁית,</p>"],[9500011048,"<p>יָרֵ\"א שַׁבָּ\"ת, דְּאִיהִי שְׁכִינְתָּא, דַּעֲלָהּ אִתְּמַר (שמות לא יד) מְחַלְלֶיהָ מוֹת יוּמָת, דְּעָאלוּ אוֹיְבִים בֶּחָלָל דִּילָהּ דְּאִיהוּ קֹדֶשׁ קָדָשִׁים, וְאִתְּמַר בְּהוֹן (במדבר יט יג) אֶת מִקְדַּשׁ יְיָ' טִמֵּא, חִלֵּל מַמְלָכָה וְשָׂרֶיהָ (איכה ב ב), וְשִׁפְחָה עָאלַת בַּאֲתַר דִּגְבִירָה, דְּאִיהִי נִדָּה שִׁפְחָה גוֹיָה זוֹנָה, וְסָאִיבַת אַתְרָהָא, דְתַמָּן הֲוָה נְיָיחָא דִשְׁכִינְתָּא, וְקָלָא הֲוָה נָחִית וְאָמַר, יְרֵא שַׁבָּת, וְאִיהִי לָא עָבְדַת כַּךְ, אֶלָּא חִלֵּל מַמְלָכָה וְשָׂרֶיהָ, וּבָרְחַת שְׁכִינְתָּא מִתַּמָּן,</p>\n<p>בְּהַהוּא זִמְנָא שָׂחֲקוּ עַל מִשְׁבַּתֶּיהָ, וְאָמְרַת שִׁפְחָה, לַאו הַאי כְּגַוְונָא דְעָבְדַת שָׂרַי לְשִׁפְחָה דִילָהּ, הֲדָא הוּא דִכְתִיב (בראשית טז ח) מִפְּנֵי שָׂרַי גְּבִרְתִּי אָנֹכִי בֹּרַחַת,</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא, בְּרַתָּא דְרָשָׁע חַיָּיבָא, וְהָא אַף עַל גַּב דְּשָׂרַי תָּרְכַת לָהּ, אֲנָא רְחִימְנָא עֲלָהּ וְעַל בְּנָהּ, וְאַתּוּן לָא עֲבַדְתּוּן הָכִי, אֶלָּא גְרַמְתּוּן (נ\"א גמלתון) בִּישׁ תְּחוֹת טָב, אֲנָא אוֹמֵינָא לְאַעֲבָרָא מַלְכוּתָא חַיָּיבָא מֵעָלְמָא, וְלָא יְהֵא חֶדְוָה קֳדָמַי עַד דְּיִתְאֲבִידוּ מֵעָלְמָא, וּבְהַהוּא זִמְנָא יְהֵא חֶדְוָה קֳדָמַי, הֲדָא הוּא דִכְתִיב (משלי יא י) וּבַאֲבֹד רְשָׁעִים רִנָּה:</p>\n<p>בְּרֵאשִׁית שִׁי\"ר תָּאֵ\"ב, וְהָא אִיהוּ שִׁיר מְשׁוּבָּח מִכָּל הַשִּׁירִים, תָּאֵב מִכָּל הַשִּׁירִים, וַעֲלֵיהּ אִתְּמַר שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, הָכִי אוּקְמוּהוּ,</p>\n<p>וְהַאי שִׁיר מָתַי יִתְעַר, בְּזִמְנָא דְיִתְאַבְּדוּן סמא\"ל וּמְמַנָּן דִּילֵיהּ חַיָּיבַיָּא מִן עָלְמָא, וּבְהַהוּא זִמְנָא אָז יָשִׁיר מֹשֶׁה (שמות טו א), אָז שָׁר לָא כְתִיב אֶלָּא יָשִׁיר, וְהָא אוּקְמוּהוּ.</p>\n<p>וְהַאי שִׁיר בְּאָז, סְלִיק בְּפוּמָא, אֲבָל שִׁיר אִיהוּ וַדַּאי חָכְמַת שְׁלֹמֹה, בְּהַהוּא זִמְנָא וַתֵּרֶב חָכְמַת שְׁלֹמֹה (מלכים א ה י).</p>\n<p>וּמָאן סָלִיק לָהּ לְאַתְרָהּ, דָּא מֹשֶׁה, וְרָזָא דְמִלָּה אָז יָשִׁיר מֹשֶׁה, בְּאָן סָלִיק לָהּ בְּתַלְשָׁא, הַאי תַּגָּא דְתַלְשָׁא אִיהִי י' יָשִׁיר,</p>\n<p>וְתָקוּם מִן ה' דְמֹשֶׁה וְשַׁרְיָא עַל רֵישָׁא דְו', וְאִתְעֲבִידַת תַּגָּא ז', וְסָלִיק לָהּ עַד אֲתַר דְּאִתְגְּזַרַת מִתַּמָּן.</p>\n<p>כַּד סָלְקָא לְגַבֵּי י' עִלָּאָה אִתְקְרִיאַת שִׁיר זָכָר, וְכַד נָחְתָא לְגַבֵּי ה' אִתְקְרִיאַת שִׁירָה, הֲדָא הוּא דִכְתִיב אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַיְיָ' וְגוֹמֵר, דַּעֲלָהּ אִתְּמַר (תהלים קיח כב) אֶבֶן מָאֲסוּ הַבּוֹנִים וְגוֹמֵר,</p>\n<p>דְּאִיהִי אַבְנָא דִי מְחָת לְצַלְמָא דַעֲבוֹדָה זָרָה,</p>\n<p>בְּהַהִיא זִמְנָא דְאִתְמַחִי צַלְמָא דַעֲבוֹדָה זָרָה דִיּוֹקְנָא בִישָׁא, אִתְּמַר בָּהּ (דניאל ב לה) וְאַבְנָא דִי מְחָת לְצַלְמָא הֲוַת לְטוּר רַב וּמְלָאת כָּל אַרְעָא, הֲדָא הוּא דִכְתִיב (ישעיה ו ג) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ,</p>\n<p>וְהָכִי סְלִיקַת עַד דְּלָא אַשְׁכְּחִין לָהּ אֲתַר, וְשָׁאֲלִין מַלְאָכִין בְּגִינָהּ אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, וְלָא אַשְׁכְּחִין לָהּ שִׁיעוּרָא, עַד דְּאָמְרִין בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ, בְּגִין דְּסָלְקָא לֵיהּ עַד אֵין סוֹף דְּאִיהוּ י' רֵישָׁא דְא'.</p>\n<p>וּבְאָן סְלִיקַת בְּעַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ ו', עֲטָרָה עַל רֵישֵׁיהּ, כַּד סְלִיקַת עֲטָרָה עַל רֵישֵׁיהּ אִתְּמַר בָּה (משלי יב ד) אֵשֶׁת חַיִל עֲטֶרֶת בַּעִִלָהּ, וְכַד נְחִיתַת תְּחוֹתֵיהּ אִתְקְרִיאַת בַּת זוּגֵיהּ יִחוּדֵיהּ.</p>"],[9500011049,"<p>אִיהוּ תַגָּא לְעִילָא, תַגָּא דְסֵפֶר תּוֹרָה, בְּגִינָהּ אִתְּמַר וּדְאִשְׁתַּמֵּשׁ בְּתַגָּא חֲלָף,</p>\n<p>וְאִיהִי נְקוּדָה דְקָמֵץ א' לְתַתָּא, כְּגַוְונָא דָא א יְחוּדֵיה לְעִילָּא אִיהוּ כְּגַוְנָא דָא א תַּגָּא עַל סֵפֶר תּוֹרָה, לְתַתָּא כְּגַונָא דָא א נְקוּדָה דְאוֹרַיְיתָא, וּבְגִינָהּ אִתְּמַר (ישעיה מו י) מַגִּיד מֵרֵאשִׁית אַחֲרִית.</p>\n<p>כַּד אִיהִי חַיָּה בֵינַיְיהוּ, אוֹמְרִים מִמְּקוֹמוֹ יִפֶן בְּרַחֲמָיו לְעַמּוֹ, כַּד אִסְתַּלִּיקַת מִינַיְיהוּ, שׁוֹאֲלִים אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, וּבְהַהוּא זִמְנָא דְסָלְקָא אִיהִי כֻלְּהוּ חֵיוָון תְּרַפֶּינָה כַנְפֵיהֶם (יחזקאל א כד),</p>\n<p>וְאֵימָתַי סָלְקָא אִיהִי לְעִילָא, בְּעָמְדָם יִשְׂרָאֵל בַּעֲמִידָה, הֲדָא הוּא דִכְתִיב (שם) בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶם, דִּסְלִיקַת עַד אֵין סוֹף, לְמִשְׁאַל מְזוֹנָא מֵעִלַּת הָעִלּוֹת, וְכַד נְחִיתַת נְחִיתַת מַלְיָא מִכָּל טָבִין, בְּהַהוּא זִמְנָא חֵיוָן פָּתְחִין גַּדְפַיְיהוּ לְגַבָּהּ, בְּכַמָּה שִׁירוֹת וְתוּשְׁבְּחָן לְקַבְּלָא לָהּ בְּחֶדְוָה.</p>\n<p>וּבְאָן אֲתַר נָחֲתַת בְּאָת ו' דְאִיהִי בְאֶמְצָעִיתָא דְא' עַמּוּדָא דְאֶמְצָעִיתָא, בֵּיהּ קָרָאן לֵיהּ שְׁמַע יִשְׂרָאֵל שִׁי\"ר אֵ\"ל,</p>\n<p>וּבְהַהוּא זִמְנָא דְנָחֲתַת מַה כְּתִיב בְּחֵיוָון (שם) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם.</p>\n<p>קָם אֵלִיָּהוּ וְאָמַר רַבִּי רַבִּי חֲזוֹר בָּךְ, בְּוַדַּאי כַּד אִיהִי סְלִיקַת, כֻּלְּהוּ חֵיוָון מְצַפְצְפִין לְגַבָּהּ בְּכַמָּה שִׁירִין וְתוּשְׁבְּחָן, וְאִיהִי סָלְקָא עַל כֻּלְּהוּ עַד אֵין סוֹף, הֲדָא הוּא דִכְתִיב (משלי לא כט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה.</p>\n<p>עַד דְּקָרָאן לָהּ יִשְׂרָאֵל לְתַתָּא בִקְרִיאַת שְׁמַע דְּתֵיחוּת לְגַבַּיְהוּ, וּבְאָן קָרָאן לָהּ בְּבֶן זוּגָהּ דְּאִיהוּ ו', יִשְׂרָאֵל סָבָא, וְאִיהוּ שִׁיר אֵ\"ל, שִׁיר דִּילֵיהּ, דְּאִם לָא קָרָאן לָהּ בֵּיהּ לָא נָחֲתָא עֲלַיְהוּ.</p>\n<p>וּבְהַהוּא זִמְנָא דִנְחִיתַת קָשְׁרִין לָהּ בִּתְפִלָּה דְיָד לְתַתָּא, דִתְהֵא קְשׁוּרָה עִמֵּיהּ, וְרָזָא דְמִלָּה וְנַפְשׁוֹ קְשׁוּרָה בְנַפְשׁוֹ (בראשית מד ז), וְקֶשֶׁר דְּתַרְוַיְיהוּ אִיהוּ שֻׁרֵ\"ק לְתַתָּא, וּלְעִילָא שַׁלְשֶׁלֶ\"ת תְּפִלִּין עַל רֵישֵׁיהּ,</p>\n<p>בְּרָזָא דְטַעֲמֵי אִתְקְרִיאַת תְּנוּעָה, מִסִּטְרָא דִנְקוּדָה יִחוּדָא, וְצָרִיךְ לְאַרָכָא לָהּ בִּתְנוּעָה דְאִיהוּ רָבִיעַ עַד אֵין סוֹף לְעִילָא, וְצָרִיךְ לְנָחֲתָא לָהּ בְּחִירֵ\"ק עַד אֵין תַּכְלִית, לְאַמְלָכָא לָהּ עַל תַּתָּאִין.</p>\n<p>וּבְשׁוּרֵ\"ק צָרִיךְ לְיַחֲדָא לָהּ בְּבַעִִלָהּ, וּבְחֹלֵ\"ם אִיהִי תַגָּא עַל רֵישֵׁיהּ, וּבְחִירֵ\"ק אִיהִי כָרְסַיָּא תְּחוֹתֵיהּ, וּבְשׁוּרֵ\"ק אִיהוּ יִחוּדָא לְגַבֵּיהּ, כְּגַוְונָא דָא וִֹּ,</p>\n<p>וְכַד אִיהִי לְעִילָא תַּגָּא עַל רֵישֵׁיהּ, וְאִיהִי בְּרַתָּא (נ\"א נחתא) תְּחוֹת רַגְלוֹי, וְאִיהִי בְּיִחוּדָא דִילֵיהּ בְּחֵיקֵיהּ, אִתְעֲבִידַת שֻׁרֵ\"ק קִשּׁוּרָא דִילֵיהּ, וְכַד בָּעִי לְתַבְרָא קְלִיפִין דְּאִינוּן צְלָמִים, בָּהּ אִתְקְרֵי שְׁבָ\"א תְּבִי\"ר, וּבָהּ שַׁבֵּר תְּשַׁבֵּר מַצֵּבוֹתֵיהֶם (שמות כג כד).</p>\n<p>אֲבָל יִחוּדָא דִילָהּ בִּנְקוּדַת שׁוּרֵ\"ק וּ דְּאִיהוּ יְסוֹד חַ\"י עָלְמִין, חַ\"י בִּרְכָאָן דִּצְלוֹתָא,</p>\n<p>בְּזִמְנָא דְאִינוּן בְּיִחוּדָא חֲדָא, צְרִיכִין יִשְׂרָאֵל לְמֵיקַם בִּצְלוֹתָא בַחֲשַׁאי, וְרָזָא דְמִלָּה הָבִיאוּ לִי בַּחֲשַׁאי,</p>\n<p>וּבְגִין דָּא בְּעָמְדָם יִשְׂרָאֵל בַּעֲמִידָה, לְאַתְעָרָא לְגַבָּהּ חַ\"י בִּרְכָאָן בַּחֲשַׁאי, לְאַרָקָא לָהּ בִּרְכָאָן, אִתְּמַר בְּחֵיוָן בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶם, דְּלָא צָרִיךְ לְמִשְׁמַע גַּדְפַיְהוּ (נ\"א קלא), כְּגַוְונָא דְחַנָּה דְאִתְּמַר בָּהּ (שמואל א א יג) וְקוֹלָהּ לֹא יִשָּׁמֵעַ.</p>\n<p>וְהָכִי צְרִיכִין יִשְׂרָאֵל לְיַחֲדָא בְּבַת זוּגַיְיהוּ בַּחֲשַׁאי, בַּעֲנָוָה בְּאֵימָה בְּרֶתֶת וּבְזִיעַ בְּכִסּוּפָא, כְמָה דְאוּקְמוּהוּ קַדְמָאִין כְּמִי שֶׁכְּפָאוֹ שֵׁד, דְּאִיהִי שֵׁד מִן שד\"י, דִּבְהַהוּא זִמְנָא אִתְעֲבַר מִתַּרְעָא,</p>\n<p>וְדָא רָזָא דִמְזוּזָה, דְאִתְּמַר בָּהּ (דברים ו ט) וּכְתַבְתָּם עַל מְזְזוֹת בֵּיתֶךָ, מְזוּזַת כְּתִיב זָז מָוְת,</p>\n<p>וְאִם הוּא אִשְׁתַּמַּע קָלֵיהּ, מִיַּד לַפֶּתַח חַטָּאת רֹבֵץ (בראשית ד ז), וְלָא עוֹד אֶלָּא דְאִיהוּ זְעִיר בִּמְהֵמְנוּתָא, וְלָא לְמַגָּנָא אוּקְמוּהָ קַדְמָאִין כָּל הַמַּשְׁמִיעַ קוֹלוֹ בִתְפִלָּתוֹ הֲרֵי זֶה מִקְּטַנֵּי אֲמָנָה.</p>\n<p>בְּהַהוּא זִמְנָא דִמְיַחֵד קוּדְשָׁא בְּרִיךְ הוּא בִשְׁכִינְתֵּיהּ, כֻּלְּהוּ חֵיוָון מְקַבְּלִין דֵּין מִן דֵּין בִּרְכָאָן, וְכֻלְּהוּ בִקְדוּשָׁה,</p>\n<p>וּבְגִין דָּא תַּקִּינוּ קִדּוּשִׁין וּבִרְכָאָן לְכַלָּה, וְלָקֳבֵל בְּרָכָה וּקְדוּשָׁה וְיִחוּד דְּקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>הָכִי צְרִיכִין יִשְׂרָאֵל דִּיְהֵא יִחוּדָא דִלְהוֹן בִּקְדוּשָׁה וּבְרָכָה, וְהָכִי כָּל מְזוֹנַיְיהוּ בִּבְרָכָה וּקְדוּשָׁה, וְלֵית קְדוּשָׁה בְּפָחוּת מֵעֲשָׂרָה דְאִיהִי י',</p>"],[9500011050,"<p>וּבְגִין דְּטַבַּעַת אִיהִי י' כְּגַוְונָא דָא סּ, בָּהּ אִתְקַדְּשַׁת כַּלָּה, וְצָרִיךְ לְאַעָלָא לָהּ בְּאֶצְבְּעָא דִילָהּ, דְּאִיהוּ דִיוֹקְנָא דְאָת ו', וְאִתְעֲבִידַת ז', וְצָרִיךְ תְּרֵין סַהֲדִין דְּאִינוּן לָקֳבֵל ה ה, וְכַד אִיהִי טַבַּעַת בְּרֵישָׁא דְאֶצְבְּעָא וְאִתְעֲבִידַת ז', בְּהַהוּא זִמְנָא צָרִיךְ לְבָרְכָא לָהּ בְּשֶׁבַע בִּרְכָאָן דְּיַרְתָא כַלָּה.</p>\n<p>בְּהַהוּא זִמְנָא דְמִתְיַחֲדִין יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ (שיר א), מַאי נְשִׁיקוֹת פִּיהוּ, תְּרֵין שִׂפְוָון דִּילֵיהּ וּתְרֵין דִּילָהּ, אִינוּן אַרְבַּע גַּדְפִין דְּחֵיוָון, דְּאִתְּמַר בְּהוֹן (יחזקאל א ו) וְאַרְבַּע כְּנָפַיִם לְאַחַת מֵהֶן,</p>\n<p>וְכַד אִתְכְּלִילָן תְּרֵין אַנְפִּין דִּילֵיהּ וּתְרֵין דִּילָהּ, וְאַרְבַּע דְּרוֹעִין דְּתַרְוַיְהוּ, אִתְּמַר בְּהוֹן (שם) וְאַרְבָּעָה פָנִים לְאֶחָת, וְאַרְבַּע כְּנָפַיִם לְאַחַת מֵהֶם,</p>\n<p>וְאִינוּן אַרְבַּע אַנְפִּין יהו\"ה, אַרְבַּע גַּדְפִין אדנ\"י, בְּחִבּוּרָא חֲדָא יאהדונה\"י.</p>\n<p>כַּד מִתְחַבְּרָן אַתְוָון אִקְרֵי חַשְׁמַ\"ל, חַיּוֹת אֵשׁ מְמַלְּלָן, זִמְנִין חָשׁוֹת, זִמְנִין מְמַלְּלוֹת, וּבְגִינַיְהוּ אִתְּמַר גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְּבָרֵךְ, בְּגִין דְּמִתְחַבְּרִין חָתָן וְכַלָּה, תְּמַנְיָא אַתְוָון כַּחֲדָא.</p>\n<p>אִינוּן אַרְבַּע חֵיוָון, וְאִינוּן אַרְיֵה שׁוֹר נֶשֶׁר אָדָם,</p>\n<p>אַרְיֵה מְקַבֵּל עֲלֵיהּ י' בְּמוֹחָא, וּבְזִמְנָא דְאִיהוּ בִימִינָא דְאִתְּמַר בֵּיהּ (שם) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם, הָרוֹצֶה לְהַחְכִּים יַדְרִים,</p>\n<p>שׁוֹר לִשְׂמָאלָא לָקֳבֵל לִבָּא, ה' הֶבֶל דְּלִבָּא, תַמָּן ה' (איוב לז כב) מִצָּפוֹן זָהָב יֶאֱתֶה, בְּהַהוּא זִמְנָא דְאִיהִי ה' בְּלִבָּא, הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין.</p>\n<p>י\"ה דְּחִילוּ וּרְחִימוּ, אַבָּא וְאִימָּא, דְּרוֹעָא יְמִינָא וּשְׂמָאלָא, וַיַּעֲבֹ\"ר חֶסֶד וּגְבוּרָה, דְּסָלְקִין לְחוּשְׁבַּן ע\"ב תֵּיבִין, וְרי\"ו אַתְוָון דְע\"ב שְׁמָהָן, וְדָא רָזָא דְוַיַּעֲבֹ\"ר עִיבוּר כְּלָל תַּרְוַיְיהוּ.</p>\n<p>ו' דָּא אוֹרַיְיתָא דְשַׁרְיָא בְפוּמָא, וּבְרוּחָא דְפוּמָא פָרְחַת עַל נֶשֶׁר, דְּנֶשֶׁר אִיהוּ חוֹטָמָא, תְּרֵין גַּדְפוֹי דִּילָהּ תְּרֵין שִׂפְוָון, וַעֲלָהּ אִתְּמַר (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר, וְדָא עַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>דְּחָכְמָה וּבִינָה אִינוּן נִסְתָּרוֹת בְּמוֹחָא וְלִבָּא בִּרְחִימוּ וּדְחִילוּ,</p>\n<p>וְאוֹרַיְיתָא בְלָא דְחִילוּ וּרְחִימוּ לָא פָרְחַת לְעִילָא,</p>\n<p>וְכֶתֶר בֵּיהּ תַּלְיָין בָּנֵי חַיֵּי וּמְזוֹנֵי, דְּאִיהוּ מַזָּלָא דְכֻלְּהוּ, וְאִיהוּ לָא תַלְיָא בְּמַזָּלָא, וּבְגִין דָּא אוּקְמוּהוּ בָּנֵי חַיֵּי וּמְזוֹנֵי לַאו בִּזְכוּתָא תַלְיָא מִלְתָא, אֶלָּא בְּמַזָּלָא תַלְיָא מִלְתָא, דְּחֶסֶד אִיהוּ זְכוּתָא.</p>\n<p>ה' זְעִירָא דְמוּת אָדָם, בָּהּ אִשְׁתַּלִּים יהו\"ה, וְהִיא מַלְכוּתָא קַדִּישָׁא, אִיהִי מִצְוָה, עֲשִׂיַּית פִּקּוּדִין, דְּאִיהִי שַׁרְיָא בְּרַמַ\"ח אֵבָרִים,</p>\n<p>וְתוֹרָה וּמִצְוָה עֲלַיְיהוּ אִתְּמַר (דברים כט כח) וְהַנִּגְלוֹת לָנוּ, וּמִצְוָה בְּלָא דְחִילוּ וּרְחִימוּ לָא יְכִילַת לְסַלְקָא וּלְמֵיקַם קֳדָם י\"ה.</p>\n<p>אִיהִי כְלִילָא דְכֹלָא, וְעַל כֹּלָּא אָדָ\"ם, יו\"ד ה\"א וא\"ו ה\"א, דָא מַחֲשָׁבָה, דְסָלִיק כֹּלָּא עַד אֵין סוֹף, בְּמַלְכוּתָא אִשְׁתַּלִּים כֹּלָּא עִילָא וְתַתָּא.</p>\n<p>וְאִיהִי כְלִילָא מֵאַרְבַּע פָּרָשִׁיָּין דִּקְרִיאַת שְׁמַע, דְּאִינוּן רְמַ\"ח תֵּיבִין עִם אֵל מֶלֶךְ נֶאֱמָן, וּבְגִין דְּלָא יַעַבְדוּן הַפְסָקָה תַקִּינוּ לְמֶהְדַּר שְׁלִיחָא דְצִבּוּרָא יְיָ' אלהיכ\"ם אֱמֶת,</p>\n<p>וְכַד יִשְׂרָאֵל אָמְרִין שְׁמַע, מָארֵי חֵיוָון שָׁמְטִין גַּדְפַיְיהוּ, בְּאָן אֲתַר, בְּכַנְפֵי מִצְוָה דְאִתְּמַר בְּהוֹן (דברים כב יב) עַל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ אֲשֶׁר תְּכַסֶּה בָּהּ, דְּאִיהוּ כְּגַוְונָא דִמְעִיל הָאֵפוֹד, דְּפַעֲמוֹנִים וְרִמּוֹנִים אִינוּן לָקֳבֵל חֻלְיָין וְקִשְׁרִין, שׁוּלֵי הַמְּעִיל אִינוּן לָקֳבֵל כַּנְפֵי מִצְוָה.</p>\n<p>וְאִינוּן ה' קִשְׁרִין, לָקֳבֵל שְׁמַע יִשְׂרָאֵל יְיָ' אלהינ\"ו יְיָ' (דברים ו ד), דְּאִינוּן לָקֳבֵל ה' נִימִין דְּכִנוֹר דְּדָוִד דְּהָיָה מְנַגֵּן מֵאֵלָיו, י\"ג חֻלְיָין כְּחֻשְׁבַּ\"ן אֶחָ\"ד, דְּקָלָא דְנִגּוּנָא סָלְקָא בְאֶחָד,</p>\n<p>וְדָא חַ\"י בֵּין חֻלְיָין וְקִשְׁרִין, לְכָל סְטַר, סָלְקִין ע\"ב, וְדָא אִיהוּ וְהוּכַן בַּחֶסֶד כִּסֵּ\"א (ישעיה טז ה), חֶסֶ\"ד ע\"ב, כָּל מָאן דְּאִתְעַטַּף בְּעִטּוּפָא דְמִצְוָה, כְּאִלּוּ אַתְקִין כָּרְסְיֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִינוּן יאהדונה\"י,</p>\n<p>לְכָל חַד אַרְבַּע אַנְפִּין וְאַרְבַּע גַּדְפִין סָלְקִין ס\"ד, וּתְמַנְיָא אַתְוָון יאהדונה\"י, סָלְקִין ע\"ב,</p>\n<p>וְכַנְפֵי מִצְוָה</p>"],[9500011051,"<p>אוֹלְפִין רָזָא, דְּאִינוּן ח' חוּטִין לְכָל סְטַר, לָקֳבֵל אַרְבַּע אַנְפִּין וְאַרְבַּע גַּדְפִין דְּכָל חַיָּה, וּבְחֻשְׁבַּן זְעִיר דַּחֲנוֹךְ אָ\"ז אִיהוּ שד\"י, אָז יָשִׁיר בְּכָל אֲתַר, וְאָמְרוּ מָארֵי מַתְנִיתִין, כָּל מָאן דְּפָחִית לָא יִפְחוֹת מִשֶּׁבַע, וְכָל מָאן דְּאוֹסִיף לָא יוֹסִיף עַל י\"ג,</p>\n<p>וְאִינוּן שֶׁבַע לָקֳבֵל שֶׁבַע יְמֵי בְרֵאשִׁית, דִּרְמִיזִין לְשֶׁבַע שְׁמָהָן אבגית\"ץ וכו', וַעֲלַיְיהוּ אִתְּמַר (ישעיה ו ב) שְׁרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד, דִּבְהוֹן פָּרְחַת צְלוֹתָא לְעִילָא,</p>\n<p>וְאִנּוּן תַּמָּן מ\"ב, לָקֳבֵל מ\"ב אַזְכָּרוֹת דְּאִינוּן בִּתְפִלִּין דְּיָד וּתְפִלִּין דְּרֵישָׁא, וַעֲלַיְיהוּ אִתְּמַר (דברים כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' וכו'.</p>\n<p>וְאִינוּן תַּכְשִׁיטִין דְּכַלָּה, תְּפִלִּין דְּרֵישָׁא עֲטֶרֶת זָהָב בְּרֵישָׁא דְכַלָּה, וּתְפִלִּין דְּיָד טַבַּעַת דִּדְרוֹעָא, הָא כַלָּה מִתְתַּקְנָא בְתַכְשִׁיטִין דִּילָהּ, צָרִיךְ לִקְרֹא לְחָתָן דִּילָהּ, הֲדָא הוּא דִכְתִיב (שם ו ד) שְׁמַע יִשְׂרָאֵל,</p>\n<p>וְהָא אִינוּן בְּחוּפָּה, צְרִיכִין עַמָּא קַדִּישָׁא לְמֵיקַם בַּעֲמִידָה קֳדָמֵיהוֹן, עִם חַזָּן, לְבָרְכָא לוֹן בְּשֶׁבַע בִּרְכָאָן, וּלְקַדְשָׁא הֶחָתָן לְכַלָּה בְּקַדְמֵיתָא בְקִדּוּשִׁין, וּבְעָמְדָם עַמָּא קַדִּישָׁא וְחַזָּן לְבָרְכָא לוֹן, חֵיוָון קַדִּישִׁין דַּהֲווֹ מְנַגְּנִין בְּגַדְפַיְיהוּ תְּרַפֶּינָה כַנְפֵיהֶן.</p>\n<p>ש שֶׁל תְּפִלִּין דָּא אִימָּא עִלָּאָה, עֲלָהּ אִתְּמַר (שם כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁ\"ם יְיָ' נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ,</p>\n<p>שִׁי\"ן סְלִיק אַתְווֹי ש\"ס, ה' דְיַד כֵּהָה שְׁסָ\"ה, וְרַמַ\"ח פִּקּוּדִין דִּכְלִילָן בְּרַמַ\"ח תֵּיבִין דִּקְרִיאַת שְׁמַע בְּאַרְבַּע פָּרָשִׁיָּין, הָא תַּרְיַ\"ג, עֲלַיְיהוּ אִתְּמַר (שמות ג טו) זֶה שְּׁמִי לְעֹלָם וְזֶה זִכְרִי לְדֹר דֹּר,</p>\n<p>שְׁמִ\"י עִם י\"ה שְׁסָ\"ה, זִכְרִ\"י עִם ו\"ה רַמַ\"ח, וְכֹלָּא תַּרְיַ\"ג, אוֹרַיְיתָא אִיהִי שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְעוֹד צִיצִית אִיהִי כָרְסַיָּא, תְּפִלִּין קוּדְשָׁא בְּרִיךְ הוּא דְנָחִית עַל כָּרְסַיָּא, דְקָרָאן לֵיהּ בִּקְרִיאַת שְׁמַע, הָא קוּדְשָׁא בְּרִיךְ הוּא יְתִיב עַל כָּרְסַיָּא, צְרִיכִין לְמֵיקַם בְּגִינֵיהּ בִּצְלוֹתָא דְעַמִּידָה, תְּלַת חֲיָילִין דִּילָהּ אַתְיָין בִּזְמִירוֹת שִׁירוֹת וְתוּשְׁבָּחוֹת.</p>\n<p>בְּהַהוּא זִמְנָא דְאִיהוּ עַל כָּרְסְיֵיהּ, מָה אָמְרִין אֵ\"ל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים וּמִתְנַהֵג בַּחֲסִידוּת,</p>\n<p>הַאי תִּקּוּנָא אִיהוּ לְגַבֵּי צַדִּיקִים גְּמוּרִים, דִּמְתַקְּנִין כָּרְסַיָּא לְקוּדְשָׁא בְּרִיךְ הוּא בְצִיצִית, וְנָחֲתִין לֵיהּ בִּתְפִלִּין, וְקַיְימִין קֳדָמוֹהִי בִצְלוֹתָא,</p>\n<p>לְבֵינוּנִיִּים צִיצִית וּתְפִלִּין אִינוּן כַּשּׁוֹר לְעוֹל וְכַחֲמוֹר לְמַשְׂאוֹי, וּבְשַׁבָּת אִתְּמַר בְּהוֹן (שמות כג יב) לְמַעַן יָנוּחַ שׁוֹרְךָ וַחֲמוֹרֶךָ,</p>\n<p>לָרְשָׁעִים אִינוּן קִשּׁוּרָא לְכָל מְקַטְרְגִין דִּלְהוֹן,</p>\n<p>דְּהָכִי אִינוּן עֲשָׂרָה כִּתְרִין תַּתָּאִין, דְּהָא דָא לָקֳבֵל דָּא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא, אֲבָל כִּתְרִין תַּתָּאִין אִינוּן קְלִיפִין לְגַבֵּי כִּתְרִין עִלָּאִין, דְּמִתְלַבְּשִׁין בְּהוֹן עֲשַׂר אַתְוָון בִּצְלוֹתָא, לְמֶהֱוִי כְּפוּיִין תְּחוֹתוֹי כִּתְרִין תַּתָּאִין.</p>\n<p>וּבְזִמְנָא דְצַדִּיקַיָּא מְתַקְּנִין בְּכַנְפֵי מִצְוָה וּבִתְפִלִּין, אִתְכַּפְיָין תְּחוֹתַיְיהוּ כִּתְרִין תַּתָּאִין, בְּהַהוּא זִמְנָא יֵעוּל מַלְכָּא בְּהֵיכָלֵיהּ דְּאִיהוּ אדנ\"י, כְּגַוְונָא דָא יאהדונה\"י,</p>\n<p>הָא מַלְכָּא בְּהֵיכָלֵיהּ, מָאן דְּבָעִי לְמִשְׁאַל שְׁאֶלְתּוֹי יֵעוּל, וּבְגִין דָּא (תהלים נא יז) אדנ\"י שְׂפָתַי תִּפְתָּח,</p>\n<p>בִּתְלַת קַדְמָאִין יְסַדֵּר בַּר נַשׁ שְׁבָחוֹי, כְּעַבְדָא דִמְסַדֵּר שְׁבָחוֹי קֳדָם רַבֵּיהּ, דְאִלֵּין תְּלַת כָּתְבִין כָּל זַכְוָון, וּתְלַת בַּתְרָאִין חָתְמִין,</p>\n<p>וּבְגִין דָּא צָרִיךְ בַּר נַשׁ לְמֶהֱוֵי בְהוֹן כְּעַבְדָּא דִמְקַבֵּל פְּרָס מֵרַבֵּיהּ וְהָלַךְ לֵיהּ, דְּתַמָּן אִיהִי בֵית קִבּוּל חוֹתָמָא דְקִשּׁוּרָא וְאִיהִי מַלְכוּתָא קַדִּישָׁא.</p>\n<p>בְּאֶמְצָעִיּוֹת צָרִיךְ לְמִשְׁאַל, דְּתמָּן ו' ו', חַד מָארֵי כְּתִיבָה וְחַד מָארֵי חֲתִימָה, וְאִינוּן ו' עִלָּאָה ו' תַּתָּאָה, כְּלִילָן תְּרֵין עֲשַׂר פִּרְקִין,</p>\n<p>תְּלַת קַדְמָאִין רֵישָׁא וּתְרֵין דְּרוֹעִין, תְּלַת בַּתְרָאִין גּוּפָא וּתְרֵין שׁוֹקִין,</p>\n<p>הָא אִתְפַּטַּר מִמַּלְכָּא, בְּגִין דָּא צָרִיךְ לְמֵיהַב תְּלַת פְּסִיעָן לַאֲחוֹרָא, וְרָזָא דְמִלָּה (בראשית מט לג) וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה: בְּרֵאשִׁית</p>"],[9500011052,"<p>בָּרָ\"א שִׁי\"ת, וּמַאי נִיהוּ. שִׁית הֵיכָלִין לָקֳבֵל שִׁית יוֹמֵי בְּרֵאשִׁית, אלהי\"ם אִימָּא עִלָּאָה עֲלַיְיהוּ, דְּאִיהִי הֵיכָלָא שְׁבִיעָאָה,</p>\n<p>וּכְמָה דְאִימָּא עִלָּאָה אַפִּיקַת שִׁית, הָכִי אִימָּא תַּתָּאָה אַפִּיקַת שִׁית וּמַאי נִיהוּ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְאִינוּן שִׁית מָאנִין, דְּאִתְּמַר בְּהוֹן (שמות כ יא) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְהֵיכָלִין תַּתָּאִין אִינוּן מָאנִין לְהֵיכָלִין עִלָּאִין.</p>\n<p>וְכַד יִשְׂרָאֵל הֲווֹ מְצַלָּאן, כָּל הֵיכָלִין אִלֵּין הֲווֹ מִתְפַּתְּחָן לְגַבַּיְיהוּ,</p>\n<p>וּכְעַן בְּגָלוּתָא אִתְּמַר בְּהוֹן כָּל הַשְּׁעָרִים נִנְעֲלוּ, וּשְׁכִינְתָּא לְבָר מֵהֵיכָלָהּ, וְקוּדְשָׁא בְּרִיךְ הוּא לְבָר מֵהֵיכָלֵיהּ, וּמַלְאָכַיָּא דִמְמַנָּן עַל צְלוֹתִין לְבָר מֵהֵיכָלֵיהוֹן, הֲדָא הוּא דִכְתִיב (ישעיה לג ז) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה, וְלָא אִית לוֹן לִצְלוֹתִין אֲתַר לְאַעָלָא,</p>\n<p>וְדָא אִיהוּ כָּל הַשְּׁעָרִים נִנְעֲלוּ, אֲבָל שַׁעֲרֵי דִמְעָה לֹא נִנְעֲלוּ,</p>\n<p>וְלֵית מָאן דְּאַפְתַּח לוֹן לְאִלֵּין שְׁעָרִים, עַד דְּיֵיתֵי מָארֵי דְּדִמְעָה, דְאִתְּמַר בֵּיהּ (שמות ב ו) וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד וְהִנֵּה נַעַר בֹּכֶה, וְלֵית הֵיכָלָא מִתְפַּתְּחָא אֶלָּא בֵיהּ,</p>\n<p>וְדָא אִיהוּ וַתִּפְתַּח, וַתִּפְתַּח דּאִתְפַתַּח הַאי הֵיכָלָא לְגַבֵּיהּ, בְּמַאי אִתְפַּתַּח לֵיהּ בְּדִמְעָה, הֲדָא הוּא דִכְתִיב וְהִנֵּה נַעַר בֹּכֶה, וּמִיָּד וַתַּחְמֹל עָלָיו.</p>\n<p>וְעוֹד וַתִּפְתַּח, כַּד יִשְׂרָאֵל פָּתְחִין בִּתְיוּבְתָּא בְּבִכְיָה, מִיָּד וַתַּחְמֹל עָלָיו, וְדָא אִיהוּ בִּבְכִי יָבֹאוּ (ירמיה לא ח), בִּזְכוּת בִּכְיָה דִילֵיהּ יִתְכַּנְשׁוּן מִן גָּלוּתָא. דְּאִית</p>\n<p>דְּאִית הֵיכָלָא דְּדִמְעָה, דְלֵית לָהּ רְשׁוּ לְמִפְתַּח אֶלָּא בְדִמְעָה,</p>\n<p>וְאִית הֵיכָלָא דְנִגּוּנָא, דְלֵית לָהּ רְשׁוּ לְמִפְתַּח אֶלָּא בְנִגּוּנָא, וּבְגִין דָּא דָּוִד מִתְקָרֵב לְהַהוּא הֵיכָלָא בְנִגּוּנָא, הֲדָא הוּא דִכְתִיב (מלכים ב ג טו) וְהָיָה כְּנַגֵּן הַמְנַגֵּן,</p>\n<p>וְאִית הֵיכָלָא דִנְהוֹרָא, דְלָא מִתְפַּתְּחָא אֶלָּא לְבַר נַשׁ דַּהֲוָה מִתְעַסֵּק בִּנְהוֹרָא דְאוֹרַיְיתָא.</p>\n<p>וְאִית הֵיכָלָא דִנְבוּאָה, דְלָא מִתְפַּתְּחָא אֶלָּא לְבַר נַשׁ דַּהֲוָה חָכָם גִּבּוֹר וְעָשִׁיר,</p>\n<p>וְאִית הֵיכָלָא דְיִרְאָה, דְאִתְקְרֵי הֵיכַל הַיִּרְאָה, דְלָא מִתְפַּתְּחָא אֶלָּא לְמָאן דְּאִית בֵּיהּ דְּחִילוּ,</p>\n<p>וְאִית הֵיכָלָא דַעֲנִיִּים, דְּלָא מִתְפַּתְּחָא אֶלָּא לַעֲנִיִּים דַּהֲווֹ מִתְעַטְּפִים קֳדָם יהו\"ה בִּצְלוֹתָא, בְעִטּוּפָא דְמִצְוָה דְצִיצִית וּתְפִלִּין וַעֲלַיְהוּ אִתְּמַר (תהלים קב א) תְּפִלָּה לְעָנִי כִי יַעֲטֹף.</p>\n<p>וְאִית תַּרְעָא דְצַדִּיקַיָּא, דְלָא מִתְפַּתְּחָא אֶלָּא לְצַדִּיקַיָּא, הֲדָא הוּא דִכְתִיב (שם קיח כ) זֶה הַשַּׁעַר לַיְיָ' צַדִּיקִים יָבֹאוּ בוֹ, וְהַאי אִיהוּ תַרְעָא דְצַדִּיק חַ\"י עָלְמִין, דְּאִתְּמַר בֵּיהּ (שם לז כה) וְלֹא רָאִיתִי צַדִּיק נֶעֱזָב וְזַרְעוֹ מְבַקֶּשׁ לָחֶם,</p>\n<p>וּכְעַן בְּגָלוּתָא אִתְּמַר בֵּיהּ (ישעיה נז א) הַצַּדִּיק אָבָד, מַאי אָבָד, אָבַד לְמַטְרוֹנִיתָא, וְאִתְּמַר בֵּיהּ (שם יט ה) וְנָהָר יֶחרַב וְיָבֵשׁ, יֶחרַב בְּבַיִת רִאשׁוֹן, וְיָבֵשׁ בְּבַיִת שֵׁנִי,</p>\n<p>וּבְגִין דְּלֵית לֵיהּ מִדִּילֵיהּ, עֲנִיִּין צָוְוחִין בְּחַ\"י בִּרְכָאָן דִּצְלוֹתָא, לְגַבֵּי חַ\"י עָלְמִין, וְהָא אִסְתַּלַּק מִתַּמָּן נְבִיעוּ דְכָל בִּרְכָאָן, וְלֵית מָאן דִּיְהִיב לוֹן, וְתַרְעִין אָחֳרָנִין סְתִימִין, וְתַרְעָא דְצַדִּיק חֲרֵבָא וִיבֵשָׁה, כְּמָה דְעָנִי חָרֵב וְיָבֵשׁ,</p>\n<p>וְרָזָא דְמִלָּה (בראשית א ט) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה.</p>\n<p>וְלֵית תַּרְעָא פְּתִיחָא אֶלָּא תַרְעָא דְּדִמְעָה, וּמַאי אִיהִי בַּת עַיִן, דְּדִמְעָה מִינָהּ נַפְקָא, וַעֲלָהּ אִתְּמַר (תהלים יז ח) שָׁמְרֵנִי כְּאִישׁוֹן בַּת עָיִן, וּבָהּ וְהִנֵּה נַעַר בֹּכֶה (שמות ב ו), לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, דִירַחַם עֲלֵיהּ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (תהלים קב יד) אַתָּה תָקוּם תְּרַחֵם צִיּוֹן,</p>\n<p>בְּגִין דְּאִיהִי לַבַּת אֵשׁ דְּאִתְחַזְיָיא לְמֹשֶׁה בַּסְּנֶה, דִכְתִיב (שמות ג ב) וַיֵּרָא מַלְאַךְ יְיָ' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה, אִיהִי בַ\"ת מִן בְּרֵאשִׁי\"ת, וְדָא בְּרֵאשִׁית. בְּרֵאשִׁי\"ת</p>"],[9500011053,"<p>מַאֲמָר קַדְמָאָה דְכֹלָּא, כְּלִילָא מֵעֲשַׂר אֲמִירָן, וְאִיהִי ל\"ב אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית, וּמִסִּטְרָא דִשְׂמָאלָא אִתְיְיהִיבַת, דְּאִיהִי גְבוּרָה אֶשָּׁא סוּמְקָא, וּבְגִין דָּא בְּלַבַּת אֵשׁ (שמות ג ב), וּמֹשֶׁה הֲוָה מִסִּטְרָא דְלֵיוָאֵי מִסִּטְרָא דִילֵיהּ מַמָּשׁ,</p>\n<p>וְאַמַּאי אִתְגַּלְיָא לֵיהּ בַּסְּנֶה, לְאַחֲזָאָה דַהֲוַת בְּדוֹחֲקָא בֵין הַקּוֹצִים, וְעִם כָּל דָּא וְהַסְּנֶה אֵינֶנּוּ אֻכָּל, בְּגִין שׁוֹשַׁנִּים דְּאִינוּן בְּנָהָא, דְאִינוּן יִשְׂרָאֵל, דַּהֲווֹ עֲתִידִין לְמֶהֱוִי בְגָלוּתָא בֵּין עִרֶב רַב דְּאִינוּן קוֹצִים, וְדָא אִיהוּ רָזָא (ירמיהו מו כח) כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם אֲשֶׁר הִדַּחְתִּיךָ שָׁמָּה, וְאוֹתְךָ לֹא אֶעֱשֶׂה כָלָה.</p>\n<p>אַחֲזֵי לֵיהּ אַגְרָא דְכַלָּה, דְאִיהִי לַבַּת אֵשׁ בֵּין הַקּוֹצִים דְּאִינוּן חַיָּיבַיָּא, כַּד דָּחֲקִין לִשְׁכִינְתָּא וְיִשְׂרָאֵל, אַגְרָא דִלְהוֹן כַּלָּה, נַפְקָא שְׁכִינְתָּא כַלָּה מִבֵּינַיְיהוּ, וְיֵיתֵי חָתָן בְּגִינָהּ, וְדָא אִיהוּ אַגְרָא דְכַלָּה דוֹחֲקָא, וְיִפְרוֹק לוֹן מִן גָּלוּתָא בְּגִינָהּ,</p>\n<p>וְדוֹחֲקָא דְגָלוּתָא דְעִרֶב רַב לְיִשְׂרָאֵל מְמַהֵר לוֹן פּוּרְקָנָא, וְרִפְיוֹן דִּילְהוֹן מְעַכֵּב לוֹן לְיִשְׂרָאֵל פּוּרְקָנָא,</p>\n<p>בְּגִין דָּא אִתְחַזֵּי לֵיהּ לְמֹשֶׁה בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה, מִגּוֹ כוּבִין.</p>\n<p>כַּד אִתְקַרִיב תַּמָּן לְמֶחזֵי עוֹבָדָא דָא, אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּקְרַב הֲלוֹם, שַׁל נְעָלֶיךָ (שמות ג ה),</p>\n<p>הָכָא רֶמֶז דְּאִתְפַּשַּׁט מִן גּוּפָא דִילֵיהּ, דְּאִיהוּ נַעַל, לְגַבֵּי גוּפָא אָחֳרָא דְאִתְלַבַּשׁ כַּד אִתְקַרִיב,</p>\n<p>וְאִית מָאן דְּיֵימָא דְאִיהוּ אִתְּתֵיהּ, וְכֹלָּא קְשׁוֹט דָּא וְדָא.</p>\n<p>וְכֵן אַחֲזֵי לֵיהּ דְּבֵי מַקְדְּשָׁא דְאִיהִי בִנְיָנָא דְבַר נַשׁ דְּעָתִיד לְאִתְחָרְבָא, וְיִתְבְּנֵי זִמְנָא אָחֳרָא עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן (חגי ב ט), בְּגִין דְּאִתְּמַר בּוֹ (זכריה ב ט) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יְיָ' חוֹמַת אֵשׁ סָבִיב,</p>\n<p>אִתְּמַר בְּבֵי מַקְדְּשָׁא בּוֹנֵה יְרוּשָׁלַם יְיָ'. וְאִתְּמַר הָתָם לְגַבֵּי אָדָם (בראשית ב כב) וַיִּבֶן יְיָ' אלהי\"ם אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם, דָּא חָכְמָה, וַיְבִיאֶהָ אֶל הָאָדָם, דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דַרְגָּא דְמֹשֶׁה,</p>\n<p>וְהַאי צֵלָע אִיהוּ וַדַּאי כַּלַּת מֹשֶׁה, וַעֲלָהּ אִתְּמַר וַיֵּרָא אֵלָיו מַלְאַךְ יְיָ' בְּלַבַּת אֵשׁ, דְּאִיהִי בַת יְחִידָה, דְמִנָּהּ נָפִיק נְהוֹרָא דְאוֹרַיְיתָא.</p>\n<p>כְּגַוְונָא דָא אִתְּמַר (שמות ב ו), וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד, וַתִּרְאֵהוּ דָא שְׁכִינְתָּא, דַהֲוָה בָכֵי בְגִינָהּ, מִיָּד וַתַּחְמוֹל עָלָיו, וְדָא הוּא בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם (ירמיהו לא ח), בְּתַחֲנוּנִים וַדַּאי, לְקַיְימָא וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ (ישעיהו נד ז).</p>\n<p>בְּהַאי זִמְנָא כָּל חֵיוָן יִתְעָרוּן בְּקָלָא, וְעוֹפִין מְצַפְצְפִין בְּשִׁיר, לְקַבְּלָא בְּרַתָּא בְּחֶדְוָה בְנִגּוּנָא, לְקַבְּלָא קִדּוּשִׁין מֵהֶחָתָן, דְּאִינוּן קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ וכו' (שם ו ג), וְלֵית קְדוּשָׁה פָּחוּת מֵעֲשָׂרָה,</p>\n<p>וְקִדּוּשִׁין אִינוּן מִסִּטְרָא דְחָכְמָה דְאִיהוּ י', קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה (ירמיהו ב ג), רֵאשִׁית וַדַּאי,</p>\n<p>וּמִתְבָּרְכִין בְּשֶׁבַע בִּרְכָאָן מִסִּטְרָא דְאִימָּא עִלָּאָה דְאִיהִי בְּרָכָה, וַעֲלָהּ אִתְּמַר (יחזקאל מד ל) לְהָנִיחַ בְּרָכָה אֶל בֵּיתֶךָ,</p>\n<p>וְשֶׁבַע בִּרְכָאָן אִינוּן, בְּשַׁחֲרִית שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבְעַרְבִית שְׁתַּיִם לְפָנֶיהָ שְׁתַּיִם לְאַחֲרֶיהָ,</p>\n<p>וְאִינוּן שֶׁבַע סְפִירָן דִּכְלִילָן בְּחָתָן וְכַלָּה, וְדָא אִיהוּ שְׁמַע יִשְׂרָאֵל וְגוֹמֵר, הָא הָכָא קְדוּשָׁה וּבְרָכָה וְיִחוּד,</p>\n<p>בְּהַהוּא זִמְנָא אִתְעַר דָּוִד בְּכִנּוֹר דְּאִיהוּ מְנַגֵּן מֵאֵלָיו, בַּעֲשָׂרָה מִינֵי נִיגוּנִין: קַדְמָאָה בְּאַשְׁרֵי וְדָא בְּרֵאשִׁית:</p>\n<p>בְּרֵאשִׁית תַּמָּן אַשְׁרֵ\"י, וְדָא אִיהוּ אַשְׁרֵי הָאִישׁ, וְאִיהוּ אהי\"ה אֲשֶׁר אהי\"ה, רֵישָׁא לְכָל</p>"],[9500011054,"<p>רֵישִׁין,</p>\n<p>וַעֲלָהּ אִתְּמַר (שיר ז ו) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל וְדָא תְּפִלִּין דְּרֵישָׁא, וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן דָּא תְּפִלִּין דְּיָד, וּבֵיהּ מְשַׁבְּחִין לְבַת בְּהַאי אַשְׁרֵי,</p>\n<p>הֲדָא הוּא דִכְתִיב (בראשית ל יג) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת.</p>\n<p>מָאן זָכֵי לְאַעָלָא תַמָּן, אֲשֶׁר לֹא הָלַךְ בַּעֲצַת רְשָׁעִים (תהילים א׳:א׳), דְּאִיהִי עִצָה בִּישָׁא מִסִּטְרָא דְעִץ הַדַּעַת טוֹב וָרָע,</p>\n<p>וּבְדֶרֶךְ חַטָּאִים לֹא עָמָד, מָאן דֶּרֶךְ חַטָּאִים הַהִיא דְאִתְּמַר בָּהּ (משלי ל כ) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת, אָכְלָה וּמָחֲתָה פִיהָ וְגוֹמֵר,</p>\n<p>וּבְמוֹשַׁב לֵצִים לֹא יָשָׁב, מָאן מוֹשַׁב לֵצִים, דָּא לִילִי\"ת אִימָּן דְּעִרֶב רַב, דְּאִיהִי מְטַמְּאָה כְנִדָּה בְמוֹשָׁבָהּ, וְכֵן עִרֶב רַב מְטַמְּאִין בְּמוֹשָׁבָם לְצַדִּיקַיָּא דְיָתְבִין בֵּינַיְיהוּ כְנִדָּה.</p>\n<p>וּמָאן דְּאִתְדַּבַּק בְּהַאי אַשְׁרֵי, דְאִיהוּ כִתְרָא וְרֵישָׁא דְאוֹרַיְיתָא, אִתְּמַר בֵּיהּ (תהלים א ג) וְהָיָה כְּעִץ שָׁתוּל עַל פַּלְגֵי מָיִם, וְדָא עִץ חַיִּים, דְּאִתְּמַר בֵּיהּ וְעָלֵהוּ לֹא יִבּוֹל, וְהַאי תִּקּוּנָא קַדְמָאָה.</p>\n<p>תִּנְיָינָא בְּשִׁיר דָּא חָכְמָה, שָׁר י', וּתְלַת יוּדִי\"ן אִנּוּן י' י' י', וְאִינוּן רֵישָׁא וְסוֹפָא וְאֶמְצָעִיתָא דְאָת י', וְאִינוּן רְמִיזִין בִּשְׁמָא סְתִים דְּאִיהוּ יו\"ד ה\"י וא\"ו ה\"י,</p>\n<p>בְּאִלֵּין תְּלַת שַׁבַּח דָּוִד מַלְכָּא לִבְרַתָּא דְמַלְכָּא, הֲדָא הוּא דִכְתִיב (תהלים קכא א) שִׁיר לַמַּעֲלוֹת, ל' מַעֲלוֹת אִינוּן וַדַּאי, אִינוּן תְּלָתִין דַּרְגִּין, דִּבְהוֹן בְּרַתָּא סָלְקָא לְגַבֵּי אַבָּא.</p>\n<p>בְּחָמֵשׁ נִימִין דְּכִנּוֹר, דְּאִינוּן חָמֵשׁ אַזְכָּרוֹת דְּאַדְכִּיר חָמֵשׁ זִמְנִין יהו\"ה בְּהַאי מִזְמוֹר, חַד עִִזְרִי מֵעִם יְיָ', ב' יְיָ' שֹׁמְרֶךָ, ג' יְיָ' צִלְּךָ, ד' יְיָ' יִשְׁמָרְךָ מִכָּל רָע, ה' יְיָ' יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ,</p>\n<p>וּבְהוֹן מַלְכָּא אָמַר לְגַבֵּי כַלָּה, צַהֲלִי קוֹלֵךָ בַּת גַּלִּים (ישעיהו י ל), בַּת עֲשָׂרָה גַּלְגַּלִּים, דְּסָלִיק בְּהוֹן יו\"ד ה\"א וא\"ו ה\"א, בַּעֲשָׂרָה מִינֵי נִגּוּנִין. וּבְאַרְבַּע חֵיוָן דְּסָלִיק יהו\"ה, בְּשִׁיר פָּשׁוּט, כָּפוּל, מְשׁוּלָשׁ, מְרוּבָּע, דְּאִיהוּ יהו\"ה,</p>\n<p>דְּקוֹלוֹ סָלְקָא כְגַלֵּי יַמָּא, וְגַלֵּי יַמָּא דִלְעִילָא אִינוּן עֲשָׂרָה גַלְגַּלִּין, וַעֲלַיְהוּ אִתְּמַר (שיר ה יד) יָדָיו גְּלִילֵי זָהָב מְמֻלָּאִים בַּתַּרְשִׁישׁ, בִּתְרֵין דְּרוֹעִין דִּבְרַתָּא. וּבְהוֹן שִׁית פִּרְקִין, וְאִינוּן שִׁית דַּרְגִּין דְּכָרְסַיָּא, שֵׁשׁ מַעֲלוֹת לַכִּסֵּא,</p>\n<p>וְכַד סָלִיק ו' בְּהוֹן, יִתְעָרוּן לְגַבֵּיהּ לְקַבְּלָא לֵיהּ שְׂרָפִים בְּגַדְפַיְיהוּ,</p>\n<p>הֲדָא הוּא דִכְתִיב (ישעיה ו ב) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם וְגוֹמֵר, וּמָאן דְּסָלִיק עַל גַּדְפַיְיהוּ וּפָרַח בְּהוֹן אִיהוּ ו', כְּלִיל שִׁית תֵּיבִין דְּיִחוּדָא שְׁמַע יִשְׂרָאֵל, וּבְגִינֵיהּ אִתְּמַר (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם וְגוֹמֵר.</p>\n<p>וְכַד סָלְקָא בְּרַתָּא סָלְקָא בִּתְרֵין דְּרוֹעוֹי דְּאִינוּן חֶסֶד וּגְבוּרָה, דִבְהוֹן שִׁית פִּרְקִין דְּאִיהוּ ו', וְרָזָא דְמִלָּה שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי (שיר ב ו).</p>\n<p>כַּד סָלְקָא הַאי שִׁיר, סָלְקָא בְשִׁית תֵּיבִין דְּאִינוּן שְׁמַע יִשְׂרָאֵל וְגוֹמֵר, וְכַד נָחֲתָא, נָחֲתָא בְשִׁית, דְּאִינוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד,</p>\n<p>וְנִגּוּנָא כַד סָלִיק סָלִיק בְּשִׁית, וְכַד מָאִיךְ מָאִיךְ בְּשִׁית, וַעֲלַיְיהוּ אִתְּמַר (שם ה טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ.</p>\n<p>וַעֲשָׂרָה גַלְגַּלִּין אִינוּן י', דְּאִינוּן לָקֳבֵל עֲשַׂר אֶצְבְּעָאן דְּבָטְשִׁין בְּנִגּוּנָא, חָמֵשׁ בְּחָמֵשׁ, וְאִינוּן ה\"ה, דְּסָלְקִין בְּי' בְּשִׁית דַּרְגִּין דְּאִיהוּ ו', בֵּיהּ סָלְקִין וְנָחֲתִין,</p>\n<p>וְאִיהוּ כְּגַוְונָא דְסֻלָּם, דְּאִתְּמַר בֵּיהּ (בראשית כח יב) וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְגוֹמֵר, וְהִנֵּה מַלְאֲכֵי אלהי\"ם עֹלִים וְיֹרְדִים בּוֹ, וְכֹלָּא יהו\"ה, יו\"ד ה\"א וא\"ו ה\"א, יָ\"ד, וְדָוִד מְנַגֵּן בְּיָד (שמואל א יט ט),</p>\n<p>ו' אִיהוּ גוּפָא, גַּדְפוֹי ה\"ה, רֵישָׁא דִילֵיהּ י', בֵּיהּ סָלִיק קָלָא דְנִגּוּנָא.</p>\n<p>וְעוֹד ו' אִיהִי מְנַרְתָּא, ה' ה' שְׁלֹשָׁה קְנֵי מְנוֹרָה מִצִּדָּהּ הָאֶחָת וְגוֹמֵר (שמות כה לב), ו' מְנוֹרָה בְּאֶמְצַע, נֵר עַל רֵישֵׁיהּ י', כַּד שַׁרְיָא בְּאָת ו' אִתְעֲבִיד ז', וְרָזָא דְמִלָּה יָאִירוּ שִׁבְעַת הַנֵּרוֹת (במדבר ח ב). לָקֳבֵל מְנַרְתָּא דְאִיהִי ו', וְשִׁית קְנֵי מְנַרְתָּא דְאִינוּן ה' ה', שִׁית וָוִי\"ן,</p>\n<p>וְרָזָא דְמִלָּה שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת (זכריה ד ב), עַד דְּסָלְקִין לְי\"ד, דְּאִיהוּ יהו\"ה יו\"ד ה\"א וא\"ו ה\"א, וְדָא אִיהוּ וְדָוִד מְנַגֵּן בְּיָד,</p>\n<p>יָ\"ד לָקֳבֵל יָ\"ד, וְסָלְקָא ה' בְּאָת ו', וּלְבָתַר סָלִיק ו' בְּי', שִׁית זִמְנִין עִִשֶׂר, עַד דְּסָלִיק לְשִׁתִּין,</p>\n<p>וְאִינוּן אַתְוָון הַדְּבֵקוֹת בִּקְרִיאַת שְׁמַע, דִּבְגִינַיְיהוּ אִתְּמַר כָּל הַמֵּשִׂים רֵיוַח בֵּין הַדְּבֵקִים מְצַנְּנִים</p>"],[9500011055,"<p>לֵיהּ גֵּיהִנָּם,</p>\n<p>וּשְׁלֹמֹה עֲלַיְיהוּ אָמַר (שיר ג ז) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ, וְאִינוּן נָטְרִין (נ\"א נטלין) עַרְסֵיהּ, וּלְקִבְלַיְיהוּ (שם ו ח) שִׁשִּׁים הֵמָּה מְלָכוֹת,</p>\n<p>אִלֵּין דְּכוּרִין, וְאִלֵּין נוּקְבִין, אִלֵּין דִּקְרִיאַת שְׁמַע דְּתַקִּין מֹשֶׁה דְכוּרִין, אִלֵּין דִּשְׁלֹמֹה נוּקְבִין, וְאִלֵּין בֵּית קִבּוּל לְאִלֵּין, דַּרְגִּין דִּשְׁלֹמֹה אִינוּן בֵּית קִבּוּל לְדַרְגִּין דְּמֹשֶׁה, וְכַד מִתְחַבְּרָן כֹּלָּא כְּאֶחָד, שְׁלֹמֹ\"ה אִתְהַפַּךְ לְמֹשֶׁ\"ה.</p>\n<p>בְּתִיקוּנִין דְּאַרְבַּע אַתְוָון אִתַּקַּן שִׁיר, וַעֲלַיְיהוּ אִתְּמַר וְהִנֵּה מַלְאֲכֵי אלהי\"ם וְגוֹמֵר, סָלְקִין תְּרֵין וְאִינוּן י\"ה, וְנָחֲתִין תְּרֵין וְאִינוּן ו\"ה, וְכֵן גַּלְגַּלֵּי יַמָּא סָלְקִין בְּעִִשֶׂר, וְאִינוּן יו\"ד ה\"א וא\"ו ה\"א, וְאַרְבַּע חֵיוָון,</p>\n<p>כַּד סָלְקָא בְּרַתָּא בְּשִׁיר, נִשְׁרָא נְטִיל י' בְּפִימָא וְעַל רֵישָׁהָא, ו' בְּגוּפָא, ה\"ה בְּגַדְפָהָא, אָדָ\"ם יו\"ד ה\"א וא\"ו ה\"א רְכִיב עַל כֹּלָּא, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, דָּא סְלִיק עַל כֹּלָּא, וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעִִתָּם דָּא יהו\"ה, וּפְנֵי שׁוֹר, וּפְנֵי נֶשֶׁר, אִינוּן מֶרְכָּבָה לִשְׁמָא דְיהו\"ה, וְאָדָם עַל כֹּלָּא.</p>\n<p>בְּזִמְנָא דְאִיהִי סָלְקָא בְּכָל אִלֵּין תִּקּוּנִין, אִיהוּ מְשַׁבַּח לָהּ, הֲדָא הוּא דִכְתִיב (שם ד ג) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ וּמִדְבָּרֵךְ נָאוְה, הָא תְּרֵין מִינֵי נִגּוּנִין דְּשַׁבַּח דָּוִד מַלְכָּא, בְּאַשְׁרֵי בְּשִׁיר.</p>\n<p>תְּלִיתָאָה בַּבְּרָכָה וְדָא שְׁכִינְתָּא עִלָּאָה, וַעֲלָהּ אִתְּמַר (תהלים קג א) בָּרְכִי נַפְשִׁי אֶת יְיָ', מֵהַאי אִתְיְיהִיבַת בְּבַר נַשׁ נִשְׁמַת חַיִּים,</p>\n<p>דְּאִתְּמַר בָּהּ חֲמִשָּׁה תִּקּוּנִין,</p>\n<p>מַה הַקָּדוֹשׁ בָּרוּךְ הוּא זָן כָּל עָלְמָא, הָכִי נִשְׁמָתָא זָנַת כָּל גּוּפָא, מַה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה וְאֵינוֹ נִרְאֶה, הָכִי נִשְׁמָתָא רוֹאָה וְאֵינָה נִרְאֵית, מַה הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּחַדְרֵי חֲדָרִים, הָכִי נִשְׁמָתָא יוֹשֶׁבֶת בְּחַדְרֵי חֲדָרִים, מַה הַקָּדוֹשׁ בָּרוּךְ הוּא מָלֵא כָל הָעוֹלָם הָכִי נִשְׁמָתָא מְלֵאָה אֶת כָּל הַגּוּף, מַה הַקָּדוֹשׁ בָּרוּךְ הוּא דָן אֶת כָּל הָעוֹלָם, הָכִי נִשְׁמָתָא דָּנָה אֶת גּוּפָא,</p>\n<p>וְרָזָא דְנִשְׁמָתָא דְאִיהִי שָׁוָה לְקוּדְשָׁא בְּרִיךְ הוּא, דָּא בִינָה, מִ\"י, וַעֲלָהּ אִתְּמַר (ישעיה מ כה) וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוְה, אֶל מִי וַדַּאי, וְהָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, חֲמִשָּׁה דְבָרִים אִלֵּין, חֲמִשָּׁה וַדַּאי, בְּגִין דְּאִינוּן מִסִּטְרָא דְה' עִלָּאָה.</p>\n<p>וְאִינוּן כֻּלְּהוּ תִקּוּנִין בְּלֵב, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין הַלֵּב מֵבִין, הַלֵּב רוֹאֶה, הַלֵּב שׁוֹמֵעַ, הָא תְּלַת, ה' אִיהִי חָמֵשׁ, וְרוּחָא דְפִימָא דְסָלִיק בָּהּ קָלָא וַאֲמִירָה וְדִבּוּרָא דָא ו', עַרְקִין דְּלִבָּא אִינוּן כַּחֲיָילִין בָּתַר מַלְכֵהוֹן,</p>\n<p>וְרָזָא דְמִלָּה (יחזקאל א יב) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ, הָכִי מִתְנַהֲגִין עַרְקִין דְּלִבָּא לְגַבֵּי רוּחָא הֲרֵי לָךְ רוּחַ בְּלֵב, דְּנָפִיק מֵאֹזֶן שְׂמָאלָא דְלִבָּא, וְאִיהוּ הֲוָה רוּחַ צְפוֹנִית דְּבָטַשׁ בְּכִנּוֹר דְּדָוִד, וּבְהַאי רוּחָא הֲוָה בָטַשׁ בְּחָמֵשׁ נִימִין דְּכִנּוֹר, דְּאִינוּן חָמֵשׁ כַּנְפֵי רֵיאָה,</p>\n<p>וּבְקָנֶה סָלִיק קוֹל לְלִבָּא, וְאִיהוּ אֵשׁ אוֹכְלָא, מֵאוּדְנָא יְמִינָא דְלִבָּא דְאִיהִי כְּלַפֵּי כָּבֵד, וּמִנֵּיהּ נָפִיק דִּבּוּר, הֲדָא הוּא דִכְתִיב (ירמיה כג כט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ, וְאִי לַאו כַּנְפֵי רֵיאָה דְנָשְׁבִין עַל לִבָּא, הֲוָה אוֹקִיד כָּל גּוּפָא,</p>\n<p>מַחֲשָׁבָה בְּלִבָּא וְדָא י',</p>\n<p>דְּה' ה' אִנּוּן אֲמִירָה וְדִבּוּרָא, ו' קָלָא כְלִיל כֹּלָּא.</p>\n<p>רְבִיעָאָה בְּמִזְמוֹר, וְדָא הוּא דְרוֹעָא יְמִינָא, הֲדָא הוּא דִכְתִיב (תהלים צח א) מִזְמוֹר שִׁירוּ לַיְיָ' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה הוֹשִׁיעָה לּוֹ יְמִינוֹ, וַעֲלָהּ אִתְּמַר (שם ס ז) הוֹשִׁיעָה יְמִינְךָ,</p>\n<p>וְאִיהוּ בְגָלוּתָא עִם שְׁכִינְתָּא, וְאִיהוּ תְמִיךְ לָהּ, וְרָזָא דְמִלָּה (ישעיה נג א) וּזְרוֹעַ יְיָ' עַל מִי נִגְלָתָה,</p>\n<p>וּבֵיהּ אוֹמָאָה דְפוּרְקָנָא, הֲדָא הוּא דִכְתִיב (שם סב ח) נִשְׁבַּע יְיָ' בִּימִינוֹ וּבִזְרוֹעַ עְִזוֹ, וְעוֹד (רות ג יג) חַי יְיָ' שִׁכְבִי עַד הַבֹּקֶר.</p>\n<p>וְאַמַּאי אִתְקְרֵי זְרוֹעַ יְיָ', בְּגִין דְּכַף הַיָּד בֵּיהּ י', חָמֵשׁ אֶצְבְּעָאן ה', קָנֶה דִימִינָא דְאִיהוּ דְרוֹעָא ו', כָּתֵף בֵּיהּ ה', וְדָא עַמּוּדָא דְאֶמְצָעִיתָא דְאִתְקַשַּׁר בִּימִינָא, לְאַקָּמָא בֵּיהּ שְׁכִינְתָּא בְגָלוּתָא,</p>\n<p>וּמֹשֶׁה דְאִיהוּ דִיּוֹקְנָא דְעַמּוּדָא דְאֶמְצָעִיתָא, אִתְּמַר בֵּיהּ (ישעיה סג יב) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ, וְאִיהוּ בּוֹקֵעַ מַיָּא דְאוֹרַיְיתָא לְגַבֵּי זֶרַע אַבְרָהָם דְּאִיהוּ יְמִינָא, לְמֶהֱוֵי לֵיהּ שֵׁם עוֹלָם,</p>"],[9500011056,"<p>וְאִתְקַשַּׁר בְּה' דְּאַבְרָהָם, דְּאִיהוּ חֲמִשָּׁה חוּמְשֵׁי תוֹרָה, וּבָהּ אִשְׁתַּלִּים מֹשֶׁה, וּמִיָּד דְּאִשְׁתַּלִּים אִתְגַּלְיָא עֲלֵיהּ יְמִינָא, וְדָא הוּא (ישעיה נג א) וּזְרוֹעַ יְיָ' עַל מִי נִגְלָתָה.</p>\n<p>חֲמִשָּׁאָה בְּנִגּוּן, בְּגִין דְּהַאי נִיגוּן סָלִיק מִנֵּיהּ כַּמָּה נְגִינוֹת, עוּלֵימָן מִסִּטְרָא דִשְׂמָאלָא, דְּמִתַּמָּן רוּחַ צָפוֹן הֲוָה נָחֲתָא בְכִנּוֹר דָּוִד וַהֲוָה מְנַגֵּן מֵאֵלָיו, הֲדָא הוּא דִכְתִיב (מלכים ב ג טו) וְהָיָה כְּנַגֵּן הַמְנַגֵּן וְגוֹמֵר.</p>\n<p>וּמִתַּמָּן רְעַמִין נָפְקִין, הֲדָא הוּא דִכְתִיב (איוב כו יד) וְרַעַם גְּבוּרוֹתָיו מִי יִתְבּוֹנָן,</p>\n<p>וּמִתַּמָּן (ישעיה כד יט) רֹעָה הִתְרֹעֲעָה הָאָרֶץ בִּתְרוּעָה, מִסִּטְרָא דְמַטֶּה כְּלַפֵּי חֶסֶד, מוֹט הִתְמוֹטְטָה אָרֶץ בִּתְקִיעָה, פּוֹר הִתְפּוֹרְרָה אֶרֶץ בִּשְׁבָרִים,</p>\n<p>בְּהַהוּא זִמְנָא תְּלַת אֲבָהָן מִתְקַשְּׁרִין בִּגְבוּרָה, וְאִתְעֲבִידוּ בָהּ תְּרוּעָה שְׁבָרִים תְּקִיעָה, וּבְהוֹן רֹעָה הִתְרוֹעֲעָה וְגוֹמֵר, וְדָא יְהֵא בְסוֹף יוֹמַיָּא, וְכָל אָתִין אִלֵּין בְּאַרְעָא דְיִשְׂרָאֵל יְהוֹן, בְּגִין דְּתַמָּן חֶבְרוֹן דַּאֲבָהָן תַּמָּן קְבוּרִים.</p>\n<p>שְׁתִיתָאָה הַלְלוּיָהּ הַלְלוּהוּ וְדָא ה\"ו, עֲלֵיהּ אִתְּמַר (שמות יב מב) לֵיל שִׁמּוּרִים הוּא לַיְיָ', וְדָא אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְרָזָא דְמִלָּה (ירמיה לא ו) הַשְׁמִיעוּ הַלְלוּ, וְאִמְרוּ הוֹשַׁע יְיָ' אֶת עַמְּךָ אֵת שְׁאֵרִית יִשְׂרָאֵל, לְקַיֵּים קְרָא (מיכה ז טו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>וְרָזָא דְמִלָּה (קהלת א ט) מַ\"ה שֶּׁ\"הָיָה ה\"וּא שֶׁ\"יִּהְיֶה, וּבֵיהּ (תהלים לג יד) מִ\"מְּכוֹן שִׁ\"בְתּוֹ הִ\"שְׁגִּיחַ, בְּגִין דְּאִיהוּ דִיּוֹקְנָא דְעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>בְּהַהוּא זִמְנָא אִתְקַיַּים רָזָא דְמַתְנִיתִין דְּאָמַר אוֹכְלִין כָּל אַרְבַּע, וְתוֹלִין כָּל חָמֵשׁ דְּהַיְינוּ אֶלֶף חֲמִשָּׁאָה, וְשׂוֹרְפִין בִּתְחִלַּת שֵׁשׁ דְּאִיהוּ אֶלֶף שְׁתִיתָאָה.</p>\n<p>וּבְגִין דְּלָא יַפְרִישׁוּ בֵּין שֵׁשׁ דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וּבֵין שֶׁבַע דְּאִיהִי בַת זוּגֵיהּ, צָרִיךְ לְבַעֲרָא שְׂאוֹר וְחָמֵץ דְּאִינוּן עִרֶב רַב, דְּלָא יִתְחַזְיָין בֵּין שֵׁשׁ דְּאִיהוּ ו', וּבֵין שֶׁבַע דְּאִתְּמַר בָּהּ (שם קיט קסד) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךָ,</p>\n<p>בְּגִין דְּעִרֶב רַב אַפְרִישׁוּ בֵּין שֵׁשׁ לְשֶׁבַע בְּמַתַּן תּוֹרָה, כְּמָה דְאַתְּ אָמַר (שמות לב א) וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה, וְאוּקְמוּהוּ בַשֵּׁשׁ, בְּאִלֵּין שִׁית שַׁעִִתִּין עֲבַדוּ יָת עִִגְלָא, וְאַפְרִישׁוּ בֵּין ו\"ה דְּאִינוּן שֵׁשׁ לְשֶׁבַע, הָכִי יַפְרִישׁ לוֹן קוּדְשָׁא בְּרִיךְ הוּא בֵּין שֵׁשׁ לְשֶׁבַע.</p>\n<p>דִּבְגִינַיְיהוּ הֲוַת מַצָּה פְּרוּסָה לֶחֶם עֹנִי עָנִי וַדַּאי,</p>\n<p>וּבְהַהוּא זִמְנָא תְּהֵא שְׁלֵימָה כְּגַוְונָא דַחֲבֵרְתָּה דְאִיהִי מַצָּה שְׁלֵימָה, הֲדָא הוּא דִכְתִיב (ישעיה ל כו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה,</p>\n<p>וְאַמַּאי הֲוַת מַצָּה פְּרוּסָה, בְּגִין דְּאִסְתַּלַּק מִנָּהּ ו' רֶגֶל דִּילָהּ לְמֶהֱוֵי בֵּיהּ כְּמִצְוָה, וּמַצָּה פְּרוּסָה אִשְׁתְּאָרַת ד', וּבְגִין דָּא מַצָּה פְּרוּסָה ד', מַצָּה שְׁלֵימָה ה',</p>\n<p>וּבְגִין דָּא אָמְרִין הַלֵּל גָּמוּר וְהַלֵּל שֶׁאֵינוֹ גָמוּר בַּפֶּסַח, לָקֳבֵל מַצָּה שְׁלֵימָה וּמַצָּה פְּרוּסָה.</p>\n<p>וְאָמְרִין מָרוֹר, עַל שֵׁם ו' דְּאִתְפַּרַשׁ מִן ה', וְדָא גָרִים לוֹן דְּוַיְמָרְרוּ אֶת חַיֵּיהֶם, אִיהוּ מָרוֹר וְאִיהִי מָרָה, הֲדָא הוּא דִכְתִיב (רות א כ) קְרֶאןָ לִי מָרָה כִּי הֵמַר שד\"י לִי, בַּעֲבוֹדָה קָשָׁה בְּקֻשְׁיָא, בְּחֹמֶר בְּקַל וָחֹמֶר, בֵּין אוּמִין דְּעָלְמָא.</p>\n<p>וּמָאן גָּרִים דָּא, י' מִן שד\"י רְשִׁימוּ דִבְרִית, דְּיָהִיב מֹשֶׁה בְּעִרֶב רַב,</p>\n<p>בְּגִין דָּא נָחִית מֹשֶׁה מִדַּרְגֵּיהּ, הֲדָא הוּא דִכְתִיב (שמות לב ז) לֶךְ רֵד כִּי שִׁחֵת עַמְּךָ, עַמְּךָ וְלֹא עַמִּי,</p>\n<p>וְעַל יָדֵיהּ עֲתִידָה שְׁכִינְתָּא לְיַחֲדָא עִם קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּאִיהוּ אַפְרִישׁ לוֹן, צָרִיךְ לְיַחֲדָא לוֹן, לְתַקְנָא בַּמֶּה דְחָאב,</p>\n<p>קָמוּ כֻלְּהוּ חַבְרַיָּא וְנָשְׁקוּ לֵיהּ, וְאָמְרוּ אִי לָא אָתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע דָּא דַי.</p>\n<p>שְׁבִיעָאָה בְּנִצּוּחַ דְּאִיהוּ נֶצַח יִשְׂרָאֵל, וַעֲלֵיהּ אִתְּמַר (שמואל א טו כט) וְגַם נֵצַח יִשְׂרָאֵל לֹא יְשַׁקֵּר, וַעֲלֵיהּ אִתְּמַר (תהלים כב א) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר, לַמְנַצֵּחַ עַל הַשְּׁמִינִית (שם יב א), מָאן שְׁמִינִית הוֹד, וְאִיהוּ נֶצַח עֲלֵיהּ.</p>\n<p>תְּמִינָאָה בְּהוֹדָאָה, וּבֵיהּ הֲוָה מְשַׁבַּח דָּוִד הוֹדוּ לַיְיָ', וְדָא הוֹד וַדַּאי, לַמְנַצֵּחַ הוֹדוּ, בְּהוֹן רְמִיזִין נֶצַח וָהוֹד, וְאִינוּן נִסִּין,</p>\n<p>וּבֵיהּ שַׁבַּח מֹשֶׁה אָז, הֲדָא הוּא דִכְתִיב (שמות טו א) אָז יָשִׁיר מֹשֶׁה, בְּגִין דְּאִיהוּ הוֹד דִּיְהִיב לְמֹשֶׁה, (ישעיה נח ז) אָז תִּקְרָא וַיְיָ' יַעֲנֶה,</p>\n<p>וְאִיהוּ תְּמַנְיָא יוֹמִין דְּמִילָה, וּבַתְרֵיהּ בְּרִית דְּאִיהוּ יְסוֹד צַדִּיקָא דְעָלְמָא, וּבֵיהּ אִתְגַּלְיָא י'</p>"],[9500011057,"<p>דְּמִילָה, עֲשִׂירָאָה לַעֲשַׂר סְפִירָן,</p>\n<p>וְאִיהוּ הוֹד תְּמַנְיָא יוֹמֵי דַחֲנוּכָּה, לְאַרְבָּעָה וְעִִשְׂרִין יוֹמִין, דְּאִינוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד,</p>\n<p>וּמִיָּד דַּעֲלֵה זַיִת טָרָף בְּפִיהָ, שַׁרְיָא כ\"ה עַל יִשְׂרָאֵל בְּכ\"ה בְּכִסְלֵו, וְאִלֵּין אִינוּן כ\"ה אַתְוָון דְּיִחוּדָא, דְאִינוּן שְׁמַע יִשְׂרָאֵל וְגוֹמֵר, וְדָא אִיהוּ חֲנוּכָּ\"ה חֲנ\"וּ כָּ\"ה.</p>\n<p>אֲבָל נֶצַח אִתְּמַר בֵּיהּ (בראשית ח ד) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, בְּגִין דְּנֶצַח בֵּיהּ רְמִיז נֹחַ צַדִּיק,</p>\n<p>וּבֵיהּ וְהַמַּיִם גָּבְרוּ מְאֹד (שם ז יט), כַּד לָא נָטְרִין יִשְׂרָאֵל בְּרִית מִילָה מִתְגַּבְּרִין אוּמִין דְּעָלְמָא דְּאִינוּן הַמַּיִם הַזֵּדוֹנִים, וְכַד נָטְרִין לֵיהּ אִתְּמַר בְּהוֹן (שם ח ה) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, עַד הַחֹדֶשׁ הָעֲשִׂירִי דָּא י' דְּמִילָה, דְאִיהִי מַלְכוּת, עֲשִׂירָאָה לַעֲשַׂר סְפִירָן.</p>\n<p>וְיַעֲקֹב בְּהַהִיא יַרְכָא אִתְּמַר בֵּיהּ (שם לב לב) וְהוּא צוֹלֵעַ עַל יְרֵכוֹ, דְפָרַח מִנֵּיהּ י', וְאִשְׁתָּאַר עָקֵב, וְרָזָא דְמִלָּה הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב (שם ג טו),</p>\n<p>כַּד אִשְׁתַּלִּימַת סוּכָּה בְיֶרֵךְ דִּילָהּ, אִתְּמַר בְּיַעֲקֹב (שם לג יח) וַיָּבֹא יַעֲקֹב שָׁלֵם, וְיַעֲקֹב וַדַּאי אִיהוּ דִיּוֹקְנָא דְעַמּוּדָא דְאֶמְצָעִיתָא מִסִּטְרָא דִּלְבָר, וְהָא מֹשֶׁה תַמָּן הֲוָה, אֶלָּא מִסִּטְרָא דִלְגָאו הֲוָה, דָּא מִגּוּפָא, וְדָא מִנִּשְׁמָתָא, וּבְגִין דָּא תְרֵין יַרְכִין דְּעַמּוּדָא דְאֶמְצָעִיתָא שְׁלִים אִינוּן נֶצַח וָהוֹד.</p>\n<p>וּמָתַי יִהְיֶה עַמּוּדָא דְאֶמְצָעִיתָא שְׁלִים, כַּד אִתְחַבַּר בִּשְׁכִינְתָּא, הֲדָא הוּא דִכְתִיב (שם יז) וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת, הֲדָא הוּא דִכְתִיב (שם ב כב) וַיִּבֶן יְיָ' אלהי\"ם אֶת הַצֵּלָע,</p>\n<p>בְּהַהוּא זִמְנָא דְאִתְחַבַּר עִמָּהּ, וַיָּבֹא יַעֲקֹב שָׁלֵם (שם לג יח), בְּהַהוּא זִמְנָא תְהֵא סוּכָּה שְׁלֵימָתָא, כ\"ו ה\"ס, יאהדונה\"י.</p>\n<p>קָם רַבִּי אֶלְעָזָר וְאָמַר, אַבָּא אַבָּא, אַמַּאי אִתְּמַר בְּיוֹמָא קַדְמָאָה דְסֻכּוֹת, וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עִץ הָדָר (ויקרא כג ג),</p>\n<p>אָמַר לֵיהּ בְּרִי מָאנֵי קְרָבָא בִּימִינָא נָטְלִין לוֹן, וּבְאִלֵּין מָאנֵי קְרָבָא אִינוּן יִשְׂרָאֵל רְשִׁימִין דְּנָצְחִין דִּינָא,</p>\n<p>מְתַל לְמַלְכָּא דַהֲוָה לֵיהּ דִּינָא וּקְרָבָא בְּשַׁבְעִין אוּמִין, וְלָא הֲווֹ יָדְעִין מָאן נָצַח דִּינָא, וְשָׁאֲלִין לֵיהּ מָאן נָצַח דִּינָא אָמַר תִּסְתַּכְּלוּן בְּאִלֵּין דִּרְשִׁימִין בְּמָאנֵי קְרָבָא בִידַיְיהוּ, וְתִנְדְּעוּן מָאן נָצַח דִּינָא,</p>\n<p>וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן פְּרִי עִץ הָדָר דָּא אֶתְרוֹג, דְּאִיהִי שְׁכִינְתָּא, לִבָּא, דְּאִיהוּ עִקָּרָא דְכָל אֵבָרִין דְּגוּפָא, דְּאִינוּן תְּלַת הֲדַסִּים, וְלוּלָב וּתְרֵי בַדֵּי עֲרָבָה, לִבָּא בְאֶמְצָעִיתָא, וְאֵבָרִין סְחוֹר סְחוֹר לֵיהּ, וּבְגִין דָּא אֶתְרוֹג דָּא שְׁכִינְתָּא,</p>\n<p>וְהָכִי אוּקְמוּהָ מָארֵי מַתְנִיתִין, אִי נִטְּלָה בּוּכְנָתוֹ, וְאִי עָלָה חֲזָזִית עַל רוּבּוֹ, פָּסוּל, בְּגִין דְּאִיהוּ דָמֵי לִשְׁכִינְתָּא, דְאִתְּמַר בָּהּ (שיר ד ז) כֻּלָּךְ יָפָה רַעִִיָתִי וּמוּם אֵין בָּךְ.</p>\n<p>כַּפֹּת תְּמָרִים דָּא לוּלָב, וַעֲלֵיהּ אִתְּמַר נִפְרְצוּ עַלָּיו פָּסוּל, בְּגִין דְּדָא אִיהוּ מְקַצֵּץ בִּנְטִיעוֹת, מָאן דִּמְבָרֵךְ עֲלָהּ בְּיוֹמָא קַדְמָאָה דְסֻכּוֹת, בְּגִין דְּאִיהוּ קִשּׁוּרָא וְיִחוּדָא דְכֹלָּא, חַ\"י עָלְמִין, דְּאִיהוּ לָקֳבֵל חַ\"י חוּלְיָין דְּשִׁדְרָה, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, לוּלָב דּוֹמֶה לְשִׁדְרָה,</p>\n<p>וְרָזָא דְלוּלָב צַדִּיק כַּתָּמָר יִפְרָח, וְדָא אִיהוּ (דה\"י א כט יא) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵם אֻנְקְלוֹס דַּאֲחִיד בִּשְׁמַיָּא וּבְאַרְעָא.</p>\n<p>וְצָרִיךְ לְנַעִִנְעָא חַ\"י נִעִִנוּעִין בְּשִׁית סִטְרִין, דְּאִינוּן חוֹתָם מִזְרָח בְּיה\"ו וכו', שִׁית הֲוַיּוֹ\"ת דְּאִית בְּהוֹן תַּמְנֵי סְרֵי אַתְוָון, וְכֻלְּהוּ רְמִיזִין בְּסֵפֶר יְצִירָה בְּשִׁית סִטְרִין,</p>\n<p>וְהָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין, מוֹלִיךְ וּמֵבִיא לְמָאן דְּאַרְבַּע רוּחוֹת הָעוֹלָם דִּילֵיהּ, מַעֲלֶה וּמוֹרִיד לְמָאן דִּשְׁמַיָּא וְאַרְעָא דִילֵיהּ.</p>\n<p>תְּלַת הֲדַסִּין גּוּף וּתְרֵין דְּרוֹעִין, וְאִינוּן לָקֳבֵל עִינָא וְכַנְפֵי עִינָא, תְּרֵי בַדֵּי עֲרָבוֹת לָקֳבֵל תְּרֵין שׁוֹקִין, וְלָקֳבֵל תְּרֵין שִׂפְוָון,</p>\n<p>וְכַד אִינוּן כֻּלְּהוּ אֲגוּדָה חֲדָא בְּלוּלָב דְּאִיהוּ שִׁדְרָה, מַה כְּתִיב (שיר השירים ז ט) אָמַרְתִּי אֶעֱלֶה בְתָמָר, א' אֶתְרוֹג ע' עֲרָבָה ל' לוּלָב ה' הֲדַס, כֻּלְּהוּ אִתְעֲבִידוּ לָקֳבֵל אַרְבַּע מִינִין דְּמֶרְכַּבְתָּא, הָרוֹכֵב בְּהוֹן אִיהוּ יהו\"ה</p>"],[9500011058,"<p>וְצָרִיךְ לְסַדְרָא בְּהוֹן בְּהַקָּפָה, כְּגַוְונָא דְמִזְבֵּחַ, וּלְמָאן לְגַן, דְּאִתְנַטְעוּ אִלֵּין נְטִיעִין בֵּיהּ,</p>\n<p>וְרָזָא דְמִלָּה נְקֵבָה תְּסוֹבֵב גָּבֶר (ירמיה לא כא), נְקֵבָה נ' מִן גַּן, גָּבֶר ג' מִן גַּן, גַּ\"ן הוּא כְלִיל תְּלַת וְחַמְשִׁין סִדְרִין דְּאוֹרַיְיתָא דְבִכְתָב, וְשֶׁבַע יוֹמִין דְּסוּכּוֹת, הָא שִׁתִּין לָקֳבֵל שִׁתִּין מַסֶּכְתּוֹת.</p>\n<p>שְׁמִינִי עֲצֶרֶת חַג בִּפְנֵי עַצְמוֹ, בֵּיהּ נְבִיעוּ דְאוֹרַיְיתָא, לְאַשְׁקָאָה אִילָנָא, דְאִיהוּ נָטוּעַ בְּגַן, וְשָׁרְשׁוֹי וְעַנְפּוֹי אִיהוּ, כְּגַוְונָא דְחוּג הָאָרֶץ (ישעיה מ כב), דְּכָל חַגִּין מִתְחַגְּגִין בָּהּ.</p>\n<p>תְּשִׁיעָאָה בְּרִנָּה וְדָא אִיהוּ רַנֲנוּ צַדִּיקִים בַּיְיָ' (תהלים לג א), וְדָא דַרְגָּא דְצַדִּיק חַ\"י עָלְמִין, מִתַּמָּן רִנָּה, וּבֵיהּ פּוּרְקָנָא, הֲדָא הוּא דִכְתִיב (ירמיה כג ה) צֶמַח צַדִּיק, (זכריה ו יב) וּמִתַּחְתָּיו יִצְמָח, מִתַּחְתָּיו וַדַּאי, הַהִיא דְאִיהִי עֲשִׂירִית לְכֹלָּא,</p>\n<p>וְצַדִּיק נָטִיל מִשְּׂמָאלָא, וְעַמּוּדָא דְאֶמְצָעִיתָא מִימִינָא, הֲדָא הוּא הוּא דִכְתִיב (דברים לג ב) מִימִינוֹ אֵשׁ דָּת לָמוֹ.</p>\n<p>בְּהַהוּא זִמְנָא דִיְהוֹן תְּרֵין שְׁמָהָן כַּחֲדָא, אִתְעֲרָא בְּרַתָּא דְמַלְכָּא, בְּשִׁיר הַשִּׁירִים וּמִשְׁלֵי וְקֹהֶלֶת, דְּאִינוּן (מ\"א ה יב) שְׁלֹשֶׁת אֲלָפִים מָשָׁל, תְּלַת יוּדִי\"ן, דְּאִינוּן תְּלַת טִפִּין דְּמוֹחָא, דְנָחֲתִין מִן י', וּלְאָן אִתְמַשְׁכוּ לְגַבֵּי צַדִּיק, דְּאִיהוּ קֶשֶׁת הַבְּרִית וּמַה דַּהֲוָה קָטָן אִתְעֲבִיד גָּדוֹל,</p>\n<p>וְרָזָא דְמִלָּה שׁוֹפָר הוֹלֵךְ פָּזֵר גָּדוֹל, מָתַי יְהֵא זָרִיק חֵץ בְּדִיּוֹקְנָא דָא. [ציור].</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עִלָּאִין אִתְתַּקְנוּ וְאִזְדַּרְזוּ בְּמָאנֵי קְרָבָא לְגַבֵּי חִוְיָא, דְאִיהוּ מְקַנְּנָא בְּטוּרִין רַבְרְבִין, וְאִיהוּ קָטִיל לְאָדָם קַדְמָאָה, וּלְכָל דָּרִין דַּהֲווֹ אַבַּתְרֵיהּ,</p>\n<p>וּבְגִין דָּא כָּרוֹזָא נָפִיק בְּכָל יוֹמָא, מָאן דְּקָטִיל הַהוּא חִוְיָא דְאִיהוּ מְקַנְּנָא בְּטוּרִין רַבְרְבִין, יָהֲבִין לֵיהּ בְּרַתָּא דְמַלְכָּא, דְאִיהִי צְלוֹתָא, דִיְתִיב עַל מַגְדְּלָא, דְאִתְּמַר בָּהּ (משלי יח י) מִגְדַּל עֹז שֵׁם יְיָ' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב.</p>\n<p>אַדְהָכִי הָא רַעִִיָא מְהֵימְנָא קָא אָתֵי, בְּכַמָּה עָאנִין וְתוֹרִין וְאִמְרִין, וְחוּטְרָא בִידֵיהּ, סָלִיק עִינֵיהּ לְמַגְדְּלָא, וְחָמָא חַד בַּר נַשׁ עוּלֵימָא צַדִּיק שְׁמֵיהּ, דַּהֲוָה יְתִיב עַל מַגְדְּלָא, קַשְׁתָּא בִּידוֹי, וַהֲוָה זָרִיק חִצִּים לְגַבֵּי חִוְיָא, וְדָא אִיהוּ פָּזֵר גָּדוֹל,</p>\n<p>וְחִוְיָא לָא הֲוָה חָשִׁיב לוֹן.</p>\n<p>וְקַשְׁתָּא אִיהוּ לִישָׁנָא דְפוּמָא, אֱגוֹזָא דְקַשְׁתָּא דְפוּמָא, חוּט הַשָּׁנִי חוּט שֶׁל קֶשֶׁת, דְּבֵיהּ הֲוָה צַדִּיק זָרִיק חִצִּין, דְּאִינוּן מִלּוּלִין דִּצְלוֹתָא, לְגַבֵּי חִוְיָא,</p>\n<p>וְחִוְיָא לָא הֲוָה חָשִׁיב לוֹן,</p>\n<p>וְלַאו בְּגִין חֲלִישׁוּ דְצַדִּיק חַ\"י עָלְמִין, אֶלָּא בְּגִין חֲלִישׁוּ דְהַהוּא דְזָרִיק לוֹן דְּאִיהוּ צַדִּיק דִּלְתַתָּא מִנֵּיהּ, כַּד לַאו אִיהוּ שְׁלִים, וּבְגִין דָּא לָא חָשִׁיב לוֹן.</p>\n<p>עַד דְּאָתָא רַעִִיָא מְהֵימְנָא, וְנָטִיל חֵץ חַד וְזָרִיק לְגַבֵּיהּ, דָּא בָּתַר דָּא בִּצְלוֹתֵיהּ, (שם ז כג) עַד יְפַלַּח חֵץ כְּבֵדוֹ דְחִוְיָא,</p>\n<p>דְּאִיהוּ סמא\"ל אֵל אַחֵר, דְּתַמָּן יְסוֹדֵיהּ וְעִקָּרֵיהּ, וּבְגִין דָּא הַכָּבֵד כּוֹעִס, בְּמַאי כּוֹעִס, בְּמָרָה דְאִיהִי דְבוּקָה בֵּיהּ, וְדָא סַם הַמָּוְת נוּקְבָא דִילֵיהּ, זְנָבָא דִילֵיהּ יוֹתֶרֶת הַכָּבֵד, יוֹתֶרֶת אִתְקְרִיאַת, דְּבָתַר דַּעֲבִידַת נִאוּפִין יְהִיבַת שִׁיּוּרִין לְבַעִִלָהּ,</p>\n<p>וּזְנָבָא אִיהִי שִׁפְחָה דִילֵיהּ, בְּמָרָה כָעִיס, וּבִזְנָבָא קָטִיל, מָרָה אִיהִי פַרְצוּף דִּילֵיהּ, יוֹתֶרֶת זָנָב דִּילֵיהּ,</p>\n<p>כְּגַוְונָא דְאָדָם, דְּעָבִיד לֵיהּ פַּרְצוּף וּלְבָתַר זָנָב, דְּהַאי אָדָם רָע אִתְקְרֵי, וְדָא כְּגַוְונָא דְּדָא, דָא אָדָם דְּאִתְנַטִּיל מֵאִילָנָא דְחַיֵּי, וְדָא אָדָם דְּאִתְנַטִּיל מֵאִילָנָא דְמוֹתָא.</p>\n<p>לְבָתַר דִּיְפַלַּח חֵץ כְּבֵדוֹ, זֶרַע יוֹרֶה כַּחֵץ לְגַבֵּי כַלָּה, יוּ\"ד זֶרַע דְּאִתְמַשֵּׁךְ מִינֵיהּ וְדָא ז', וְאִתְּמַר בָּהּ (שמואל א ב כ) לְשַׁלַּח לִי לְמַטָּרָה, וְדָא בַת עַיִן, בֵּית קִבּוּל לְזֶרַע דְּאִיהוּ ז' וַדַּאי,</p>\n<p>מַאי מַטָּרָה, דָא יֶרַח בֶּן יוֹמוֹ, [ציור] סִיהֲרָא קַדִּישָׁא, מַטָּרָה אִיהִי וַדַּאי לְבַת עַיִן, נְקוּדָה זְעִירָא מִלְּגָיו, לְגַבָּהּ הֲוָה שָׁלַח חִצִּים בִּרְחִימוּ דְעַיְנִין,</p>\n<p>מַטָּרָה וַדַּאי שְׁכִינְתָּא, דְאִיהִי אֲגִינַת עַל יִשְׂרָאֵל מֵחִוְיָא בִּישָׁא סמא\"ל. וּלְמָאן</p>"],[9500011059,"<p>דְּאִיהִי אֲגִינַת עֲלֵיהּ, אִתְּמַר בֵּיהּ (תהלים צא ה) לֹא תִירָא מִפַּחַד לָיְלָה מֵחֵץ יָעוּף יוֹמָם, בְּאֶבְרָתוֹ יָסֶךְ לָךְ, דָּא אֵבֶר מִן הַחַי, צַדִּיק,</p>\n<p>וְתַחַת כְּנָפָיו תֶּחְסֶּה, אִינוּן ה\"ה, דְּאָת ז' אִיהוּ אֶבְרָתוֹ כָּלוּל י\"ו, גּוּפָא דִילֵיהּ ו', רֵישָׁא דִילֵיהּ י', גַּדְפוֹי ה\"ה, וּבְגִין דָּא וְתַחַת כְּנָפָיו תֶּחְסֶּה</p>\n<p>צִנָּה וְסוֹחֵרָה אֲמִתּוֹ, צִנָּה וְסוֹחֵרָה שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, אֲמִתּוֹ דָא עַמּוּדָא דְאֶמְצָעִיתָא, רֵישָׁא דִילֵיהּ חָכְמָה עִלָּאָה, צַדִּיק אִיהוּ בְצַלְמוֹ כִּדְמוּתוֹ,</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּנָטִיר בְּרִית מִילָה, וְאוֹרַיְיתָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, דְּתַרְוַיְיהוּ מְגִינִין עֲלֵיהּ, חַד בְּעָלְמָא דָא, וְחַד בְּעָלְמָא דְאָתֵי.</p>\n<p>בְּרֵאשִׁית, עֲלָהּ אִתְּמַר (שמות כג יט) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית יְיָ' אלהי\"ך, לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ,</p>\n<p>תָּא חֲזִי חָכְמָה עִלָּאָה עֲלָהּ אִתְּמַר (שם יג כ) קַדֶּשׁ לִי כָל בְּכֹר, דְּכָל בִּכּוּרִים עַל שְׁמָהּ אִתְקְרִיאוּ, וּשְׁכִינְתָּא מִתַּמָּן אִתְקְרִיאַת בְּכוֹרָה, חָכְמָה וַדַּאי עֲלָהּ אִתְּמַר (יחזקאל מד ל) רֵאשִׁית כָּל בִּכּוּרֵי כֹל,</p>\n<p>וּבְרָא בּוּכְרָא דִילָהּ קַדְמָאָה דְכֹלָּא דָא ו' עַמּוּדָא דְאֶמְצָעִיתָא. בִּכּוּרֵי אַדְמָתְךָ תְּרֵי סַמְכֵי קְשׁוֹט, מַאי אַדְמָתְךָ שְׁכִינְתָּא תַּתָּאָה, וְאִנּוּן כָּל בִּכּוּרֵי כֹל מִסִּטְרָא דְצַדִּיק דְּאִיהוּ כֹל,</p>\n<p>וּשְׁכִינְתָּא אִיהִי אַרְעָא דְבֵיהּ גָּדְלִין וְצָמְחִין אִלָּנִין, דַּעֲלָהּ אִתְּמַר (ירמיהו כג ה) צֶמַח צַדִּיק, דְּאִיהוּ עִץ פְּרִי,</p>\n<p>אִילָנָא רְבָא וּתְקִיף עַמּוּדָא דְאֶמְצָעִיתָא, עִשְׂבִּין וְדִשְׁאִין דְּאִינוּן תַּלְמִידֵי חֲכָמִים מִתַּמָּן צָמְחִין בְּגַן, בְּגִין דְּאִיהִי אוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>וּמָאן אַשְׁקֵי וְרַוִי (נ\"א ורבי) בָהּ אִלָּנִין וְעִשְׂבִּין וְדִשְׁאִין, מַעִִיַן גַּנִּים, דְּאִיהִי חָכְמָה רֵאשִׁית כָּל בִּכּוּרֵי כֹל, וּמֵאַיִן נַפְקָא מַעֲיָנָא דְמַיָּא, מִבֵּית יְיָ', הֲדָא הוּא דִכְתִיב (יואל ד יח) וּמַעִִיָן מִבֵּית יְיָ' יֵצֵא,</p>\n<p>וּבְגִין דָּא (שמות כג יט) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית יְיָ' אלהי\"ך, וְכֵן רֵאשִׁית דְּעָאנֵי וְאִמְּרֵי, הֲדָא הוּא דִכְתִיב (דברים יח ד) וְרֵאשִׁית גֵּז צֹאנְךָ תִּתֶּן לוֹ. וּסְמִיךְ לֵיהּ לְרֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ וכו' לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ, מַאי הַאי לְגַבֵּי הַאי,</p>\n<p>קָם רַבִּי שִׁמְעוֹן עַל רַגְלוֹי, פָּתַח בְּקָלָא סַגִּיא וְאָמַר, אֵלִיָּהוּ אֵלִיָּהוּ נְחֵית הָכָא בִרְשׁוּתָא דְמָארָךְ, וְאַנְהִיר עִינֵהוּ דְאִלֵּין סָבִין בְּהַאי מִלָּה, דְּלָא יֵתוּן לְמֵיכַל בָּשָׂר בֶּחָלָב.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ קָא נָחִית וְלָא אִתְעַכַּב, אָמַר בּוֹצִינָא קַדִּישָׁא, וְהָא רָזָא דָא וַדַּאי אִיהוּ רָזָא דְלֹא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו (דברים כב ו), כַּד בּוּכְרָא דְאִיהוּ יִשְׂרָאֵל עַמּוּדָא דְאֶמְצָעִיתָא, לָא אַתְיָין לֵיהּ לְבֵית יְיָ', חָלָב אִתְעָרַב בְּבִשְׂרָא, וְגָרְמִין לְאִתְעָרְבָא שׁוֹר בַּחֲמוֹר, וְדָא אִיהוּ כִּלְאַיִם מִין דְּלַאו בְּמִינֵיהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֵלִיָּהוּ אֵלִיָּהוּ, וְהָא שׁוֹר אִיהוּ מִסִּטְרָא דְּדַכְיוּ, וַחֲמוֹר מִסִּטְרָא דִמְסָאֲבוּ, דָא אִיהוּ כִּלְאַיִם טַב וּבִישׁ, אֲבָל חָלָב אִיהוּ מִסִּטְרָא דְּדַכְיוּ, וּבִשְׂרָא מִסִּטְרָא דְּדַכְיוּ,</p>\n<p>אָמַר לֵיהּ וַדַּאי הָכִי הוּא, אֲבָל הַאי רָזָא אִשְׁתְּמוֹדָע בִּקְרָא דָא, תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ (בראשית א כד), דְּאַף עַל גַּב דְּאִינוּן מִסִּטְרָא דְּדַכְיוּ, כֻּלְּהוּ אִינוּן דְּכַר וְנוּקְבָא, וְאִינוּן זוּגִין, וּמָאן דְּנָטִיל מִמַּה דְּלַאו אִיהוּ מִינֵיהּ, הַהוּא בַּר דְּאִתְרְכִיב מִתַּרְוַיְיהוּ, עֲלֵיהּ אִתְּמַר (שמות כג יט) לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ.</p>\n<p>אָמַר בּוֹצִינָא קַדִּישָׁא בְּוַדַּאי כְּעַן אִיהוּ מִלָּה בְּדוּכְתָּהָא, וְדָא אִיהוּ בְרִירָא דְמִלָּה, וְדָא אִיהוּ, מְלֵאָתְךָ וְדִמְעֲךָ לֹא תְאַחֵר (שם כב כח), כְּמָה דְאִתְּמַר שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמֵי,</p>\n<p>חוֹבָא דָא דְעָרַב בַּר נַשׁ טִפָּה בּוּכְרָא בְּזִוּוּגָא נִדָּה שִׁפְחָה גוֹיָה זוֹנָה, דָּא גָרִים דְּנָטִיל אַחֵר בַּת זוּגֵיהּ, וְאִיהוּ מִדָּה לָקֳבֵל מִדָּה,</p>"],[9500011060,"<p>וּבְגִין דָּא רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית יְיָ' אלהי\"ך, לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ, דְּהַהוּא בַּר אִיהוּ עִרְבוּבְיָא דְנָפִיק כִּלְאַיִם, מֵאִתְּתָא דְלַאו מִינֵיהּ, דְּאִיהִי כְּנֶגְדּוֹ,</p>\n<p>וּבְגִין דָּא זָכָה עִזֶר, בַּת זוּגֵיהּ דְּאִיהִי עִזֶר לֵיהּ בְּאוֹרַיְיתָא בְּפִקּוּדָא בִּדְחִילוּ וּבִרְחִימוּ, עִזֶר לוֹ בְּעָלְמָא דֵין, וּבְעָלְמָא דְאָתֵי,</p>\n<p>וְאִם לַאו, אָחֳרָא דְלַאו אִיהוּ מִינֵיהּ, אִיהִי כְּנֶגְדּוֹ, לְאוֹבָדָא לֵיהּ מִתְּרֵין עָלְמִין, וְכָל דָּא גְרִים לֵיהּ בְּגִין דְּלָא נָטִיר טִפָּה קַדְמָאָה לְבַת זוּגֵיהּ.</p>\n<p>וְעִם כָּל דָּא אִם חָזַר בִּתְיוּבְתָּא, עֲלֵיהּ אִתְּמַר (ישעיהו ו י) וָשָׁב וְרָפָא לוֹ, וְיָהִיב לֵיהּ בַּת זוּגֵיהּ, דְּאִתְּמַר בָּהּ (משלי ג ח) רִפְאוּת תְּהִי לְשָׁרֶךָ, וְאִיהִי דִיּוֹקְנָא דְאוֹרַיְיתָא, דְאִיהִי אַסְוָותָא וְאִיהִי חַיִּים,</p>\n<p>הֲדָא הוּא דִכְתִיב (שם יח) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, וְאִתְּתֵיהּ אִיהִי בְּדִיּוֹקְנָהָא, הֲדָא הוּא דִכְתִיב (קהלת ט ט) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ, אוֹרַיְיתָא אִיהִי טוֹב, הֲדָא הוּא דִכְתִיב (משלי ד כב) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, וְאִתְּתֵיהּ אִיהִי בְּדִיּוֹקְנָהָא, הֲדָא הוּא דִכְתִיב (שם יח ב) מָצָא אִשָּׁה מָצָא טוֹב,</p>\n<p>סוֹף סוֹף עִִשֶׂר מִלִּין אִתְּמַר בְּהַאי, וְעִִשֶׂר בְּהַאי, וְהָא אוּקְמוּהָ חַבְרַיָּא.</p>\n<p>בְּרֵאשִׁית דָּא יִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב (ירמיה ב ג) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ' רֵאשִׁית תְּבוּאָתֹה, רֵאשִׁית בְּלָא עִרְבוּבְיָא אָחֳרָא, וּבְגִין דְּאִיהוּ קֹדֶשׁ, לָא הֲוָה לֵיהּ הַרְכָּבָה מִמִּינָא אָחֳרָא,</p>\n<p>וּבְגִין דְּאִיהוּ קֹדֶשׁ, לֵית לֵיהּ הַרְכָּבָה דְצָרִיךְ בֵּיהּ נְטִירוּ לְגַבֵּי בַּת זוּגֵיהּ דְּאִיהִי ה', וּבְגִין דָּא רֵאשִׁית תְּבוּאַת ה', לֵית בֵּיהּ פְּגִימוּ, הֲדָא הוּא דִכְתִיב (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, לֵית בֵּיהּ פְּסוֹלֶת, (צריך למהוי נטיר) אִיבָּא דָא לְמַלְכָּא אִתְחָזֵי, וּבְגִין דָּא (ירמיהו ב ג) כָּל אוֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבֹא אֲלֵיהֶם נְאֻם יְיָ'.</p>\n<p>דְּדָא אִיהוּ עִץ הַחַיִּים, דְּאִיבָּא דִילֵיהּ סַם חַיִּים בַּת זוּגֵיהּ, נְטִירָא לֵיהּ בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, עֲלָהּ אִתְּמַר (בראשית ג כב) וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, גַּם לְרַבּוֹת בַּת זוּגֵיהּ, סַם חַיִּים דִּילֵיהּ, וְאִיהוּ נָטִיר לֵיהּ בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, וּמָאן דְּבָעִי לְנַטְלָא בַת זוּגֵיהּ, כְּגוֹן אוּרִיָּה דְאַקְדִּים לְדָוִד, אִתְּמַר בֵּיהּ (ירמיהו ב ג) כָּל אוֹכְלָיו יֶאְשָׁמוּ רָעָה תָּבֹא אֲלֵיהֶם נְאֻם יְיָ'.</p>\n<p>דְּבַת זוּגֵיהּ דְּצַדִּיק אִיהוּ מַצָּה שְׁמוּרָה, לְגַבֵּי מַצָּה שְׁלֵימָה עֲשִׁירָה,</p>\n<p>וּמָאן גָּרִים דָּא לְמֶהֱוִי בַת זוּגֵיהּ מַצָּה שְׁמוּרָה לְגַבֵּהּ, בְּגִין דְּנָטַר טִפָּה דִילֵיהּ, וּמָאן דְּפָגִים טִפָּה דִילֵיהּ, אִתְקְרֵי בַת זוּגוֹ מַצָּה פְּרוּסָה לֶחֶם עֹנִי,</p>\n<p>וְרָזָא דְמִלָּה כָּל מָאן דִּמְזַלְזֵל בְּנַהֲמָא, אוֹ בְּפִירוּרִין דְּנַהֲמָא, דְאִינוּן טִפִּין בְּכַזַּיִת, עֲנִיּוּת קָא רָדִיף אַבַּתְרֵיהּ, אֶלָּא צָרִיךְ לְנַטְרָא טִפִּין דִּילֵיהּ, דְּלָא יְזָרֵיק לוֹן בַּאֲתַר דְּלָא אִצְטְרִיךְ,</p>\n<p>וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, אוֹקִירוּ לִנְשַׁיְיכוּ כִּי הֵיכֵי דְתִתְעַתְרוּ, וְאוֹקִירוּ דִלְהוֹן לְנַטְרָא טִפָּה קַדְמָאָה, דְלָא יַעֲבִיד בָּהּ פְּסוֹלֶת.</p>\n<p>דִּפְסוֹלֶת דְּאַבְרָהָם וְיִצְחָק, גָּרִים לְאוּמָה דְעִשָׂו וְיִשְׁמָעִאל דְּאִשְׁתַּעִִבְּדוּן בִּבְנֵיהוֹן בְּגָלוּתָא, וְנִסְיוֹנָא דִלְהוֹן בְּאֶשָּׁא וְסַכִּינָא, שֵׁזִיב לוֹן מִשְּׂרֵיפָה וְהֶרֶג דִּלְהוֹן.</p>\n<p>יַעֲקֹב בְּגִין דְּלָא הֲוָה בֵיהּ פְּסוֹלֶת, אִתְּמַר בְּזַרְעִיהּ בְּגָלוּתָא (דברים לג כח) וַיִּשְׁכֹּן יִשְׂרָאֵל בֶּטַח בָּדָד עִין יַעֲקֹב, אִתְּמַר הָכָא בֶטַח בָּדָד, וְאִתְּמַר הָתָם בְּמַפְּקָנוּ דְגָלוּתָא (שם לב יב) יְיָ' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר,</p>\n<p>לָא אִתְעָרְבוּן בִּבְנוֹי עִרְבוּבְיָא דְגִיּוֹרִים, וּבְגִין דָּא אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ, דַּעֲלַיְיהוּ דְזֶרַע יַעֲקֹב אִתְּמַר (תהלים פ ט) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ, מַה גֶּפֶן לָא מְקַבְּלָא הַרְכָּבָה מִמִּין אָחֳרָא, כֵּן זַרְעִיהּ הֲווֹ נָטְרִין אוֹת בְּרִית, וְלָא מְקַבְּלִין הַרְכָּבָה מִמִּין אָחֳרָא,</p>\n<p>וְכָל מָאן דְּנָטִיר אוֹת בְּרִית זָכֵי לְמַלְכוּ,</p>"],[9500011061,"<p>כְּגַוְונָא דְיוֹסֵף,</p>\n<p>וְיִשְׂרָאֵל בְּגִין דְּנָטְרִין בְּרִית זָכוּ לְמַלְכוּתָא, וְאִתְּמַר בְּהוֹן כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים, וּמֹשֶׁה בְּגִין דְּנָטַר אוֹת בְּרִית, אִתְּמַר בֵּיהּ (דברים לג ה) וַיְהִי בִישׁוּרוּן מֶלֶךְ, זַכָּאָה אִיהוּ מָאן דְּנָטַר בְּרִית.</p>\n<p>בְּרֵאשִׁית דָּא חַלָּה, הֲדָא הוּא דִכְתִיב (במדבר טו כ) רֵאשִׁית עֲרִיסוֹתֵיכֶם חַלָּה תָּרִימוּ תְרוּמָה, וְהָא אוּקְמוּהוּ דְאָדָם חַלָּתוֹ שֶׁל עוֹלָם הֲוָה, וּמְנָא לָן דְּחַלָּה אִיהוּ רֵאשִׁית, דִּקְרָא אוֹכַח הֲדָא הוּא דִכְתִיב רֵאשִׁית עֲרִיסוֹתֵיכֶם חַלָּה תָּרִימוּ תְרוּמָה לַיְיָ',</p>\n<p>מַאי חַלָּה, אֶלָּא שִׁבְעָה מִינִין אִינוּן, חִטָּה וּשְׂעוֹרָה וְגֶפֶן וּתְאֵנָה וְרִמּוֹן אֶרֶץ זֵית שֶׁמֶן וּדְבָשׁ, דְּהוּא דְבַשׁ תְּמָרִים.</p>\n<p>חִטָּה אִילָנָא אִיהוּ דְאָכִיל מִנֵּיהּ אָדָם קַדְמָאָה, וְאִיהוּ לָא אַפִּיק מִתַּמָּן חַלָּה, וּבְגִין דָּא לָא חָל בֵּיהּ ה', וְשַׁרְיָא בֵיהּ ח' ט', וְגָרִים לֵיהּ מוֹתָא.</p>\n<p>וְחַלָּה אִיהִי שְׁכִינְתָּא, כְלִילָא מִשִּׁבְעָה מִינִין אִילֵין, וּבָהּ חָב אָדָם קַדְמָאָה, טִפָּה דָא י', עִסָּה צָרִיךְ לְאַפָּקָא מִינָהּ חַלָּה, וּמִיָּד חָל עַל הַהִיא טִפָּה, וְיָהִיב לֵיהּ זֶרַע כְּלִיל מִתַּרְוַיְיהוּ דְאִיהוּ ו', וְרָזָא דְמִלָּה הֵ\"א לָכֶם זֶרַע (בראשית מז כז).</p>\n<p>וּבְגִין דָּא חַלָּה וַדַּאי אִיהִי פִּקּוּדָא דְאִתְמַנִּי לְאִתְּתָא, דִּבְגִינָהּ מֵת אָדָם דְּאִיהוּ חַלָּתוֹ שֶׁל עוֹלָם,</p>\n<p>צְרִיכָה אִיהִי לְאַפְרָשָׁא חַלָּה, וּלְאַפָּקָא לָהּ מֵעִסָּתָהּ, דְּאִיהִי טִפָּה דִילָהּ, לְהַחֲזִירָה עַל הָאָדָם.</p>\n<p>אִיהִי אַטְפַת שָׁרְגָּא דִילֵיהּ, דְּאִתְּמַר בֵּיהּ (משלי כ כז) נֵר יְיָ' נִשְׁמַת אָדָם, צְרִיכָה לְאוֹקָדָא לֵיהּ בְּלֵיל שַׁבָּת, בְּאִתְעָרוּ דְשַׁלְהוֹבִין דְּאֶשָּׁא דִרְחִימוּ לְגַבֵּי בַעִִלָהּ, וְרָזָא דְמִלָּה מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה (שיר א ז),</p>\n<p>וְאִתְעָרוּ דְחַמִּימוּתָא דְלֵיל שַׁבָּת, מֵאִתְּתֵיהּ צְרִיכָה בִרְחִימוּ וּדְחִילוּ, וְדָא אִיהוּ אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר (ויקרא יב ב).</p>\n<p>אִיהִי שְׁפִיכַת דָּמִים דְּאָדָם, אִזְדְּרִיקַת דָּמָהּ, וְעַל דָּא צְרִיכָה לְנַטְרָא לֵיהּ מִדַּם נִדָּה,</p>\n<p>וּבְגִין דָּא עַל תְּלַת מִלִּין אִלֵּין נָשִׁים זְהִירוֹת, בַּנִּדָּה וּבַחַלָּה וּבְהַדְלָקַת הַנֵּר,</p>\n<p>עַד כַּאן רָזָא דְחִטָּה, דְמִתַּמָּן חַלָּה, חִטָּ\"ה אִיהוּ רָזָא דְעִִשְׂרִין וּתְרֵין אַתְוָון דְּאוֹרַיְיתָא.</p>\n<p>בְּרֵאשִׁית, עֲלָהּ אִתְּמַר (עי, דברים יח ד) רֵאשִׁית מַעִִשַׂר דְּגָנְךָ, וְדָא מַלְכוּת דְּאִיהוּ מַעֲשֵׂר, וְאִיהִי עֲשִׂירִית לְעִִשֶׂר סְפִירוֹת, וּבְגִינָהּ מְעַשְּׂרִין,</p>\n<p>וּמוֹץ וְתֶבֶן דְּאִינוּן לְבוּשִׁין דְּחִטָּה, בְּהַאי עָלְמָא פְּטוּרִין מִמַּעֲשֵׂר, וּמָאן דְּבָעִי לְאַפָּקָא מַעֲשֵׂר מֵחִטָּה, בָעִי לְנַקְיֵיהּ מִן מוֹץ וְתֶבֶן דְּאִינוּן ח\"ט, וְאִשְׁתְּאָרַת אִיהִי ה' נְקִיָּה, בְּהַהוּא זִמְנָא יְהֵא זָרִיק בָּהּ טִפָּה דְאִיהִי י'. וּכְגַוְונָא</p>\n<p>וּכְגַוְונָא דָא בְּזִווּגָא דְבַר נַשׁ, צָרִיךְ לְנַקָּאָה טִפָּה מֵחֵטְ\"א דְּאִיהוּ יֵצֶר הָרָע, לְמֶהֱוִי זַרְעָא נְקִיָּה בְּה', הֲדָא הוּא דִכְתִיב (בראשית מז כז) הֵ\"א לָכֶם זֶרַע.</p>\n<p>אֲבָל בְּעָלְמָא דְאָתֵי חִטָּה אִיהִי נְקִיָּה, אִיהִי וּלְבוּשָׁה, וְאִיהִי עִִשְׂרִין וּתְרֵין אַתְוָון דְּאוֹרַיְיתָא,</p>\n<p>וּבְגִין דָּא בְּהַמּוֹצִיא, בַּעַל הַבַּיִת צָרִיךְ לְדַקְדֵּק בְּה', לְמֶהֱוִי אִיהִי נְקִיָּה בְלָא פְסוֹלֶת,</p>\n<p>וּתְרֵין עִשּׂוּרִין אִינוּן, דְּאָמַר קְרָא (דברים יד כב) עַשֵּׂר תְּעַשֵּׂר, אַמַּאי אֶלָּא בְגִין לְקַשְׁרָא לָהּ בִּתְרֵין דְּרוֹעִין, דְּאִינוּן כֹּהֵן לֵוִי, דְאִינוּן מַעֲשֵׂר רִאשׁוֹן לְלֵוִי, מַעֲשֵׂר מִן הַמַּעֲשֵׂר לַכֹּהֵן,</p>\n<p>דְּכָל סְפִירָן סָלְקִין לְעִִשֶׂר (בשכינתא), עַד דְּסָלְקִין לְמֵאָה, וְאִיהִי אִתְעֲבִידַת תְּרוּמָה לְכֻלְּהוּ מֵאָה, וּבְגִין דָּא שִׁיעוּר</p>"],[9500011062,"<p>תְּרוּמָה תְּרֵי מִמֵּאָה, לָקֳבֵל תְּרֵין לוּחִין דְּאוֹרַיְיתָא, דְּאִיהִי תוֹרָה דְאִתְיְיהִיבַת בְּאַרְבְּעִין יוֹמִין, וְדָא אִיהוּ תּוֹרָ\"ה מ',</p>\n<p>וּבָהּ אִתְעֲבִידוּ סְפִירָן כֻּלְּהוּ עִִשְׂרוֹנִים, תְּלַת אֲבָהָן תְּלַת עִִשְׂרוֹנִין, תְּרֵי נְבִיאֵי קְשׁוֹט אִינוּן עִשָּׂרוֹן עִשָּׂרוֹן.</p>\n<p>בְּרֵאשִׁית בָּרָ\"א שִׁי\"ת, אִינוּן שִׁית דַּרְגִּין דִּנְבוּאָה, דְאִתְּמַר בְּהוֹן (שיר ה טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ,</p>\n<p>וּכְמָה דְאִינוּן שִׁית לְתַתָּא, הָכִי אִינוּן שִׁית לְעִילָא, וְאִינוּן שִׁית סָלְקִין לְשִׁתִּין, בְּאָן אֲתַר, בִּיסוֹ\"ד חַ\"י עָלְמִין,</p>\n<p>אִשְׁתָּאַר י\"ד מִן יְסוֹ\"ד, דָּא שְׁכִינְתָּא תַּתָּאָה, כְּלִילָא מֵאַרְבַּע סְרֵי פִּרְקִין דְיָד, דְּאִינוּן בְּחָמֵשׁ אֶצְבְּעָאן, וְאִינוּן יהו\"ה יו\"ד ה\"א וא\"ו ה\"א, אַרְבַּע סְרֵי אַתְוָון דְּקוּדְשָׁא בְּרִיךְ הוּא, דִכְלִילָן בָּהּ, וְדָא אִיהוּ וּבְיַד הַנְּבִיאִים אֲדַמֶּה (הושע יב יא).</p>\n<p>ס\"ו מִן יְסוֹד, אִנּוּן לָקֳבֵל שִׁית דַּרְגִּין דְּכָרְסַיָּא, דְאִתְּמַר בֵּיהּ (מלכים א י יט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, וְאָת ו' סְלִיק בְּי' דְּאִיהִי עֲטָרָה דִבְרִית לְשִׁתִּין, שִׁית זִמְנִין עִִשֶׂר, וְסָלְקִין לְשִׁתִּין לָקֳבֵל שִׁתִּין גַּלְגַּלִּין דְּסַחֲרִין לְכָרְסַיָּא, וְכָרְסַיָּא תַמָּן שְׁכִינְתָּא. דְאִיהִי דִמְיוֹן וּמַרְאֶה דְכֹלָּא,</p>\n<p>דִּמְיוֹן הָא דְאִתְּמַר וּבְיַד הַנְּבִיאִים אֲדַמֶּה, וַעֲלָהּ אִתְּמַר (במדבר יב ח) וּתְמוּנַת יְיָ' יַבִּיט,</p>\n<p>עַל שֵׁם דְּכָל פַּרְצוּפִין דִּנְבִיאֵי בָּהּ אִינוּן רְשִׁימִין, אִתְקְרֵי דִמְיוֹן,</p>\n<p>וְעַל שֵׁם דְּכָל נְהוֹרִין דִּלְעִילָא מִינָהּ, בָּהּ אִתְחַזְיָין אִתְקְרִיאַת מַרְאֶה, הֲדָא הוּא דִכְתִיב (שם ו) יְיָ' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע,</p>\n<p>בִּסְתִימוּ דְעַיְינִין, אִתְקְרִיאַת מַרְאֶה בַחֲלוֹם, וְרָזָא דְמִלָּה אֲנִי יְשֵׁנָה וְלִבִּי עִר (שיר ה ב), וּבִפְתִיחוּ דְעַיְינִין אִיהוּ מַרְאֶה בְּהָקִיץ,</p>\n<p>וּתְרֵין מְמַנָּן תַּמָּן, חַד סגרו\"ן, וְחַד פתחו\"ן, וּמטטרו\"ן דְּאִתְקְרֵי בְּשֵׁם תַּרְוַיְיהוּ, מְמַנָּא עַל תְּרֵין מַפְתְּחִין אִלֵּין.</p>\n<p>מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִיהִי שְׁכִינְתָּא מַרְאֶה בְּהָקִיץ, וּמֹשֶׁה בְּסִטְרֵיהּ, דִּכְתִיב בֵּיהּ (במדבר יב ח) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת, וּתְמוּנַת יְיָ' יַבִּיט.</p>\n<p>מִסִּטְרָא דְצַדִּיק, דְּאִיהוּ אוֹר הַגָּנוּז לַצַּדִּיקִים לְעָלְמָא דְאָתֵי (נ\"א לעתיד לבא), אִתְקְרִיאַת מַרְאֶה בַחֲלוֹם, וְהוּא דְאִתְחַזְיָא בָּהּ,</p>\n<p>מִסִּטְרָא דְגוּפָא, אִיהוּ יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְנַטִּיל מִתְּרֵין סִטְרִין,</p>\n<p>וְאִיהוּ רָכִיב עַל אַרְבַּע חֵיוָון דְּאִינוּן פְּנֵי אָדָם פְּנֵי אַרְיֵה פְּנֵי שׁוֹר פְּנֵי נֶשֶׁר, יו\"ד ה\"א וא\"ו ה\"א אִתְקְרֵי מִלְּגָאו דְּגוּפָא, וְאִיהוּ אָדָם לָשֶׁבֶת עַל הַכִּסֵּא.</p>\n<p>לְמָאן דְּאִיהוּ אָדָם אִתְחַזְיָא לֵיהּ בִּדְמוּת אָדָם, לְמָאן דְּאִיהוּ כִּשְׁאָר חֵיוָון אִתְחַזְיָא לֵיהּ בִּדְמוּת חֵיוָן דְּכָרְסַיָּא, לְכָל חַד כְּפוּם חֵילֵיהּ,</p>\n<p>וְאַל יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל לֵיהּ, אֶלָּא בִּשְׁכִינְתֵּיהּ, דְּלָא יְכִיל לְאַשָּׂגָא לֵיהּ שׁוּם נָבִיא וְחוֹזֶה אֶלָּא בִשְׁכִינְתָּא,</p>\n<p>וְאִית אָדָם לְעִילָא מֵאָדָם, מִסִּטְרָא דְחָכְמָה, כֹּ\"חַ מָ\"ה וַדַּאי, וְאִתְּמַר בֵּיהּ חָכָם עָדִיף מִנָּבִיא.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְכֻלְּהוּ חַבְרַיָּא, וְאָמַר</p>\n<p>רַעִִיָא מְהֵימְנָא, רַבָּן דְּכָל נְבִיאַיָּא, קוּם אִתְעַר מִשִּׁנְתָךְ, דְּאַנְתְּ אִיהוּ בְּכָל נְבִיאַיָּא כְּגַוְונָא דְשִׁמְשָׁא, דְּסִיהֲרָא וְכֹכָבַיָּא מִנֵּיהּ נָהֲרִין, וְלֵית לוֹן נְהוֹרָא מִסִּטְרָא אָחֳרָא, וּבְזִמְנָא דְאַנְתְּ אִתְכְּנִישַׁת מֵעָלְמָא, אִתְּמַר בְּהוֹן (איוב ג ט) יֶחְשְׁכוּ כֹּכְבֵי נִשְׁפּוֹ,</p>\n<p>קוּם אַנְהִיר נְהוֹרָךְ.</p>\n<p>וְלָא עוֹד, אֶלָּא בְזִמְנָא דְאַנְתְּ אִתְכַּנִּישׁ מִן עָלְמָא, בֵּיתָא דִנְבוּאָה, דְאִתְּמַר בָּהּ (שם ז) לֹא כֵן עַבְדִּי מֹשֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא, אִיהִי סְתִימָא,</p>\n<p>קוּם אַפְתַּח לָהּ, דְּאִיהִי בֵּיתָא עִלָּאָה גְנִיזָא, דְכָל גְּנִיזִין דִּלְעִילָא סְתִימִין דְּמַלְכָּא עִלָּאָה תַּמָּן, וְאַנְתְּ הֲוִית כְּבֶן בַּיִת, בֶּן דְּהַהוּא בֵּיתָא,</p>\n<p>בַּיִ\"ת, ב' אִימָּא</p>"],[9500011063,"<p>עִלָּאָה, י' חָכְמָה אַבָּא, ת' תִּפְאֶרֶת, בֶּן בַּיִת דִּלְעִילָא, וְאַנְתְּ הֲוִית בְּדִיּוֹקְנֵיהּ,</p>\n<p>דִּבְהַהוּא בַּיִת לָא הֲוָה רְשׁוּ לְנָבִיא וְחוֹזֶה לְאַעָלָא תַּמָּן אֶלָּא בִּרְשׁוּ,</p>\n<p>וְאַנְתְּ הֲוִית עָאל בְּלָא רְשׁוּ, כִּבְרָא דְמַלְכָּא דְלֵית תַּמָּן תַּרְעָא סְתִימָא לֵיהּ.</p>\n<p>וְלָא עוֹד, אֶלָּא דִנְבִיאַיָּא אָחֳרָנִין, לָא הֲווֹ עָאלִין לְמֶחמֵי לְמַלְכָּא, אֶלָּא בְשַׁעִִתִּין יְדִיעָאן, וּבְיוֹמִין יְדִיעָאן, כְּגַוְונָא דְאַשְׁכַּחְנָא בְאַהֲרֹן דַּהֲוָה עִלָּאָה מִכֻּלְּהוּ, דְאִתְּמַר בֵּיהּ (ויקרא טז ב) וְאַל יָבֹא בְכָל עִת אֶל הַקֹּדֶשׁ, אֶלָּא בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, כָּל שֶׁכֵּן אָחֳרָנִין, וְאַנְתְּ בְּכָל שַׁעִִתָּא וְשַׁעִִתָּא, וּבְכָל יוֹמָא דְאַנְתְּ בָּעִי הֲוִית עַיִיל לְמֶחזֵי לְמַלְכָּא.</p>\n<p>וְלָא עוֹד, אֶלָּא כָל נְבִיאַיָּא, הֲווֹ חַזְיָין נְבוּאָה דִלְהוֹן בְּאֵבָרִין דְּמַלְכָּא, כָּל חַד וְחַד בְּאֵבֶר יְדִיעָא וְלָא יַתִּיר, מִנְּהוֹן בְּרֵישָׁא דְמַלְכָּא, מִנְּהוֹן בְּנִימִין דְּרֵישָׁא, דְאִנּוּן כֹּכְבַיָּא וּמַזָּלֵי דְלֵית לוֹן חוּשְׁבָּנָא, מִנְּהוֹן בְּעַיְינִין, מִנְּהוֹן בְּאוּדְנִין, מִנְּהוֹן בְּאַנְפִּין, מִנְּהוֹן בְּחוֹטָמָא, מִנְּהוֹן בְּפוּמָא מִנְּהוֹן בְּצַוָּאר, מִנְּהוֹן בְּיָדַיִם, מִנְּהוֹן בְּקוֹמָה דְאִיהוּ גוּפָא, מִנְּהוֹן בְּשׁוֹקִין, מִנְּהוֹן בְּאוֹת בְּרִית, מִנְּהוֹן בִּלְבוּשִׁין דְּמַלְכָּא, דְלָא הֲוָה לוֹן רְשׁוּ לְאִסְתַּכְּלָא יַתִּיר.</p>\n<p>אֲבָל מֹשֶׁה בְּכָל אֵבֶר, וּבְכָל אֲתַר הֲוָה מַשִּׂיג נְבוּאָה דִילֵיהּ, וּבְכָל אֵבֶר וְאֵבֶר אִיהִי הֲוָה נָחֲתָא לְגַבֵּיהּ, מַה דְּלָא הֲוָה הָכִי לִשְׁאָר כָּל נְבִיאַיָּא,</p>\n<p>דְּכָל חַד סְלִיק לְאֵבֶר דִּילֵיהּ, דְּנִשְׁמָתֵיהּ הֲוָה אֲצִילוּת מֵהַהוּא אֵבֶר, וְהַהוּא אֵבֶר הֲוָה לֵיהּ אֲבוֹי.</p>\n<p>וּבְרַתָּא דְמַלְכָּא אִיהִי הֵיכָלָא דְכָל אֵבֶר וְאֵבֶר, מִצְוָה דְכָל אֵבֶר וְאֵבֶר,</p>\n<p>אדנ\"י אִיהוּ כְּחֻשְׁבַּן הֵיכָ\"ל, וּבְגִין דָּא אִתְּמַר (תהלים נא יז) אדנ\"י שְׂפָתַי תִּפְתָּח,</p>\n<p>יהו\"ה אִיהוּ בְּכָל אֵבֶר וְאֵבֶר, אדנ\"י הֵיכָל, יהו\"ה בְּכָל אֵבֶר וְאֵבֶר וְאִיהִי נְבוּאָה דְכָל אֵבֶר וְאֵבֶר, מַרְאֶה דְכָל אֵבֶר וְאֵבֶר אִתְקְרֵי,</p>\n<p>וְכָל אֵבֶר וְאֵבֶר אִית לֵיהּ סְפִירָה יְדִיעָא,</p>\n<p>הֵיכָלָא דְכֻלְּהוּ שְׁכִינְתָּא תַּתָּאָה אדנ\"י, וְכַמָּה מְמַנָּן נְטוּרֵי תַרְעִין אִינוּן לְהֵיכָלָא, דְלָא יַעֲלוּן תַּמָּן נְבִיאַיָּא אֶלָּא בִּרְשׁוּ.</p>\n<p>קוּם רַעִִיָא מְהֵימְנָא, קוּם אַפְתַּח הֵיכָלָא, דְּהָא כַּמָּה מָארֵי דִנְבוּאָה אִינוּן דָּפְקִין לְתַרְעִין דְּהֵיכָלָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, וְאִיהִי סְתִימָא לְגַבַּיְיהוּ, עַד דְּאַנְתְּ תֵּיתֵי תַּמָּן אִיהִי לָא אִתְפַּתְּחַת,</p>\n<p>לְמַלְכָּא דַהֲווֹ צְרִיכִין לֵיהּ עַבְדּוֹי וַאֲפַרְכַסּוֹי וּמְמַנָּן וְשָׁלְטָנֵי אַרְעָא לְמֶחזֵי עִמֵּיהּ, כָּל חַד כְּפוּם צָרְכוֹי, וְכָל חַד כְּפוּם שָׁלְטָנוּתֵיהּ, וְכָל חַד כְּפוּם עִסְקוֹי, מֶה עָבַד מַלְכָּא, שַׁוִּי כֹלָּא בִידָא דְמַטְרוֹנִיתָא, וְאָמַר כָּל מָאן דְּבָעִי לְמִשְׁאַל שְׁאֶלְתּוֹי, יֵיתֵי לְמַטְרוֹנִיתָא, דְאִיהִי בַּיִת דִּילִי בֵּית י', הֵיכָל דִּילִי, וְהַאי אִיהוּ (ירמיה ט כג) אַל יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדוֹעַ אוֹתִי, כִּי אִם בְּזֹאת.</p>\n<p>בְּהַהוּא זִמְנָא דָפְקִין כֻּלְּהוּ לְפִתְחָא, דְתַמָּן סגרו\"ן דְּסָגִיר, וְתַמָּן פתחו\"ן דְּפָתַח, מִיָּד יֵיתֵי רַעִִיָא מְהֵימְנָא, וְיֵימָא אדנ\"י שְׂפָתַי תִּפְתָּח,</p>\n<p>קָמֵ\"ץ פַּתָ\"ח, דָּא סָגִיר וְדָא פָתַח, תְּרֵין שִׂפְוָון (נ\"א שבא) שַׁעֲרֵי צֶדֶק, עֲלַיְיהוּ אִתְּמַר (שם קיח יט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק.</p>\n<p>מִלְּגָאו אִיהִי סֶגוֹלְתָּ\"א, סֶגוֹ\"ל אִיהוּ בַּעִִלָהּ, וְאִיהִי סֶגוֹלְתָּ\"א, עֲטָרָה עַל רֵישֵׁיהּ, חֹלֵ\"ם עֲלֵיהּ אִתְּמַר (שם) אָבוֹא בָם אוֹדֶה י\"הּ, אָבוֹ\"א אִיהִי עִִשֶׂר, דְּאִיהִי נְקוּדַת חֹלֵ\"ם, וּבֵיהּ</p>"],[9500011064,"<p>אוֹדֶה י\"ה דְאִיהוּ כֶּתֶר עַל כֻּלְּהוּ,</p>\n<p>זֶה דָא צֵרִי, וְאִינוּן תְּרֵי סַמְכֵי קְשׁוֹט, צַדִּיקִים יָבֹאוּ בוֹ (תהלים קח כ), דָא צַדִּיק דְּאִיהוּ אוֹת בְּרִית, בְּתַרְוַיְהוּ, אִיהוּ חִירֵ\"ק תְּחוֹת צֵרִ\"י, וְאִיהוּ שׁוּרֵ\"ק, קִשּׁוּרָא דְתַרְוַיְהוּ, וּבְגִין דָּא</p>\n<p>אוֹדְךָ כִּי עֲנִיתָנִי וַתְּהִי לִי לִישׁוּעָה (שם כא), דָּא שְׁכִינְתָּא, דְאִיהִי מִסִּטְרָא דְצַדִּיק שׁוּרֵ\"ק לְגַבֵּי בַּעִִלָהּ, קִשּׁוּרָא דִילֵיהּ.</p>\n<p>וְאִיהִי חִרֵ\"ק תְּחוֹת צֵרִ\"י, תְּרֵי סַמְכֵי קְשׁוֹט, וְאִיהוּ סֶגוֹ\"ל תְּחוֹת תְּרֵין דְּרוֹעִין, וְאִיהִי חֹלֵ\"ם לְעִילָא בְכֶתֶר,</p>\n<p>וּבְגִין דָּא אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה (שם), כֻּלְּהוּ אָמְרִין מֵאֵת יְיָ' הָיְתָה זֹאת הִיא נִפְלָאת בְּעִינֵינוּ (שם), בְּזִמְנָא דְאִיהִי לְרֹאשׁ פִּנָּה אִתְקְרִיאַת רֵישָׁא, וַעֲלָהּ אִתְּמַר (שיר ז ו) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל.</p>\n<p>כַּד סְלִיקַת לְגַבֵּי מַלְכָּא, כַּמָּה מַלְאָכִין וְכַמָּה נִשְׁמָתִין סָלְקִין עִמָּהּ, דְּאִנּוּן נִימִין דִּילָהּ, דְּתַלְיָין מִינָהּ כְּעִנְבִין בְּאַתְכְּלָא,</p>\n<p>וְכַמָּה מַלְאָכִין וְנִשְׁמָתִין נָהֲרִין קֳדָמָהָא דְאִתְקְרִיאוּ עִינֵי יְיָ', וַעֲלַיְיהוּ אִתְּמַר (איוב לד כא) כִּי עִינָיו עַל דַּרְכֵי אִישׁ,</p>\n<p>וְכַמָּה פִקּוּדִין סָלְקִין קֳדָמָהָא, דְאִתְקְרִיאַת בְּכֻלְּהוּ מִצְוַת יְיָ' בָּרָה מְאִירַת עִינָיִם (תהלים יט ט).</p>\n<p>וְכַמָּה מַלְאָכִין סָלְקִין עִמָּהּ, דְּאִתְקְרִיאוּ אָזְנֵי יְיָ', דִּמְמַנָּן עַל קָלִין דִּצְלוֹתִין, וְעַל שִׂיחַת בְּנֵי הָאָדָם, לְמִשְׁמַע צְלוֹתִין,</p>\n<p>וְכַמָּה מַלְאָכִין סָלְקִין עִמָּהּ דְּאִתְקְרִיאוּ פְּנֵי יְיָ', דְּאִתְּמַר בְּהוֹן (יחזקאל א י) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וְגוֹמֵר, נָהֲרִין בְּכַמָּה גַוָּונִין,</p>\n<p>וְכַמָּה מַלְאָכִין סָלְקִין עִמָּהּ דְּאִתְקְרִיאוּ רוּחִין וְאֵשִׁין, דְּאִתְּמַר בְּהוֹן (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט, דִּמְמַנָּן עַל רֵיחָא וּתְנָנָא דְקָרְבָנִין, וְאִינוּן מָארֵי דְחוֹטָמָא.</p>\n<p>וְכַמָּה מָארֵי דְקָלִין וְדִבּוּרִין דְּפִימָא סָלְקִין עִמָּהּ, דְּאִתְּמַר בְּהוֹן (קהלת י ב) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר,</p>\n<p>וְכַמָּה מָארֵי דְצַוָּארֵי סָלְקִין עִמָּהּ, דְּתַמָּן קָנֶה וִשֶׁט, דִּמְמַנָּן עַל קָרְבָּנִין וּצְלוֹתִין, דְּאִתְּמַר בְּהוֹן (במדבר כח ב) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, וְאִלֵּין אִתְקְרִיאוּ אִשִּׁי\"ם,</p>\n<p>וְכַמָּה מַלְאָכִין סָלְקִין עִמָּהּ דְּאִתְקְרִיאוּ מָארֵי דִידַיִן, דְּאִתְּמַר בְּהוֹן (יחזקאל א ח) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם,</p>\n<p>וְכַמָּה מָארֵי דְגוּפָא סָלְקִין עִמָּהּ דְּאִתְּמַר בְּהוֹן (דניאל י ו) וּגְוִיָּתוֹ כְתַרְשִׁישׁ,</p>\n<p>וְכַמָּה מָארֵי דִבְרִית סָלְקִין עִמָּהּ דְּאִתְּמַר בְּהוֹן (יחזקאל א כח) כְּמַרְאֵה הַקֶּשֶׁת, וְאִנּוּן מָארֵי דְאוֹתוֹת,</p>\n<p>וְכַמָּה מָארֵי דְרַגְלִין סָלְקִין עִמָּהּ דְּאִתְּמַר בְּהוֹן (שם) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה.</p>\n<p>וְכַד אִיהוּ בְּהֵיכָלָהָא, כֻלְּהוּ נְבִיאַיָּא סָלְקִין תַּמָּן, וְדָפְקִין לְתַרְעָא וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח (תהלים נא יז),</p>\n<p>תְּלַת קַדְמָאִין דִּצְלוֹתָא אִינוּן מְסַדְּרִין שְׁאֵלְתִּין עַל נַפְשָׁא, לְאַעָלָא בְּהוֹן קֳדָם עִלַּת הָעִלּוֹת, דְּתַמָּן חַיֵּי נַפְשָׁא,</p>\n<p>אֶמְצָעִיּוֹת מְמַנָּן עַל שְׁאֵלְתִּין לְמִשְׁאַל בָּעוּתְהוֹן עַל צָרְכֵי גוּפָא,</p>\n<p>תְּלַת בַּתְרָאִין מְקַבְּלִין תְּיוּבְתָּא דְכָל שְׁאֵלְתִּין מִן מַלְכָּא.</p>\n<p>וּלְעִילָא מִכֻּלְּהוּ יָד כּוֹתֶבֶת, וּלְתַתָּא מִכֻּלְּהוּ יָד חוֹתֶמֶת, הֲדָא הוּא דִכְתִיב (איוב לז ז) וּבְיַד כָּל אָדָם יַחְתּוֹם,</p>\n<p>יָד כּוֹתֶבֶת אוֹרַיְיתָא דְבִכְתָב דְּאִיהִי לִימִינָא, יָד חוֹתֶמֶת אוֹרַיְיתָא דִבְעַל פֶּה דְאִיהִי לִשְׂמָאלָא,</p>\n<p>אוֹרַיְיתָא דְבִכְתָב דְּאִיהִי לִימִינָא עֲלֵיהּ אִתְּמַר (שמות יד ח) וּבְנֵי יִשְׂרָאֵל יוֹצְאִים בְּיָד רָמָה, וְדָא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ אוֹרַיְיתָא דְאִתְיְיהִיב מִימִינָא דְתַמָּן חָכְמָה.</p>\n<p>אוֹרַיְיתָא דִבְעַל פֶּה דְתַמָּן שְׁכִינְתָּא תַּתָּאָה, פֶּה אִתְקְרִיאַת מִסִּטְרָא דְצַדִּיק, דְּהָכִי סְלִיק פֶּ\"ה לְחוּשְׁבַּן מִילָ\"ה, דְאִיהוּ כָּל פֶּה,</p>\n<p>וּבְגִין דָּא (איוב לז ז) וּבְיַד כָּל אָדָם יַחְתּוֹם, וְאִיהִי לִשְׂמָאלָא, דְתַמָּן אִיהִי אִימָּא עִלָּאָה, דְאִתְּמַר בָּהּ חָתְמֵנוּ לְחַיִּים, וְצַדִּיק עַל שְׁמָהּ אִתְקְרֵי סֵפֶר חַיִּים.</p>"],[9500011065,"<p>כְּמָה דְאַמְרִינָן וּבְסֵפֶר חַיִּים וְגוֹמֵר,</p>\n<p>הָא אִתְפַּתְּחַת הֵיכָלָא,</p>\n<p>הָא קָא אַתְיָין נְבִיאַיָּיא מָארֵי דְרַגְלִין דְּקָא דָפְקִין לְתַרְעָא, וְאָמְרִין לְהַהוּא דְסָגִיר הֵיכָלָא, סגרו\"ן וְאִתְקְרֵי אדנ\"י שְׁמֵיהּ כְּשֵׁם רַבֵּיהּ, אָמְרִין לֵיהּ אדנ\"י שְׂפָתַי תִּפְתָּח, אַפְתַּח תַּרְעִין דְּהֵיכָלָא,</p>\n<p>בְּהַהוּא זִמְנָא עָאלִין נְטוּרֵי תַרְעָא לְמַלְכָּא, וְאַמְרֵי לֵיהּ,</p>\n<p>רִבּוֹן עָלְמִין הָא מָארֵי דְרַגְלִין קָא דָפְקִין לְתַרְעָא, דְאִינוּן שְׁלוּחֵי מִצְוָה, דְקַיְימִין בַּעֲמִידָה דִצְלוֹתָא קֳדָמָךְ.</p>\n<p>בְּהַהוּא זִמְנָא יָהַב לוֹן רְשׁוּ לְאַעָלָא,</p>\n<p>מַטְרוֹנִיתָא דְאִיהִי מִצְוָה דְמַלְכָּא אַפִּטְרוּפּוֹסָא דְכָל פִּקּוּדִין, אוֹלִיפַת זְכוּ קֳדָם מַלְכָּא בְּגִינַיְיהוּ, וְיֵימָא לֵיהּ</p>\n<p>רִבּוֹן עָלְמָא, הָא אִלֵּין דְּקַיְימִין קֳדָמָךְ בִּצְלוֹתִין, צָרִיךְ לְמֵיהַב לוֹן שְׁאֵלְתִּין דִּלְהוֹן,</p>\n<p>בְּהַהוּא זִמְנָא קָלָא נָפִיק לְגַבֵּי מָארֵי דְרַגְלִין, וְאָמַר (יחזקאל ב א) בֶּן אָדָם עֲמוֹד עַל רַגְלֶיךָ וַאֲדַבֵּר אוֹתָךְ, מַלֵּיל עִמִּי מַה שְּׁאֵלָתֵךְ בְּאֶמְצָעִיּוֹת דִּצְלוֹתִין, וְיִנָּתֵן לָךְ בְּבַתְרָאִין,</p>\n<p>מַטְרוֹנִיתָא קַבִּלַת שְׁאֵלְתּוֹי,</p>\n<p>וְצָרִיךְ לְמֵיהַב תְּלַת פְּסִיעָאן לַאֲחוֹרָא, דְלָא יִתְחַזַּר כִּתְפוֹי לְגַבֵּי מַלְכָּא,</p>\n<p>אִלֵּין נָפְקִין וְסגרו\"ן סָגַר תַּרְעָא אַבַּתְרַיְיהוּ.</p>\n<p>הָא מָארֵי דְאוֹתוֹת קָא דָפְקִין לְפִתְחָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, תִּפְתָּח דָּא פתחו\"ן,</p>\n<p>וְאִלֵּין אִינוּן מָארֵי דְחַ\"י בִּרְכָאָן דִּצְלוֹתָא, מִסִּטְרָא דְחַ\"י עָלְמִין, דִּמְיַחֲדִין לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ תַּמָּן, דְּצַדִּיק תְּשִׁיעָאָה אִיהוּ מֵעִילָא לְתַתָּא וּמִתַּתָּא לְעִילָא,</p>\n<p>תֵּשַׁע נְקוּדִין תֵּשַׁע טַעֲמֵי, וַעֲלַיְיהוּ אִתְּמַר (בראשית א יז) וַיִּתֵּן אוֹתָם אלהי\"ם בִּרְקִיעַ הַשָּׁמָיִם, וְדָא צַדִּיק דְּבֵיהּ כָּל נְקוּדִין, לְהָאִיר עַל הָאָרֶץ דָּא שְׁכִינְתָּא, דְאִיהִי כְלִילָא מִכָּל אַתְוָון.</p>\n<p>מִיָּד מָארֵי שְׁאֵלְתִּין דָּפְקִין לְתַרְעָא,</p>\n<p>כַּמָּה נְטוּרֵי תַרְעָא עָאלִין קֳדָם מַלְכָּא, וְיֵימְרוּן רִבּוֹן עָלְמָא, הָא מָארֵי צַדִּיקַיָּא מָארֵי דִצְלוֹתִין דִּמְבָרְכִין לָךְ בְּחַ\"י בִּרְכָאָן, בָּעוּן לְאַעָלָא קַמָּךְ,</p>\n<p>מִיָּד מַנִּי לְמִפְתַּח לוֹן, וּלְמֵהַב שְׁאֵלְתּוֹי,</p>\n<p>וְאִלֵּין אִינוּן מָארֵי דְאוֹתוֹת, מִסִּטְרָא דְאִלֵּין דְּאִתְּמַר בְּהוֹן (שם יד) וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים וּלְיָמִים וְשָׁנִים,</p>\n<p>וְאִלֵּין אִנּוּן דְּסָגְדִין בְּחַ\"י עָלְמִין, בְּחַ\"י בִּרְכָאָן לְגַבֵּי שְׁכִינְתָּא.</p>\n<p>אִלֵּין נָפְקִין</p>\n<p>הָא מָארֵי דְקוֹמָה דָפְקִין לְפִתְחָא, דְאִינוּן כָּרְעִין וְסָגְדִין לְמַלְכָּא בִצְלוֹתִין, כְּמָה דְאָמְרוּ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם,</p>\n<p>כּוֹרֵעַ לְגַבֵּי אדנ\"י בְּצַדִּיק, דְּאִתְּמַר בֵּיהּ (מלכים א ב מה) וְהַמֶּלֶךְ שְׁלֹמֹה בָּרוּךְ, וְזוֹקֵף לְגַבֵּי יהו\"ה, לְחַבְּרָא לוֹן תַּרְוַיְיהוּ כְּגַוְונָא דָא יאהדונה\"י.</p>\n<p>וְעַל כֻּלְּהוּ אוֹלִיפַת שְׁכִינְתָּא זְכוּ,</p>\n<p>וְאִינוּן כַּד סָלְקִין לְעִילָא נִשְׁמָתְהוֹן, כַּמָּה חֵיוָון מְקַבְּלִין לוֹן עַל גַּדְפַיְיהוּ, וְסָלְקִין לוֹן עַד תַּרְעָא דְהֵיכָלָא דְמַלְכָּא,</p>\n<p>מִיָּד דְּאִלֵּין דָּפְקִין לְפִתְחָא, אוֹלְפִין זְכוּ קֳדָם מַלְכָּא בְּגִינַיְיהוּ, וּמַנִּי מַלְכָּא לְמִפְתַּח לוֹן, וְאִלֵּין אִינוּן דִּמְמַלְּלִין קֳדָם מַלְכָּא בַּחֲשַׁאי, וְשָׁאֲלִין מִנֵּיהּ בָּעוּתְהוֹן בַּחֲשַׁאי, יְחִידִים קֳדָם מַלְכָּא, וּמַלְכָּא יָהִיב לוֹן שְׁאֵלְתִּין דִּלְהוֹן.</p>\n<p>מִיָּד הָא מַטְרוֹנִיתָא אֲחִידַת בְּהוֹן, וְאוֹלִיפַת זְכוּ בְּגִינַיְיהוּ קֳדָם דְּיִפְקוּן מִן הֵיכָלָא, וְאָמְרַת</p>\n<p>רִבּוֹן עָלְמִין, אִלֵּין אִינוּן דַּהֲווֹ, מְכַסְּיָין לִי בְּעִטּוּפָא דְמִצְוָה דְצִיצִית, בְּחָמֵשׁ קִשְׁרִין וּתְלַת עִִשֶׂר חוּלְיָין לְכָל סְטַר, וּבִתְלָתִין וּתְרֵין עַנְפֵי מִצְוָה,</p>\n<p>מִיָּד מַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְמַלְאָכִין דְּמֶרְכַּבְתָּא דִלְעִילָא, לְנָטְלָא לוֹן בְּגַדְפַיְיהוּ, וּלְפָרְחָא בְהוֹן מֵאֲתַר לַאֲתַר, וּלְכַסָּאָה עֲלַיְהוֹן מִכָּל מַזִּיקִין וּמַלְאֲכֵי חַבָּלָה.</p>\n<p>הָא אִלֵּין נָפְקִין, וְהָא אָחֳרָנִין דָּפְקִין לְתַרְעָא,</p>\n<p>מִיָּד עָאלִין נְטוּרֵי תַרְעִין, וְאָמְרִין</p>\n<p>רִבּוֹן עָלְמָא, הָא מָארֵי יְדִין דְּקָשְׁרִין תְּפִלָּה שֶׁל יָד עַל דְּרוֹעַיְיהוּ שְׂמָאלָא בִצְלוֹתָא, וּתְפִלִּין עַל רֵישָׁא, קָא עָאלִין,</p>\n<p>וְאִלֵּין אִינוּן דְּיָהֲבִין דּוֹרוֹנָא לָךְ בִּימִינָא, דְּאִיהִי צְדָקָה, צ' תִּשְׁעִים אֲמֵנִים, ד' אַרְבַּע קְדוּשׁוֹת, ק' מֵאָה בִּרְכָאָן, ה' חֲמִשָּׁה חוּמְשֵׁי אוֹרַיְיתָא,</p>\n<p>וּמִיָּד מַנִּי לוֹן, לְמִפְתַּח לוֹן,</p>\n<p>בְּהַהוּא</p>"],[9500011066,"<p>זִמְנָא וִידֵי אָדָם נָפְקִין, דְּאִינוּן גְּדוּלָה גְבוּרָה, וּמְקַבְּלִין דּוֹרוֹנָא דִלְהוֹן,</p>\n<p>הֲדָא הוּא דִכְתִיב (יחזקאל א ח) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, מָאי אָדָם, הַהוּא דְאִתְּמַר בֵּיהּ (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם,</p>\n<p>וּמְקַבְּלִין מִנַּיְיהוּ דוֹרוֹנָא וְיָהֲבִין לֵיהּ לְמַלְכָּא, וְאִם דּוֹרוֹנָא לַאו אִיהוּ כִדְקָא יָאוּת, לְכַלְבָּא אִתְמַסַּר, וְדַחְיָין לוֹן לְבָר,</p>\n<p>דְּאִית דְּלָא פָתְחִין לוֹן תַּרְעִין, וְאִתְּמַר בְּהוֹן (דברים כד יא) בַּחוּץ תַּעֲמֹד, וּמְמַלֵּל מַלְכָּא בְּהוֹן מִלְּבָר, וְיָהִיב לוֹן שְׁאֵלְתּוֹי מִלְּבָר, וְאָזְלִין לוֹן.</p>\n<p>דְּלַאו כֻּלְּהוּ עָאלִין לְבֵי מַלְכָּא, אֶלָּא אִלֵּין מָארֵי דְבֵיתָא, דְאִתְּמַר בְּהוֹן (דניאל א ד) יְלָדִים אֲשֶׁר אֵין בָּהֶם כָּל מוּם, לָא בִּצְלוֹתְהוֹן, וְלָא בְּנִשְׁמָתְהוֹן, וְטוֹבֵי מַרְאֶה בְּכָל עוֹבְדֵיהוֹן, וּמַשְׂכִּילִים בְּכָל חָכְמָה, וְשַׁפִּירָן לְמֶחזֵי, דַּעֲלַיְיהוּ אִתְּמַר (שיר ב יד) הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִינִי אֶת קוֹלֵךְ, כִּי קוֹלֵךְ עָרֵב וּמַרְאֵךְ נָאוְה,</p>\n<p>וְיוֹדְעִי דַעַת וּמְבִינֵי מַדָּע (דניאל א ד), דְּיָדְעִין בְּחָכְמָה וּבִתְבוּנָה וָדַעַת, דְּאֵין דּוֹרְשִׁין בְּמַעֲשֵׂה בְרֵאשִׁית, אֶלָּא אִם הוּא חָכָם בְּחָכְמָה וּמֵבִין בְּבִינָה וְיוֹדֵעַ בְּדַעַת,</p>\n<p>וַאֲשֶׁר כֹּחַ בָּהֶם, דָּא שְׁכִינְתָּא עִלָּאָה, דְאִיהִי כ\"ח אַתְוָון דְּעוֹבָדָא דִבְּרֵאשִׁית, לַעֲמוֹד בְּכֻלְּהוּ בַּעֲמִידָה דִצְלוֹתָא,</p>\n<p>אִלֵּין יַעֲלוּן לְהֵיכָלָא דְמַלְכָּא, דְאִינוּן צַדִּיקִים גְּמוּרִים.</p>\n<p>בֵּינוּנִיִּים יְהִיב לוֹן שְׁאֵלְתִּין דִּלְהוֹן מִלְּבָר, וְלָא עָאלִין לְגָאו,</p>\n<p>רַשִּׁיעַיָּיא אִדַּחְיָין מִתַּמָּן, וְלָא יָהִיב לוֹן שְׁאֵלְתִּין דִּלְהוֹן, אֶלָּא עֲלַיְיהוּ אִתְּמַר (ישעיה א יב) מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם רְמֹס חֲצֵרָי,</p>\n<p>וְאִלֵּין אִינוּן רַשִּׁיעַיָּיא, דַהֲווֹ מְבַזִּין לְמַלְכָּא בִּצְלוֹתְהוֹן, דְּמַנְחָן לְמִשְׁמַע צְלוֹתָא, וּפָסְקִין לָהּ עַל שִׂיחָה בְּטֵלָה.</p>\n<p>אִלֵּין נָפְקִין,</p>\n<p>הָא אָחֳרָנִין עָאלִין, אִינוּן מָארֵי דְצַוָּאר, דַּהֲווֹ מְבָרְכִין לְקוּדְשָׁא בְּרִיךְ הוּא עַל מַאֲכָלִין וּמִשְׁתְּיָין דְּקָרְבָּנִין, דְּאָמְרִין בְּכָל יוֹמָא צַו אֶת בְּנֵי יִשְׂרָאֵל, וְאָמַרְתָּ אֲלֵיהֶם אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִיחוֹחִי (במדבר כח ב), דַהֲווֹ מְקָרְבִין לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, בְּכַמָּה קָרְבָּנִין דִּצְלוֹתִין, וְאִלֵּין אִינוּן דִּמְהַנְּיָין בְּעֹנֶג שַׁבָּת, וּמְבָרְכִין לְקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא, יְהִיב לוֹן שְׁאֵלְתִּין דִּלְהוֹן, וּלְאָחֳרָנִין דַּהֲווֹ אָכְלִין בְּלָא צְלוֹתָא אִתְדַּחְיָין מִתַּמָּן, וְיָהֲבִין לוֹן בִּידָא דְכַמָּה מַלְאֲכֵי חַבָּלָה דְאִינוּן מַזִּיקִין.</p>\n<p>הָא אִלֵּין נָפְקִין,</p>\n<p>הָא מָארֵי דְקָלִין וְדִבּוּרִין בִּזְמִירוֹת וְתוּשְׁבָּחוֹת וְהוֹדָאוֹת דִּצְלוֹתָא דָפְקִין, וּמָארֵי דְקָלִין דְּקָרָאן לְקוּדְשָׁא בְּרִיךְ הוּא בִּקְרִיאַת שְׁמַע, שְׁמַע יִשְׂרָאֵל תְּרֵין זִמְנִין עִִרֶב וָבֹקֶר.</p>\n<p>אַדְהָכִי הָא מָארֵי דְרַגְלִין קָא דָפְקִין לְפִתְחָא, מָארֵי דַעֲמִידָה דִצְלוֹתָא, דְאִתְּמַר בְּהוֹן (דניאל א ד) וַאֲשֶׁר כֹּחַ בָּהֶם לַעֲמוֹד בְּהֵיכַל הַמֶּלֶךְ,</p>\n<p>הַמֶּלֶךְ סְתָם דָּא קוּדְשָׁא בְּרִיךְ הוּא, הֵיכַל הַמֶּלֶךְ דָּא אדנ\"י, דְּאִתְּמַר בֵּיהּ (תהלים נא יז) אדנ\"י שְׂפָתַי תִּפְתָּח, אדנ\"י סְלִיק לְחוּשְׁבָּן הֵיכָל, וְאִתְּמַר (חבקוק א כ) וַיְיָ' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּזָכֵי לְאַעֲלָאָה לְהֵיכָלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֶחזֵי לְמַלְכָּא וּמַטְרוֹנִיתָא,</p>\n<p>זַכָּאָה פוּמָא, דְּשַׁרְיָא בֵּיהּ צְלוֹתָא דְאִיהִי אדנ\"י, דְּאָמְרִין לָהּ אדנ\"י שְׂפָתַי תִּפְתָּח, וְזַכָּאִין שִׂפְוָון דְּאִינוּן תַּרְעִין דְּהֵיכָלָא, כְּגַוְונָא דְאִלֵּין דְּאִתְּמַר בְּהוֹן (שם קיח יט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק,</p>\n<p>דְּכַד פּוּמֵיהּ פָּתַח בִּצְלוֹתָא בִשְׁכִינְתָּא, וַיְיָ' יַעֲנֶה מִיָּד, הֲדָא הוּא דִכְתִיב (ישעיה נח ט) אָז תִּקְרָא וַיְיָ' יַעֲנֶה, אָ\"ז תְּמַנְיָא אַתְוָון יהו\"ה אהי\"ה, וַיְיָ' יַעֲנֶה הוּא וּבֵית דִּינוֹ, וְדָא יהו\"ה אדנ\"י יאהדונה\"י,</p>\n<p>לָקֳבֵל תְּמַנְיָא אַתְוָון, אִלֵּין אִינוּן חֵיוָון דְּחַשְׁמַ\"ל, דְּאִינוּן חֵיוָון דְּאֶשָּׁא, פַּעַם חָשׁוֹת וּפַעַם מְמַלְּלוֹת, בִּצְלוֹתָא מְיוּשָׁב מְמַלְּלוֹת, בִּצְלוֹתָא דִמְעוּמֶד חָשׁוֹת.</p>\n<p>וְתָא חֲזִי,</p>\n<p>אִם בַּר נַשׁ סָלִיק בְּמַחֲשַׁבְתֵּיהּ בִּצְלוֹתָא דִילֵיהּ לִשְׁכִינְתָּא, אוֹ בְּכָל פִּקּוּדָא וּפִקּוּדָא דְעָבִיד, מִיָּד דְּדָפִיק לְפִתְחָא דְהֵיכָלָא דְמַלְכָּא, נָבִיא אוֹ חוֹזֶה אוֹ חָכָם אוֹ צַדִּיק אוֹ חָסִיד, מִיָּד דְּקָרָא לָהּ לְתַרְעָא, אִם שְׁכִינְתָּא סְלִיקַת תַּמָּן, יְיָ' יַעֲנֶה מִיָּד, וְלָא אַמְתִּין לְעִִבֶד אוֹ מְמַנָּא דְאַפְתַּח לֵיהּ, אֶלָּא אִיהוּ מַמָּשׁ אַפְתַּח לֵיהּ, מֵחֲבִיבוּ וּרְחִימוּ דְאִית לֵיהּ לְגַבָּהּ כְּחָתָן לְגַבֵּי כַלָּה,</p>\n<p>וְאִם שְׁכִינְתָּא לָא סְלִיקַת בְּהַהוּא צְלוֹתָא אוֹ פִקּוּדָא, לָא חָשִׁיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמִפְתַּח לֵיהּ הֵיכָלֵיהּ, וַאֲפִילוּ עַל יְדֵי שִׁלּוּחָא.</p>"],[9500011067,"<p>וְלַאו אִיהוּ כְדַאי לְמֵיעָאל לְהֵיכָלָא דְמַלְכָּא, וַעֲלֵיהּ אִתְּמַר (דברים כד יא) בַּחוּץ תַּעֲמֹד, וּמִלְּבָר יָהֲבִין לֵיהּ בָּעוּתֵיהּ, עַל יְדֵי שְׁלוּחָא אוֹ מְמַנָּא,</p>\n<p>וְאִי לָא סָלִיק צְלוֹתֵיהּ כִּדְקָא יָאוּת, דַּחְיָין לֵיהּ לְבָר, וְסָגְרִין תַּרְעִין בְּאַנְפּוֹי, וַעֲלֵיהּ אִתְּמַר (משלי א כח) אָז יִקְרָאֻנְנִי וְלֹא אֶעֱנֶה יְשַׁחֲרֻנְנִי וְלֹא יִמְצָאֻנְנִי.</p>\n<p>וְהָכִי כַּד קָרָאן יִשְׂרָאֵל כָּל חַד וְחַד לְקוּדְשָׁא בְּרִיךְ הוּא, בִּקְרִיאַת שְׁמַע אוֹ בִצְלוֹתָא אוֹ בְכָל פִּקּוּדָא, אִם שְׁכִינְתָּא לַאו אִיהִי תַמָּן לָא נָחִית תַּמָּן,</p>\n<p>הֲדָא הוּא דִכְתִיב (שמות כ כד) בְּכָל מָקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי אָבֹא אֵלֶיךָ וּבֵרַכְתִּיךָ, וְתִרְגֵּם אֹנְקְלוֹס בְּכָל אֲתַר דְּאַשְׁרֵי שְׁכִינְתִּי תַמָּן וְגוֹמֵר,</p>\n<p>דְּכַד בַּר נַשׁ סְלִיק שְׁכִינְתָּא בְּפִקּוּדִין דִּילֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא נָחִית עֲלֵיהּ בְּגִינָהּ, וּבְגִין דָּא אָמַר הַנָּבִיא (ירמיה ט כב), אַל יִתְהַלֵּל וְגוֹמֵר, כִּי אִם בְּזֹאת וְהָא אוּקְמוּהוּ.</p>\n<p>וְהָכִי כַד בַּר נַשׁ סָלִיק שְׁכִינְתָּא בִצְלוֹתָא דִילֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא נָחִית לָקֳבֵל צְלוֹתֵיהּ, וּשְׁכִינְתֵּיהּ אַקְדִּימַת, לְאַפְתָּחָא לֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית כד טו) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר, וְהִנֵּה רִבְקָה יֹצֵאת,</p>\n<p>וְדָא אִיהוּ רָזָא דְאוּקְמוּהָ מָארֵי מַתְנִיתִין, אִם שְׁגוּרָה תְּפִלָּתִי בְּפִי יוֹדֵעַ אֲנִי שֶׁהוּא מְקוּבָּל, וְאִם לַאו יוֹדֵעַ אֲנִי שֶׁהוּא מְטוֹרָף, וְטוֹרְפִין לוֹ צְלוֹתֵיהּ בְּאַנְפּוֹי,</p>\n<p>וּבְגִין דָּא וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר, וּלְמַלְּלָא בִצְלוֹתֵיהּ בְּשֵׁם יְיָ', מִיָּד שְׁכִינְתָּא נָפְקַת לְגַבֵּיהּ וּבְגִינֵיהּ נָחְתַת שְׁכִינְתָּא לְרַגְלוֹי, הֲדָא הוּא דִכְתִיב (תהלים פה יד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו.</p>\n<p>וְכַד שְׁכִינְתָּא אִיהִי עוֹמֶדֶת עַל יִשְׂרָאֵל, וְיִשְׂרָאֵל אִינוּן רַגְלִין דְּקָמַת עֲלַיְהוּ בְּגָלוּתָא, קוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ בְּהוֹן, מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים וְגוֹמֵר (שיר ז ב),</p>\n<p>וְעוֹד מַה יָּפוּ פְעָמַיִךְ, כַּד יִשְׂרָאֵל הֲווֹ מְקַיְּימִין שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה,</p>\n<p>וְעוֹד מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים, בְּזִמְנָא דְעָמְדוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי, דַּעֲלַיְיהוּ אִתְּמַר (זכריה יד ד) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא,</p>\n<p>וְעוֹד מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים, כַּד קַיְימִין בְּרֹאשׁ הַשָּׁנָה בְּיוֹמָא דְּדִינָא בִצְלוֹתָא, קוּדְשָׁא בְּרִיךְ הוּא בְּגִינַיְיהוּ עוֹמֵד מִכִּסֵּא דִין וְיוֹשֵׁב עַל כִּסֵּא רַחֲמִים,</p>\n<p>בְּזִמְנָא דְאִינוּן קַיְימִין בִּשְׁכִינְתָּא בְגָלוּתָא, וְסָבְלִין עֲלַיְיהוּ כַמָּה דִינִין וְכַמָּה יִסּוּרִין, דְּאָמְרִין כִּי עָלֶיךָ הוֹרַגְנוּ כָל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה (תהלים מד כג).</p>\n<p>וְכַד בַּר נַשׁ מְצַלֵּי, צָרִיךְ בְּקַדְמֵיתָא לְנַחְתָא קוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ יהו\"ה בִּקְרִיאַת שְׁמַע,</p>\n<p>וְלֵיהּ אָמְרִין שְׁמַע יִשְׂרָאֵל, בְּכָל שַׁבָּתוֹת וְיֹמִין טָבִין, בְּגִין דְּיוֹמִין דְּחוֹל תַּרְעָא דְהֵיכָלָא פְּנִימָאָה אִיהִי סְתִימָא, הֲדָא הוּא דִכְתִיב (יחזקאל מו א) כֹּה אָמַר אדנ\"י אלהי\"ם שַׁעַר הֶחָצֵר הַפְּנִימִית הַפֹּנֶה קָדִים יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה,</p>\n<p>וְאַמַּאי בְּגִין דְמטטרון שַׁלִּיט עֲלַיְיהוּ, וּבְיוֹם הַשַּׁבָּת דְּיֵיתֵי בַעִִלָהּ יִפָּתֵחַ, וְכֵן בְּיוֹם הַחֹדֶשׁ יִפָּתֵחַ,</p>\n<p>וּבְגִין דָּא, כַּד נָחִית בַּר נַשׁ יהו\"ה בִּקְרִיאַת שְׁמַע, צָרִיךְ לְנַחְתָא לֵיהּ בְּאדנ\"י, דְּאִיהוּ בְּפִימֵיהּ, וּבְגִין דָּא אדנ\"י שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ.</p>\n<p>דִתְלַת צְלוֹתִין אִינוּן בְּשַׁבָּת, וּרְבִיעָאָה צְלוֹתָא דְמוּסָף, צְלוֹתָא דְעַרְבִית אַתָּה קִדַּשְׁתָּ, וְדָא שְׁכִינְתָּא תַּתָּאָה, דְאִיהִי מִסִּטְרָא דִשְׂמָאלָא, דְתַמָּן לֵיוָאֵי, דְאִתְּמַר בְּהוֹן וְקִדַּשְׁתָּ אֶת הַלְוִיִּם,</p>\n<p>צְלוֹתָא דְשַׁחֲרִית יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ, וְדָא נִשְׁמַת כָּל חַי, דְאִיהִי אִימָּא עִלָּאָה, עֲלָהּ אִתְּמַר (תהלים סח יד) אִם תִּשְׁכְּבוּן בֵּין שְׁפַתָּיִם, אַל תִּקְרֵי אִם אֶלָּא אֵם, דַּעֲלָהּ אִתְּמַר (בראשית כח יא) וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, בַּאֲתַר דְּיֵשׁ כ\"ב אַתְוָון דְּאוֹרַיְיתָא שְׁכִיבַת תַּמָּן,</p>\n<p>זַכָּאָה אִיהִי פוּמָא, דְאוֹרַיְיתָא דְהַהִיא שַׁעִִתָּא שְׁכִיבַת תַּמָּן.</p>\n<p>צְלוֹתָא תְּלִיתָאָה אַתָּה אֶחָד וְשִׁמְךָ אֶחָד, דָּא יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא דַאֲחִיד בְּתַרְוַיְיהוּ,</p>\n<p>וְאִינוּן נְשָׁמָה יְתֵירָה וְרוּחַ יְתֵירָה וְנֶפֶשׁ יְתֵירָה, נֶפֶשׁ יְתֵירָה בְּעִִרֶב שַׁבָּת, אַתָּה קִדַּשְׁתָּ, נְשָׁמָה יְתֵירָה נִשְׁמַת כָּל חַי, דְּאִתְּמַר בָּהּ יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ, רוּחַ יְתֵירָה אַתָּה אֶחָד וְשִׁמְךָ אֶחָד,</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּאַפְתַּח פִּימוֹי בִּתְלַת צְלוֹתִין, לְקַבְּלָא</p>"],[9500011068,"<p>לוֹן בְּשַׁבָּת,</p>\n<p>תְּפִלַּת מוּסָף דָּא צַדִּיק, דְּכָלִיל כֻּלְּהוּ צְלוֹתִין, וּבֵיהּ אָמְרִין בִּצְלוֹתָא דְמוּסָף כֶּתֶר יִתְּנוּ לְךָ יְיָ' אלהינ\"ו</p>\n<p>וְכֶתֶר אִיהוּ כֶתֶר עִִלְיוֹן, יְיָ' אלהינ\"ו אַבָּא וְאִימָּא, קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ תְּלַת אֲבָהָן, יְיָ' צבאו\"ת בְּרִית מִילָה וּתְרֵין יַרְכֵי קְשׁוֹט, מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ דָא שְׁכִינְתָּא.</p>\n<p>זַכָּאִין שִׂפְוָון דְּאִינוּן תַּרְעִין דְּהֵיכָלָא, לְקַבְּלָא בְהוֹן צְלוֹתִין אִלֵּין, וּבְגִין דָּא אדנ\"י שְׂפָתַי תִּפְתָּח (תהלים נא יז),</p>\n<p>פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק (שם קיח יט), דְּכַד בַּר נַשׁ אַפְתַּח פִּימוֹי בִּצְלוֹתָא בִשְׁכִינְתֵּיהּ, מִיָּד אָז תִּקְרָא וַיְיָ' יַעֲנֶה (ישעיה נח ט), הוּא וּבֵית דִּינוֹ, אָ\"ז תְּמַנְיָא אַתְוָון דְּאִינוּן יהו\"ה אהי\"ה, אַבָּא וְאִימָּא, וַיְיָ' יַעֲנֶה מִיָּד הוּא וּבֵית דִּינוֹ יהו\"ה אדנ\"י.</p>\n<p>כַּד אִינוּן בְּאַבָּא וּבְאִימָּא, לִימִינָא וּשְׂמָאלָא, כָּל חַד אִיהוּ שֵׁם בִּפְנֵי עַצְמוֹ, וְכַד אִינוּן בְּכֶתֶר עִִלְיוֹן אִינוּן בְּיִחוּדָא חֲדָא, כְּגַוְונָא דָא יאההויה\"ה, בְּחֶסֶד וּגְבוּרָה אִינוּן יהו\"ה אהי\"ה, עַנְפִין מִתְפָּרְדִין לִימִינָא וּשְׂמָאלָא, בְּעַמּוּדָא דְאֶמְצָעִיתָא אִינוּן תַּרְוַיְיהוּ בְיִחוּדָא חֲדָא, וְהָכִי אִינוּן עַנְפִין מִתְפָּרְדִין בְּנֶצַח וָהוֹד, יהו\"ה לִימִינָא אהי\"ה לִשְׂמָאלָא, בְּצַדִּיק מִתְיַחֲדִים,</p>\n<p>הָא הָכָא רָזָא דְאִילָנָא, דְאִתְפַּשְׁטָן עַנְפּוֹי מֵעִילָא, וּמִתְיַיחֲדִין בְּשָׁרְשׁוֹי לְתַתָּא, וְדָא עִץ הַחַיִּים.</p>\n<p>עִץ הַדַּעַת טוֹב, דְּלֵית בֵּיהּ רָע, מִתַּתָּא לְעִילָא, כְגַוְונָא דָא, אדנ\"י שְׁכִינְתָּא תַתָּאָה, יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא, וְאִינוּן בִּתְרֵין יַרְכִין עַנְפִין מִתְפָּרְדִין לִימִינָא וּשְׂמָאלָא, וְהָכִי בִתְרֵין דְּרוֹעִין מִתְפָּרְדִין עַנְפִין לִימִינָא וְלִשְׂמָאלָא, בְּצַדִּיק אִינוּן בְּיִחוּדָא חֲדָא יאהדונה\"י, וְדָא רָזָא דְחַשְׁמַ\"ל, חֵיוָון דְּאֶשָּׁא מְמַלְּלָן,</p>\n<p>כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, דְּאִיהִי יאהדונה\"י, וְכָל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, בִּתְרֵין שְׁמָהָן וְדָא יהו\"ה אהי\"ה.</p>\n<p>וּבְהוֹן הֲוָה מְשַׁבַּח שְׁכִינְתָּא בְּשִׁיר הַשִּׁירִים מִתַּתָּא לְעִילָא, הֲדָא הוּא דִכְתִיב (שיר השירים ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, חַמּוּקֵי יְרֵכַיִךְ כְּמוֹ חֲלָאִים מַעֲשֵׂה יְדֵי אֳמָּן, שָׁרְרֵךְ אַגַּן הַסַּהַר, שְׁנֵי שָׁדַיִךְ, צַוָּארֵךְ, רֹאשֵׁךְ, הָא הָכָא מִתַּתָּא לְעִילָא.</p>\n<p>וְהִיא מְשַׁבַּחַת לְקוּדְשָׁא בְּרִיךְ הוּא מֵעִילָא לְתַתָּא, רֹאשׁוֹ כֶּתֶם פָּז, עִינָיו, לְחָיָיו, שִׂפְתוֹתָיו, יָדָיו, שׁוֹקָיו, זַכָּאָה אִיהוּ מָאן דְּסָלִיק צְלוֹתָא בְּכָל אֵבֶר וְאֵבֶר בְּתִקּוּנָא דָא. תָּא</p>\n<p>תָּא חֲזִי יהו\"ה</p>\n<p>יהו\"ה אדנ\"י אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, בִּתְרֵין שׁוֹקִין יהו\"ה לִימִינָא אדנ\"י לִשְׂמָאלָא, וְאִינוּן אַסְפַּקְלַרְיָאָה הַמְּאִירָה וְאַסְפַּקְלַרְיָאָה שֶׁאֵינָה מְאִירָה, בְּצַדִּיק תַּרְוַיְיהוּ חַד יאהדונה\"י,</p>\n<p>וְהָכִי בִתְרֵין דְּרוֹעִין יהו\"ה לִימִינָא אדנ\"י לִשְׂמָאלָא, בְּעַמּוּדָא דְאֶמְצָעִיתָא יאהדונה\"י תַּרְוַיְיהוּ בְּיִחוּדָא חֲדָא, בְּסוֹד אָמֵ\"ן,</p>\n<p>וּבְגִין דָּא גָדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ, הָא אִיהוּ מִתַּתָּא לְעִילָא.</p>\n<p>מֵעִילָא לְתַתָּא יהו\"ה אהי\"ה תַּרְוַיְיהוּ חַד בְּכֶתֶר עִִלְיוֹן, כְּגַוְונָא דָא יאההויה\"ה,</p>\n<p>בְּחָכְמָה וּבִינָה יהו\"ה אהי\"ה, בִּתְרֵין דְּרוֹעִין יהו\"ה אהי\"ה, בְּעַמּוּדָא דְאֶמְצָעִיתָא תַּרְוַיְיהוּ כַּחֲדָא, בְּנֶצַח וָהוֹד יהו\"ה אהי\"ה דָּא לִימִינָא וְדָא לִשְׂמָאלָא, בְּצַדִּיק תַּרְוַיְיהוּ בְּיִחוּדָא כַּחֲדָא,</p>\n<p>וְכֵן בְּמַלְכוּת תַּרְוַיְיהוּ בְּיִחוּדָא חֲדָא כְּגַוְונָא דָא יהו\"ה אדנ\"י, וּבָהּ מִתְחַבְּרִין יהו\"ה אהי\"ה, וּבְגִין דָּא אִיהִי קִרְיַת אַרְבַּע, חִבּוּרָא דְאַרְבַּע שְׁמָהָן, דְּאִינוּן בְּאַרְבַּע פָּרָשִׁיָּין דִּתְּפִלִּין דְּיָד, וּבְאַרְבַּע בָּתֵּי דִתְּפִלִּין דְּרֵישָׁא.</p>\n<p>וְכַד נָבִיא הֲוָה סָלִיק לְעִילָא, וְדָפִיק לְתַרְעָא, אִי הֲוָה סָלִיק בִּשְׁכִינְתָּא, הֲוָה פָתַח לֵיהּ מִיָּד, וַהֲוָה אָמַר לֵיהּ בֶּן אָדָם עֲמֹד עַל רַגְלֶיךָ וַאֲדַבֵּר אֹתָךְ (יחזקאל ב א),</p>\n<p>דְּאַנְתְּ הוּא דַהֲוִית סָבִיל לִשְׁכִינְתָּא בִצְלוֹתָא בַעֲמִידָה, עֲמוֹד עַל רַגְלֶיךָ, דְּאִתְּמַר בְּהוֹן (שם א ז) וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עִגֶל, עֲגוּלִים כַּנְּקוּדִים דְּאִינוּן מַנְהִיגִים לְאַתְוָון, וּמִסִּטְרָא דְאַתְוָון אִינוּן מְרוּבָּעִין, הֲדָא הוּא דִכְתִיב (שם יז) עַל אַרְבַּעַת רִבְעִיהֶם בְּלֶכְתָּם יֵלֵכוּ,</p>\n<p>וְעוֹד עַל אַרְבַּעַת רִבְעִיהֶם, אִינוּן</p>"],[9500011069,"<p>אַרְבַּע קְדוּשׁוֹת דְּאוֹמֵר בַּר נַשׁ בְּכָל יוֹמָא,</p>\n<p>וְעוֹד עֲמוֹד עַל רַגְלֶיךָ בְּקַדְמָאִין,</p>\n<p>וּמַה שְּׁאֵלָתֵךְ עַד חֲצִי הַמַּלְכוּת בְּאֶמְצָעִיּוֹת,</p>\n<p>וְתֵעָשׂ בְּבַתְרָאִין, דְּתַמָּן אִיהוּ בַּר נַשׁ כְּעִִבֶד הַמְקַבֵּל פְּרָס מֵרַבּוֹ וְהוֹלֵךְ לוֹ,</p>\n<p>אִלֵּין נָפְקִין דְּיָהִיב לוֹן מַלְכָּא בָּעוּתְהוֹן, הָא אָחֳרָנִין קָא דָפְקֵי לְתַרְעָא, מָארֵי דִבְרִית מִילָה, וְאַמְרֵי אדנ\"י שְׂפָתַי תִּפְתָּח.</p>\n<p>זַכָּאִין אִינוּן יִשְׂרָאֵל דְּאִינוּן רַגְלִין דִּשְׁכִינְתָּא, דְקָמַת עֲלַיְיהוּ בִצְלוֹתָא בַעֲמִידָה, דְּאִיהִי וַדַּאי עֲלַיְיהוּ תְּפִלָּה מְעוּמָד, וְקָמַת עֲלַיְיהוּ בְגָלוּתָא,</p>\n<p>וּבְמַאי קָמַת עֲלַיְיהוּ, בְּגִין דְּנָחֲתִין לְגַבָּה יהו\"ה, דַּעֲלֵיהּ אִתְּמַר כָּל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, דְּבֵיהּ צָרִיךְ בַּר נַשׁ לְזַקְפָא לִשְׁכִינְתָּא,</p>\n<p>וְאִלֵּין דְּלָא זָקְפִין לָהּ בְּשֵׁם יהו\"ה בִּצְלוֹתְהוֹן, אוֹ בְּפִקּוּדִין דְּאוֹרַיְיתָא (נ\"א דלהון), אִיהִי צָוְוחַת עֲלַיְיהוּ, נְתָנַנִי יְיָ' בִּידֵי לֹא אוּכַל קוּם (איכה א יד),</p>\n<p>דִּסְמִיכוּ דִילָהּ אִיהוּ בִּתְרֵין דְּרוֹעִין דְּאִינוּן חֶסֶד וּגְבוּרָה, וַעֲמִידָה דִילָהּ בִּתְרֵין שׁוֹקִין דְּאִינוּן נֶצַח וָהוֹד,</p>\n<p>וּזְקִיפוּ דִילָהּ בְּגוּפָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, יהו\"ה שְׁמֵיהּ, וּבְגִין דָּא כָּל הַזּוֹקֵף זוֹקֵף בְּשֵׁם, וְיִחוּדָא דִילָהּ בְּצַדִּיק,</p>\n<p>וּבְגִין אִלֵּין דְּלָא יְכִילַת לְמֵיקַם בְּהוֹן בִּצְלוֹתָא, וְלֵית לָהּ סְמִיכוּ וְלָא זְקִיפוּ בְהוֹן בְּגָלוּתָא, אִתְעֲצִיבַת בְּהוֹן,</p>\n<p>וְרָזָא דְמִלָּה בֵּן חָכָם יְשַׂמַּח אָב, וּבֵן כְּסִיל תּוּגַת אִמּוֹ (משלי י א), וּבְגִינֵיהּ וַיִּתְעַצֵּב אֶל לִבּוֹ (בראשית ו ז),</p>\n<p>וְאַמַּאי כּוּלֵי הַאי לְאִמֵּיהּ וְלָא לַאֲבוּהִי. אֶלָּא דָא רָזָא עִלָּאָה</p>\n<p>אִיהוּ, פִּקּוּדִין דַּעֲשֵׂה אִינוּן מִימִינָא דְתַמָּן חָכְמָה, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין הָרוֹצֶה לְהַחְכִּים יַדְרִים,</p>\n<p>וּפִקּוּדִין דְּלֹא תַעֲשֶׂה אִינוּן מִשְּׂמָאלָא דְתַמָּן אִימָּא עִלָּאָה, דִּבְהוֹן אדנ\"י שְׁ'מָעָה אדנ\"י סְ'לָחָה אדנ\"י הַ'קְשִׁיבָה וַעֲשֵׂה אַל תְּאַחַר (דניאל ט יט), בְּיוֹם הַכִּפּוּרִים,</p>\n<p>וְכַד לָא חָזְרִין בִּתְיוּבְתָּא אִינוּן דְּעָבְרִין עַל לֹא תַעֲשֶׂה דְאִינוּן מִשְּׂמָאלָא, אִתְּמַר עֲלַיְהוּ (משלי י א) וּבֵן כְּסִיל תּוּגַת אִמּוֹ, בְּגִין דְּתַמָּן אִימָּא לִשְׂמָאלָא, וְלִבָּא אִיהוּ לִשְׂמָאלָא, (ורזא דמלה) וּבְגִין דָּא וַיִּתְעַצֵּב אֶל לִבּוֹ.</p>\n<p>וּתְרֵין הֲוַיּוֹ\"ת אִינוּן לִימִינָא וְלִשְׂמָאלָא, כְגַוְונָא דָא יהה\"ו יוה\"ה,</p>\n<p>י' לִימִינָא וּבֵיהּ יהו\"ה בְּחָכְמָה יָסַד אָרֶץ (שם ג יט), אָב עִם בְּרַתָּא, ה' עִלָּאָה עִם בְּרָא דְאִיהוּ ו', תְּפִלִּין עַל רֵישֵׁיהּ, הֲדָא הוּא דִכְתִיב (ישעיה סב ח) וּבִזְרוֹעַ עְִזּוֹ אֵלּוּ תְּפִלִּין דְּרֵישָׁא, דִבְכָל אֲתַר דְּאָת ה' עַל ו' אִיהִי אִימָּא.</p>\n<p>וְדָא רָזָא דְקָרְבָּן עוֹלֶה וְיוֹרֵד, דְּסָלִיק ה' לְגַבֵּי י', וְנָחִית ה' לְגַבֵּי ו', וְאִם לַאו הַאי הֲוַיָּ\"ה יהה\"ו, דְאִתְרְמִיז בְּהַאי קְרָא (ירמיה ט כג) כִּי אִם בְּזֹאת יִ תְהַלֵּל הַ מִּתְהַלֵּל הַ שְׂכֵּל וְ יָדוֹעַ אוֹתִי, לָא הֲווֹ יָדְעִין בְּנֵי נָשָׁא קָרְבָּן עוֹלֶה וְיוֹרֵד,</p>\n<p>דְּכַד לָא הֲוָה בַּר נַשׁ קָרִיב אָת ה' עִם י', ה' עִם ו', וּמָאן עוֹלֶה וְיוֹרֵד, מָאן הֲוָה יָדַע מָאי נִיהִי ה' דְּאִיהִי בְּרַתָּא, דְאִית לֵיהּ לְסַלְקָא לָהּ לְגַבֵּי אַבָּא, וְה' דְּאִיהִי אִימָּא לְנַחְתָא לָהּ לְגַבֵּי בְּרָא,</p>\n<p>אֶלָּא בְּגִין הַאי הֲוַיָּ\"ה דְאִיהִי יהה\"ו, דְה' דְּאִיהִי עַל ו' אִיהִי אִימָּא עִלָּאָה, וּבָהּ אִשְׁתְּמַע ה' תַּתָּאָה דְאִיהִי תְּחוֹת י' דְּאִיהִי בְּרַתָּא,</p>\n<p>וְדָא רָזָא דְקָרְבָּנָא, דְצָרִיךְ לְסַלְקָא ה' לְגַבֵּי י', וּלְנַחֲתָא ה' לְגַבֵּי ו'.</p>\n<p>יוה\"ה י' אִיהוּ לִימִינָא חָכְמָה, ו' תּוֹרָה שֶׁבִּכְתָב, מִימִינוֹ אֵשׁ דָּת לָמוֹ (דברים לג ב), וְהַאי אִיהוּ דְאָמְרִין מוֹחַ הַבֵּן דְּאִתְמַשַּׁךְ מִמּוֹחַ הָאָב,</p>\n<p>ה' עִלָּאָה לִשְׂמָאלָא, וּמִתַּמָּן אִתְיְהִיבַת אוֹרַיְיתָא שֶׁבְּעַל פֶּה, דְאִיהִי ה' תַּתָּאָה.</p>\n<p>זַכָּאִין אִינוּן יִשְׂרָאֵל דְּיָדְעִין רָזִין עִלָּאִין בַּהֲוַיּוֹ\"ת, דִּבְהוֹן סָלְקִין צְלוֹתִין בַּהֲבָלִים דְּפוּמְהוֹן, וְנָחֲתִין אִינוּן חֲיָילִין בְּהוֹן כִּדְקָא יָאוּת,</p>\n<p>דְּכַד בַּר נַשׁ סָלִיק שְׁכִינְתֵּיהּ בִּצְלוֹתֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא נָחִית עֲלֵיהּ, הֲדָא הוּא דִכְתִיב (שמות כ כד) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי אָבֹא אֵלֶיךָ וּבֵרַכְתִּיךָ,</p>\n<p>זַכָּאִין אִינוּן יִשְׂרָאֵל דְּאִינוּן רַגְלִין לִשְׁכִינְתָּא, לְמֵיקַם עִמָּהּ בֵּין בְּרֵיוַח בֵּין בְּעָאקוּ,</p>\n<p>דְּכַד אִנּוּן בְּדִינָא</p>"],[9500011070,"<p>בְּיוֹמָא דְּדִינָא דְאִיהִי רֹאשׁ הַשָּׁנָה, אִיהִי קָמַת עִמְּהוֹן לְדִינָא, דְקַיְימִין לָהּ בִּצְלוֹתְהוֹן, דַּעֲלַיְיהוּ אִתְּמַר (משלי ו כב) בְּהִתְהַלֶּכְךָ תַּנְחֶה אוֹתָךְ, בְּשָׁכְבְּךָ תִּשְׁמוֹר עָלֶיךָ, וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ,</p>\n<p>דִּבְכָל אֲתַר דְּקַיְימִין יִשְׂרָאֵל בְּכָל פִּקּוּדָא וּפִקּוּדָא לִשְׁכִינְתָּא, אִיהִי קַיְימַת בְּגִינַיְיהוּ בְּכָל דּוֹחֲקָא וְצַעֲרָא, בֵּין בְּאָרְחָא בֵּין בְּיִשּׁוּבָא בֵּין בְּיַמָּא, וְדָא אִיהוּ בְּהִתְהַלֶּכְךָ בְּמַדְבְּרָא תַּנְחֶה אוֹתָךְ, הֲדָא הוּא דִכְתִיב (תהלים פה יד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו, בְּשָׁכְבְּךָ בְּיִשּׁוּבָא תִּשְׁמוֹר עָלֶיךָ, וַהֲקִיצוֹתָ לְמֵיזַל בְּיַמָּא הִיא תְשִׂיחֶךָ,</p>\n<p>וְעוֹד בְּהִתְהַלֶּכְךָ בְּהַאי עָלְמָא תַּנְחֶה אוֹתָךְ, בְּשָׁכְבְּךָ בַּקֶּבֶר תִּשְׁמוֹר עָלֶיךָ, וַהֲקִיצוֹתָ בִתְחִיַּת הַמֵּתִים הִיא תְשִׂיחֶךָ.</p>\n<p>הָא אִלֵּין נָפְקִין, וְהָא אָחֳרָנִין קָא דָפְקִין לְפִתְחָא, וְאִינוּן מָארֵי רַגְלִין, מִסִּטְרָא דְרַגְלִין דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְּמַר בְּהוֹן (זכריה יד ד) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא, וַעֲלַיְיהוּ אִתְּמַר (שמות יב לז) כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי הַגְּבָרִים לְבַד מִטָּף,</p>\n<p>אִלֵּין נָפְקִין הָא אָחֳרָנִין עָאלִין, מִסִּטְרָא דְאִלֵּין דְּאִתְּמַר בְּהוֹן (יחזקאל א ז) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, רַגְלִין בְּעִגּוּלָא אִינוּן רֶגֶל יְשָׁרָה, וְאִית רַגְלִין אָחֳרָנִין מְרוּבָּעִין דְּאוֹפַנִּים, דְּאִתְּמַר בְּהוֹן (שם יז) עַל אַרְבַּעַת רִבְעִיהֶם בְּלֶכְתָּם יֵלֵכוּ, דִּבְהוֹן וְהַחַיּוֹת רָצוֹא וָשׁוֹב כְּמַרְאֵה הַבָּזָק (שם יד), וְאִנּוּן רַגְלִין בְּעִגּוּלָא, אִינוּן כְּנִקּוּדִין לְאַתְוָון, דְּאִינוּן רַגְלִין בְּרִבּוּעָא.</p>\n<p>וְנָבִיא דְאִיהוּ מִסִּטְרָא דִלְהוֹן, תַּמָּן הֲוָה סָלִיק רוּחֵיהּ, וּמִתַּמָּן הֲוָה שָׁמַע כָּל מַה דַּהֲוָה לֵיהּ לְמִשְׁמַע, הֲדָא הוּא דִכְתִיב (יחזקאל ב א) וַיֹּאמֶר אֵלָי בֶּן אָדָם עֲמֹד עַל רַגְלֶיךָ וַאֲדַבֵּר אוֹתָךְ,</p>\n<p>וְעוֹד (שם ב) וַתָּבֹא בִי רוּחַ כַּאֲשֶׁר דִּבֶּר אֵלַי וַתַּעֲמִדֵנִי עַל רַגְלָי, וָאֶשְׁמַע אֵת מִדַּבֵּר אֵלָי, וַתִּשָּׂאֵנִי רוּחַ וָאֶשְׁמַע אַחֲרַי וְגוֹמֵר (שם ג יב), בְּגִין דְּדַרְגִּין אִינוּן מִסִּטְרָא דִשְׁכִינְתָּא, דְאִתְּמַר בָּהּ (שמות לג כג) וְרָאִיתָ אֶת אֲחוֹרָי, אָמַר וָאֶשְׁמַע אַחֲרַי.</p>\n<p>מָאי קוֹל רַעַשׁ גָּדוֹל, דְּאִית רַעַשׁ וְאִית רַעַשׁ, אִית רַעַשׁ דְּאִתְּמַר בֵּיהּ (מלכים א יט יא) לֹא בָרַעַשׁ יְיָ', דְּלָא יֵיתֵי תַמָּן קוּדְשָׁא בְּרִיךְ הוּא, וְאִית רַעַשׁ דְּיֵיתֵי תַמָּן,</p>\n<p>אֶלָּא רַעַ\"שׁ בְּהִפּוּכָא עִִרֶ\"שׂ, כְּמָה דְאִתְּמַר (תהלים מא ד) יְיָ' יִסְעָדֶנּוּ עַל עִִרֶשׂ דְּוָי, וְדָא אִיהוּ כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ, דְאִתְהַפַּךְ רַעַ\"שׁ לְעִִרֶ\"שׂ, וּמַאי נִיהוּ עִִרֶ\"שׂ, אֶלָּא אִיהוּ עִִשֶׂ\"ר בְּהִפּוּךְ אַתְוָון, וְדָא שְׁכִינְתָּא דְאִיהִי כְלָלָא דְעִִשֶׂר סְפִירָן, דַּעֲלָהּ אִתְּמַר אֵין קְדוּשָׁה בְּפָחוּת מֵעֲשָׂרָה.</p>\n<p>דְאִיהִי שַׁרְיָא לְרֵישָׁא דְחוֹלֶה, וּבְגִינָהּ יְיָ' יִסְעָדֶנּוּ, וּבְמַאי עַל עִִרֶשׂ דְּוָי, עַל שְׁכִינְתֵּיהּ וַדַּאי,</p>\n<p>וְאִם שְׁכִינְתָּא לַאו תַּמָּן, רוּחַ סְעָרָה תַמָּן, דְּאַסְעִיר גּוּפֵיהּ דְּבַר נַשׁ, דִּכְתִיב בֵּיהּ (יונה א ד) וְהָאֳנִיָּה חִשְּׁבָה לְהִשָּׁבֵר, דְּאִיהִי גוּפָא דִסְפִינָה,</p>\n<p>כַּד לֵית שְׁכִינְתָּא סְמִיכַת לָהּ, רוּחַ סְעָרָה מְהַפֵּךְ לָהּ וְתַבַּר לָהּ, וּבְזִמְנָא דִשְׁכִינְתָּא סְמִיכַת לָהּ, מִיָּד קָלָא נָפִיק בֶּן אָדָם עֲמֹד עַל רַגְלֶיךָ (יחזקאל ב א), וְקָאִים מִמַּרְעָא דִילֵיהּ, וְנָפִיק מִדִּינָא, שְׁלִים בְּגוּפֵיהּ שְׁלִים בְּמָמוֹנֵיהּ.</p>\n<p>הָא אִלֵּין נָפְקִין, הָא אָחֳרָנִין דָּפְקִין לְפִתְחָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, וְאִינוּן דִּסְמִיכִין לִשְׁכִינְתָּא בְּכַמָּה רַגְלִין דְּמוֹעֲדִים וְיוֹמִין טָבִין, וְכַד אִלֵּין עָאלִין, קוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ בְּהוֹן, מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב (שיר ז ב),</p>\n<p>דְּאִלֵּין אִינוּן דְּאִתְּמַר בְּהוֹן (דברים טז טז) שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה יֵרָאֶה כָל זְכוּרְךָ,</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה אַנְתְּ שַׁפִּירָא בְּאִלֵּין נְעָלִים דְּאִינוּן נְעִילַת פֶּסַח וּנְעִילַת עֲצֶרֶת וּנְעִילַת חָג,</p>\n<p>חַמּוּקֵי יְרֵכַיִךְ, אִלֵּין אִינוּן מִסִּטְרָא דִתְרֵי יַרְכֵי קְשׁוֹט דְּאִתְּמַר בְּהוֹן שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, וְאִינוּן שִׁית דַּרְגִּין דִּנְבוּאָה.</p>\n<p>מִסִּטְרָא דְאָת ו' דְּאִיהוּ צַדִּיק, עַמּוּד דְּסָמִיךְ לוֹן, וְאִיהוּ שִׁית לָקֳבֵל (מלכים א י יט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, וְסָלִיק בְּאָת י' לְשִׁשִּׁים, כְּגַוְונָא דְשִׁשִּׁים וְשִׁית גַּלְגַּלִּים דְּסַחֲרִין לְכוּרְסַיָּא, וְאִינוּן ס\"ו מִן יְסוֹ\"ד, וְהָא אוּקְמוּהָ, אִשְׁתָּאַר י\"ד, בֵּיהּ וּבְיַד הַנְּבִיאִים אֲדַמֶּה (הושע יב יא), וְדָא שְׁכִינְתָּא יָד חוֹתֶמֶת מִסִּטְרָא דְצַדִּיק, יָד כּוֹתֶבֶת מִסִּטְרָא</p>"],[9500011071,"<p>דְעַמּוּדָא דְאֶמְצָעִיתָא, אִיהִי תְמוּנַת כֹּל, וּבְגִין דָּא (הושע יב יא) וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>הָא אִלֵּין נָפְקִין, הָא אָחֳרָנִין קָא דָפְקִין לְפִתְחָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, וְאִינוּן מָארֵי דְאוֹת, דְּאִיהוּ חַ\"י עָלְמִין, דִּמְצַלִּין בְּחַ\"י בִּרְכָאָן דִּצְלוֹתִין, דִּמְקָרְבִין בְּהוֹן קָרְבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא, דַּחֲשִׁיבָא לָקֳבֵל שִׁבְעָה פָּרִים וְשִׁבְעָה אֵלִים, וְלָקֳבֵל שְׁתֵּי תוֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה, דְּמִסִּטְרָא דְהַאי אוֹת אָמַר לְמֹשֶׁה וְזֶה לְךָ הָאוֹת (שמות ג יב),</p>\n<p>וְאִיהוּ כְלִיל תְּרֵי עֲשַׂר מַזָּלוֹת, וְשִׁבְעָה כֹּכְבֵי לֶכֶת, מִסִּטְרָא דִקְדוּשָׁה, דְאִיהִי בַת שֶׁבַע, וּמִסִּטְרָא דְוו' דְּאִיהוּ ו' עִלָּאָה ו' תַּתָּאָה, וַעֲלַיְיהוּ אִתְּמַר (ירמיה י ב) וּמֵאֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ, כִּי יֵחַתּוּ הַגּוֹיִם מֵהֵמָּה.</p>\n<p>הֵ\"א אִינוּן שִׁית כֹּכְבֵי לֶכֶת, ה' כֹּכָבָא שְׁבִיעָאָה, ו\"ו תְּרֵין עֲשַׂר מַזָּלוֹת, דְּכָל מַזָּל אִתְקְרֵי אוֹת, וְאִיהוּ מְמַנָּא עַל כָּל שַׁעִִתָּא דִתְרֵין עֲשַׂר שַׁעִִתִּין,</p>\n<p>כָּל נָבִיא אִית לֵיהּ מַזָּלֵיהּ וְשַׁעִִתֵּיהּ, וּכְפוּם הַהוּא מַזָּל, וּכְפוּם פְּעוּלָה דִילֵיהּ, הָכִי אִתְגַּלְיָיא לֵיהּ אוֹת מִן וָא\"ו, דִּתְרֵין עֲשַׂר מַזָּלוֹת מְמַנָּן עַל תְּרֵין עֲשַׂר שַׁעִִתִּין, וְעַל תְּרֵין עֲשַׂר יַרְחִין. וְאִלֵּין מַזָּלוֹת מִתַּמָּן הֲווֹ יָרְתִין תְּרֵין עֲשַׂר שִׁבְטִין נִשְׁמָתִין דִּלְהוֹן,</p>\n<p>וְאִית מִסִּטְרָא אָחֳרָא תְּרֵין עֲשַׂר, דְּאִתְּמַר בְּהוֹן (בראשית כה טז) שְׁנֵים עָשָׂר נְשִׂיאִים לְאֻמֹּתָם, דְּאִינוּן אִתְקְרִיאוּ טָלֶ\"ה שׁוֹ\"ר תְּאוֹמִי\"ם סַרְטָ\"ן וְגוֹמֵר, דָּא כְגַוְונָא דְּדָא עָבַד קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>שִׁית מַזָּלוֹת אִינוּן מֵעִילָא לְתַתָּא מֵחֶסֶד וְעַד יְסוֹד, וְשִׁית מִתַּתָּא לְעִילָא מִיסוֹד וְעַד חֶסֶד, מִסִּטְרָא דְמַלְכוּת אִתְקְרִיאוּ שִׁבְעָה כֹּכְבֵי לֶכֶת, מִשְּׁכִינְתָא עַד חֶסֶד, וּכְפוּם פְּעוּלָה דְהַהִיא סְפִירָה הָכִי אִתְגַּלְיָיא אוֹת,</p>\n<p>אוֹת מִסִּטְרָא דְחֶסֶד אִיהוּ רַחֲמֵי, אוֹת מִסִּטְרָא דִגְבוּרָה אִיהוּ דִינָא, וְאַחֲזֵי עַל קָטוֹלָא דְחַיָּיבַיָּא, וּשְׁפִיכוּ דִדְמָא, וְאַחֲזֵי בְצַדִּיקַיָּיא דַם דִּבְעִירָן, לְמֵיכַל בְּחֶדְוָה וְעֹנֶג דְּמַאֲכָלִין בְּחָתָן וְכַלָּה, וּבִשְׁפִיכוּ דִדְמָא דְקָרְבָּנִין, הֲדָא הוּא דִכְתִיב (שמות כ כד) וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךָ וכו', וַעֲלַיְיהוּ אִתְּמַר אֵיזֶהוּ מְקוֹמָן שֶׁל זְבָחִים שְׁחִיטָתָן בַּצָּפוֹן,</p>\n<p>וְעוֹד אַחֲזֵי בְצַדִּיקַיָּיא דַם בְּרִית, דְּאִתְּמַר בָּהּ (יחזקאל טז ו) וָאוֹמַר לָךְ בְּדָמַיִךְ חֲיִי וָאוֹמַר לָךְ בְּדָמַיִךְ חֲיִי.</p>\n<p>מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ אוֹת תָּלוּי אָרוּךְ, אִם זַכְוָון עוֹבָדִין דְּעָלְמָא מַטֶּה כְּלַפֵּי חֶסֶד, וְאִם לַאו כְּלַפֵּי דִינָא, וְהָכִי אִינוּן תְּלַת אָחֳרָנִין כְּגַוְונָא דָא,</p>\n<p>וּלְחַכִּימַיָּא בִרְמִיזָא.</p>\n<p>הָא אִלֵּין נָפְקִין, הָא אָחֳרָנִין דָּפְקִין לְפִתְחָא מִסִּטְרָא דְקֶשֶׁת, דְּאִיהוּ אוּף הָכִי אוֹת בְּרִית, דְּאִתְּמַר בֵּיהּ (שם א כח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם, כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב, הוּא מַרְאֵה דְּמוּת כְּבוֹד יְיָ' וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי, וָאֶשְׁמַע קוֹל מְדַבֵּר, וְאַמַּאי הוּא נְפִיל עַל אַנְפּוֹי, בְּגִין דַּאֲסִיר לְאִסְתַּכְּלָא בַקֶּשֶׁת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא וְאַמַּאי אַסִּיר לְאִסְתַּכְּלָא בַקֶּשֶׁת,</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, בְּרִי בְּגִין אִינוּן קְלִיפִין דְּמִתְלַבְּשִׁין בֵּיהּ וּדְאִינוּן בֵּיהּ, דְּאִינוּן רוּחַ סְעָרָה עָנָן גָּדוֹל וְאֵשׁ מִתְלַקַּחַת וְנֹגַהּ לוֹ סָבִיב, וְדָא אִיהוּ דְחָזָא יְחֶזְקֵאל עָלָיו הַשָּׁלוֹם,</p>\n<p>דְּאָמַר וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, דָּא קַו תֹּהוּ קְלִיפָא יְרוֹקָא דֶאֱגוֹזָא קַו יָרוֹק, עָנָן גָּדוֹל קְלִיפָה תִּנְיָינָא חִוְורָא דֶאֱגוֹזָא, וְדָא בֹהוּ, וְאֵשׁ מִתְלַקַּחַת קְלִיפָה תְלִיתָאָה דֶאֱגוֹזָא וְדָא חֹשֶׁךְ, וְנֹגַהּ לוֹ סָבִיב דָּא קְלִיפָה רְבִיעָאָה דֶּאֱגוֹזָא, דְאִיהִי אִתְאַחֲדָא בְּמוֹחָא, וּמִתּוֹכָם כְּעִין הַחַשְׁמַל דָּא מוֹחָא דֶאֱגוֹזָא, וְדָא יאהדונה\"י.</p>\n<p>וּבְרִי עַד דְּאִלֵּין קְלִיפִין דֶּאֱגוֹזָא מִתְעַבְּרִין וּמִתְתַּבְּרִין, בִּתְקִיעָה וּשְׁבָרִים וּתְרוּעָה, דִּבְהוֹן שְׁבָרִים (שמות כג כד) שַׁבֵּר תְּשַׁבֵּר מַצֵּבוֹתֵיהֶם, דְּאִינוּן קְלִיפִין דֶּאֱגוֹזָא, וּבִתְרוּעָה (תהלים ב ט) תְּרוֹעִם בְּשֵׁבֶט בַּרְזֶל, וּבִתְקִיעָה וְהוֹקַע אוֹתָם לַיְיָ',</p>\n<p>דְּאִלֵּין גָּרְמוּ (בראשית לב כו) דְוַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה, דְאִיהוּ צַדִּיק,</p>\n<p>וְאִתְפָּרַשׁ מִינָהּ שְׁכִינְתָּא, וְאִיהִי בְּגָלוּתָא, וְאִתְדַּבַּק בְּאַתְרָהָא קְלִיפָה דְּעָרְלָה דְאַפְרִיד בֵּין צַדִּיק וּשְׁכִינְתָּא, עַל כֵּן לֹא</p>"],[9500011072,"<p>יֹאכְלוּ בְנֵי יִשְׂרָאֵל אֶת גִּיד הַנָּשֶׁה (שם לב לג), עַד דְּאִתְעַבְּרַת הַאי קְלִיפָה מִתַּמָּן.</p>\n<p>וּבְרִי כָּל זִמְנָא דְאִלֵּין קְלִיפִין לָא מִתְעַבְּרִין מִקֶּשֶׁת, לָא יְהֵא קֶשֶׁת בְּגַוְּונוֹי נְהִירִין,</p>\n<p>וְסִימָנָא דָא יְהֵא בִידָךְ, עַד דְּתֶחזֵי קַשְׁתָּא בְּגַוְּונוֹי נְהִירִין לָא תְצַפֵּי לְרַגְלֵי דִמְשִׁיחָא, וּמִיָּד דִּיְהֵא נָהִיר בְּגַוָּונִין נְהִירִין, מִיָּד וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם (שם ט טז),</p>\n<p>וּמִיָּד אִתְגַּלְיָיא הַהוּא דְאִתְּמַר בֵּיהּ (שמות ג יב) וְזֶה לְּךָ הָאוֹת כִּי אָנֹכִי שְׁלַחְתִּיךָ, לְקַיָּימָא בֵּיהּ כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת (מיכה ז טו),</p>\n<p>בְּהַהוּא זִמְנָא אִתְגַּלְיָיא מַ\"ה שֶּׁ\"הָיָה ה\"וּא שֶׁיִּהְיֶה.</p>\n<p>הָא אִלֵּין נָפְקִין, אָחֳרָנִין דָּפְקִין לְפִתְחָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, וְאִינוּן מָארֵי דְקוֹמָה,</p>\n<p>מִסִּטְרָא דְאִימָּא עִלָּאָה אִתְקְרִיאַת שְׁכִינְתָּא בֶּטֶן, הֲדָא הוּא דִכְתִיב (איוב לח כט) מִבֶּטֶן מִי יָצָא הַקָּרַח, (יחזקאל א כב) כְּעִין הַקֶּרַח הַנּוֹרָא,</p>\n<p>גוּף דִּילָהּ עַמּוּדָא דְאֶמְצָעִיתָא, בֶּטֶן עֲלֵיהּ אִתְּמַר (שיר ז ג) בִּטְנֵךְ עֲרֵמַת חִטִּים. שָׁרְרֵךְ אַגַּן הַסַּהַר אַל יֶחְסַר הַמָּזֶג וְגוֹמֵר (שם),</p>\n<p>שָׁרְרֵךְ דָּא צִיּוֹן, דְּאִיהוּ טַבּוּר עָלְמָא, נְקוּדָה דְמִינָהּ הוּשְׁתַּת הָעוֹלָם, לְאַרְבַּע סִטְרִין דְּאִינוּן מִזְרָח וּמַעֲרָב צָפוֹן וְדָרוֹם,</p>\n<p>וּלְקִבְלַיְיהוּ, רֵישָׁא לְמִזְרָח, גּוּפָא לְמַעֲרָב, דְּרוֹעִין לְדָרוֹם, רַגְלִין לְצָפוֹן,</p>\n<p>אוֹת בְּרִית נְקוּדָה בְּאֶמְצָעִיתָא, כְּגַוְונָא דְטַבּוּר, אַגַּן הַסַּהַר,</p>\n<p>דָּא נְקוּדָה דְסִיהֲרָא כְגַוְונָא דָא כּ, וְהִיא רֵאשִׁית נְקוּדָה בְאָת בּ,</p>\n<p>בַּת קוֹל אִיהִי וַדַּאי, כְּלָלָא דְנִקּוּדִין וְאַתְוָון.</p>\n<p>וְאִיהִי פְתוּחָה כְלַפֵּי צַדִּיקַיָּא וְחַסִּידַיָּא וְחַכִּימַיָּא מָארֵי דְאוֹרַיְיתָא,</p>\n<p>וּפְתִיחָא לְגַבֵּי נְבִיאַיָּיא, וּלְגַבֵּי נַטְרֵי בְרִית, וְכָל אִינוּן דְּתַלְיָין בִּסְפִירָן, דְּאִינוּן שְׁמָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>וְאִיהִי סְתִימָא מִסִּטְרָא אָחֳרָא כְּלַפֵּי רַשִּׁיעַיָּיא, דִבְזִמְנָא דְאַתְיָין לְאִסְתַּכְּלָא בָּהּ, חָזְרַת אַנְפִּין לַאֲחוֹרָא מִנַּיְיהוּ, כְגַוְונָא דָא [ציור].</p>\n<p>וּבְגִין דְּיַעֲקֹב דְּאִיהוּ דִיוֹקְנֵיהּ חֲקוּקָה בְסִיהֲרָא תַמָּן, אִתְּמַר בֵּיהּ (במדבר כג כא) לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל, יְיָ' אֱלֹהָי\"ו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ,</p>\n<p>וְעַל אִינוּן דְּזַרְעָא דְיַעֲקֹב אִתְּמַר (דברים לג כז) וַיִּשְׁכֹּן יִשְׂרָאֵל בֶּטַח בָּדָד עִין יַעֲקֹב, אִתְּמַר הָכָא בָּדָד, וְאִתְּמַר הָתָם בַּאֲתַר אָחֳרָא (שם לב יב) יְיָ' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר,</p>\n<p>דָּא יְהֵא בְיוֹמוֹי דְמַלְכָּא מְשִׁיחָא, דְלָא יְהֵא פְסוֹלֶת בְּיִשְׂרָאֵל, אֶלָּא יְיָ' בָּדָד יַנְחֶנּוּ,</p>\n<p>וּמָאן פְּסוֹלֶת. אִינוּן גֵּרִים, וּבְגִין דָּא אוּקְמוּה מָארֵי מַתְנִיתִין, דְּאֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ.</p>\n<p>וּבְהַהוּא זִמְנָא מִתְפַּשְׁטָא סִיהֲרָא מֵאִלֵּין קְלִיפִין חֲשׁוֹכִין, וּמִתְחַדְּשָׁא בִלְבוּשִׁין שַׁפִּירִין, וְהַאי אִיהוּ חִדּוּשָׁא דְסִיהֲרָא, הֲדָא הוּא דִכְתִיב (בראשית לה יד) וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ, וְאִתְּמַר בָּה (תהלים קג ה) תִּתְחַדֵּשׁ כַּנֶּשֶׁר נְעוּרָיְיכִי,</p>\n<p>וּמִיָּד דְּאִיהִי מִתְחַדְּשָׁא, מִיָּד אִתְקַיַּים קְרָא (יחזקאל לו כז) דִנְבוּאָה בְיִשְׂרָאֵל, וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְגוֹמֵר (שם כו) וְנָתַתִּי בָכֶם לֵב חָדָשׁ, וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם וְגוֹמֵר, וְנִבְּאוּ בְּנֵיכֶם וּבְנוֹתֵיכֶם (יואל ג א).</p>\n<p>הָא אִלֵּין נָפְקִין, הָא מָארֵי דְקוֹמָה קָא דָפְקִין לְפִתְחָא, דְאִיהוּ קוֹמָה דְגוּפָא דְמַלְכָּא, דְאִתְּמַר בֵּיהּ (דניאל י ו) וּגְוִיָּתוֹ כְּתַרְשִׁישׁ, וְהַאי אִיהוּ דְאִתְקְרֵי שָׁמַיִם, דְּבֵיהּ אִתְפַּתְּחוּן חָמֵשׁ נְהוֹרִין, הֲדָא הוּא דִכְתִיב (יחזקאל א א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אלהי\"ם,</p>\n<p>וְאִינוּן חָמֵשׁ נְהוֹרִין דְּאִינוּן ה' סִפְרֵי דְאוֹרַיְיתָא, בְּגִין דְּאִיהוּ ו' וּבֵיהּ אִתְפַּתְּחָן חָמֵשׁ נְהוֹרִין דְּאָת ה', דְּסָלְקִין לְחַמְשִׁין תַּרְעִין דְּחֵירוּ.</p>\n<p>וּבְזִמְנָא דְאִלֵּין דָּפְקִין לְפִתְחָא, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח, אִתְפַּתְּחַת לוֹן תַּרְעָא דְהֵיכָלָא בְּכַמָּה נְהוֹרִין מְרַקְּמָן, נָהֲרִין מִכָּל גַּוָּונִין דְּעָלְמָא,</p>\n<p>וּבְזִמְנָא דְאִלֵּין עָאלִין לְהֵיכָלָא, שְׁכִינְתָּא אוֹלִיפַת זְכוּ עֲלַיְיהוּ, וְאָמְרַת</p>\n<p>רִבּוֹן עָלְמָא, הָא אִלֵּין מָארֵי דְקוֹמָה דְקָא סָגְדִין בִּצְלוֹתָא לְגַבָּךְ אַרְבַּע זִמְנִין, בִּתְלַת קַדְמָאִין תְּרֵי, וּבִתְלַת בַּתְרָאִין תְּרֵי, לָקֳבֵל אַרְבַּע אַתְוָון דִּילָךְ, וְזָקְפִין אַרְבַּע זְקִיפוֹת בְּהוֹן לְאַרְבַּע אַתְוָון דִּילִי דְאִינוּן אדנ\"י, לְסַלְקָא אַרְבַּע דְּאִינוּן</p>"],[9500011073,"<p>אדנ\"י, בְּאַרְבַּע דְּאִינוּן יהו\"ה,</p>\n<p>וְצָרִיךְ לְמִכְרַע בְּכֻלְּהוּ, בְּחַ\"י חוּלְיָין, דְּאִינוּן לָקֳבֵל תַּמְנֵי סְרֵי בִרְכָאָן, דִּכְלִילָן בְּחַ\"י עָלְמִין,</p>\n<p>וְדָא אִיהוּ דְתַקִּינוּ מָארֵי מַתְנִיתִין, עַד דְּיִתְפַּקְקוּ כָּל חוּלְיוֹת שֶׁבַּשִּׁדְרָה,</p>\n<p>וְשִׁדְרָה אִיהוּ לוּלָב, אִם נִפְרְצוּ עַלָּיו פָּסוּל,</p>\n<p>כְּגַוְונָא דָא צָרִיךְ דְּלָא יַפְסִיק בְּתַמְנֵי סְרֵי בִרְכָאָן דִּצְלוֹתָא, דְאִינוּן לָקֳבֵל חַ\"י נִעִִנוּעִין דְּלוּלָב. כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, אֲפִילוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק,</p>\n<p>בְּגִין דְּחַ\"י עָלְמִין אִיהוּ דַאֲחִיד בֵּין יהו\"ה אדנ\"י, כְּגַוְונָא דָא יאהדונה\"י, דְסָלִיק לְחֻשְׁבַּן אָמֵ\"ן, וּבְגִין דָּא אֲפִילוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק, כְּשֶׁהוּא כוֹרֵעַ בְּבָרוּךְ, וּמַה דְּאִתְּמַר אֲבָל עַקְרָב פּוֹסֵק, בְּגִין דְּהָא אוּקְמוּהוּ (ויקרא יח ה) וָחַי בָּהֶם, וְלֹא שֶׁיָּמוּת בָּהֶם.</p>\n<p>וְעוֹד כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, הָא אוּקְמוּהוּ דְצָרִיךְ לִכְלוֹל בֵּיהּ עִִשֶׂר סְפִירָן, דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א, דְּאִינוּן כ' מִן בָּרוּךְ כֶּתֶר, ר' רֵאשִׁית חָכְמָה, ב' תְּרֵין הֵהִי\"ן שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, ו' שִׁית סְפִירָן, הָא עִִשֶׂר,</p>\n<p>וּבְגִינֵיהּ אִתְּמַר (בראשית יד כ) וּבָרוּךְ אֵ\"ל עִִלְיוֹן וְגוֹמֵר, וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל,</p>\n<p>יוֹסֵף בְּגִין דְּזָכָה לְצַדִּיק חַ\"י עָלְמִין, דְּבֵיהּ צָרִיךְ לְמִסְגַּד בְּכָל סְפִירָן לְגַבֵּי שְׁכִינְתָּא, זָכָה לְהַאי חֶלְמָא, הֲדָא הוּא דִכְתִיב (שם לז ט) וְהִנֵּה הַשֶּׁמֶשׁ וְהַיָּרֵחַ וְגוֹמֵר,</p>\n<p>וְנָבִיא דְסָלִיק לְהַאי דַרְגָּא, שִׁמְשָׁא וְסִיהֲרָא וְכֹכְבַיָּא וּמַזָּלֵי, כֻלְּהוּ יָהֲבִין בֵּיהּ נְבִיעוּ בְּנִשְׁמָתֵיהּ, וְרוּחַ דִּנְבוּאָה לְאִתְנַבָּאָה מִכֻּלְּהוּ,</p>\n<p>וְהַאי אִיהוּ מִשְׁתַּחֲוִים לִי, דְּמִכֻּלְּהוּ נָחִית לֵיהּ נְבוּאָה, וּמִכֻּלְּהוּ אִתְכְּלִילַת נִשְׁמָתֵיהּ, וְהַאי אִיהוּ אַגְרָא דְאִלֵּין מָארֵי דְקוֹמָה.</p>\n<p>הָא אִלֵּין נָפְקִין, הָא אָחֳרָנִין דָּפְקִין לְפִתְחָא, וְאִינוּן מָארֵי דְרוֹעִין, וְאָמְרִין אדנ\"י שְׂפָתַי תִּפְתָּח,</p>\n<p>מִיָּד עָאלִין נְטוּרֵי תַּרְעִין, וְאָמְרִין רִבּוֹן עָלְמָא הָא מָארֵי דִדְרוֹעִין קָא דָפְקִין לְפִתְחָא,</p>\n<p>קָלָא נָפִיק וְיֵימָא, הָא אִינוּן מָארֵי דִדְרוֹעִין בְּקִשּׁוּרָא דִתְּפִלִּין, וּבַעֲטִיפוּ דְמִצְוָה, דְאִתְּמַר בְּהוֹן וַיָּשִׂימוּ עַל שְׁכֶם שְׁנֵיהֶם, כְּגַוְונָא דְשֵׁם וָיֶפֶת, דְּאִתְּמַר בְּהוֹן (שם ט כג) וַיִּקַּח שֵׁם וָיֶפֶת אֶת הַשִּׂמְלָה וְגוֹמֵר, וְעִִרְוַת אֲבִיהֶם לֹא רָאוּ,</p>\n<p>עִִרְוָה אִיהִי מִסִּטְרָא דְחָם, וְדָא אִיהוּ יֵצֶר הָרַע, דִּמְחַמֵּם גּוּפֵיהּ לִדְבַר עִִרְוָה (נ\"א עבירה), וְגַלִּי עִִרְיָן בְּעָלְמָא, דְאִיהוּ מִסִּטְרָא דְנָחָשׁ הַקַּדְמוֹנִי, דְאִתְּמַר בֵּיהּ (שם ג יד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, וּבְגִין דְּהַאי אִיהוּ מִסִּטְרוֹי, אָמַר (שם ט כה) אָרוּר כְּנָעַן וְגוֹמֵר.</p>\n<p>וְעוֹד אִלֵּין אִינוּן מָארֵי מַתְּנָן, דְּעָבְדִין גְּמִילוּת חֲסָדִים עִם שְׁכִינְתָּא דְאִיהִי עַנְיָא, דְאִנּוּן (דברים טו יא) פָּתוֹחַ תִּפְתַּח, נָתוֹן תִּתֵּן (שם י), הַעֲנֵק תַּעֲנִיק וכו' (שם יד), עֲשָׂרָה אִינוּן, וְהָא אוּקְמוּהוּ חַבְרַיָּא מָארֵי מַתְנִיתִין,</p>\n<p>וְאִלֵּין אִינוּן יְדֵי נְדִיבִים מִסִּטְרָא דַאֲבָהָן, דְּאִתְּמַר בְּהוֹן (תהלים מז ו) נְדִיבֵי עַמִּים וְגוֹמֵר,</p>\n<p>יְדַיִן פְּתִיחָן בְּוַתְּרָנוּתָא לְגַבֵּי עֲנִיִּין, דְּאִינוּן צַדִּיק וָצֶדֶק, דְּגָמְלִין עִמְּהוֹן בְּגָלוּתָא גְמִילוּת חֲסָדִים, בְּאוֹרַיְיתָא דְאִתְיְיהִיבַת מִימִינָא וּמִשְּׂמָאלָא,</p>\n<p>הֲדָא הוּא דִכְתִיב (שם מב ט) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי, אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה, דְּמִתַּרְוַיְיהוּ אִתְיְהִיבוּ, הֲדָא הוּא דִכְתִיב (דברים לג ב) מִימִינוֹ אֵשׁ דָּת לָמוֹ.</p>\n<p>וְעוֹד רִבּוֹן עָלְמָא, קַבֵּל דּוֹרוֹנָא דִלְהוֹן, דְּאִיהִי מַתָּנָה טוֹבָה דְסָלְקָא עֲלַיְיהוּ, דְּאִתְּמַר בָּהּ מַתָּנָה טוֹבָה יֵשׁ לִי בְּבֵית גְּנָזַי וְשַׁבָּת שְׁמָהּ, אִלֵּין אִינוּן דַּהֲווֹ עָבְדִין צְדָקָה עִמָּהּ, דְּאִיהִי צ' תִּשְׁעִין אֲמֵנִים, ד' אַרְבַּע קְדוּשׁוֹת, ק' מֵאָה בִרְכָאָן, ה' חֲמִשָּׁה חוּמְשֵׁי תוֹרָה,</p>\n<p>מִיָּד וִידֵי אָדָם (יחזקאל א ח) דְּאִינוּן חֶסֶד וּגְבוּרָה, הֲווֹ נָפְקִין מֵאָדָם דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, לְקַבְּלָא דוֹרוֹנָא דִלְהוֹן, וְיָהֲבִין לֵיהּ לְמַלְכָּא,</p>\n<p>דְּאִלֵּין דְּלָא עָבְדִין גְּמִילוּת חֲסָדִים עִם שְׁכִינְתֵּיהּ בְּגָלוּתָא, וְאִינוּן קַמְצָנִין לְגַבָּהּ, דּוֹרוֹנָא דִלְהוֹן לְכַלְבָּא אִתְמַסַּר,</p>\n<p>וְדוֹרוֹנָא דִשְׁכִינְתָּא צָרִיךְ לְמֶעֱבַד בְּגִינָהּ מֵהַהוּא חָבִיב דְּאִית לֵיהּ,</p>"],[9500011074,"<p>כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, וְאָהַבְתָּ אֵת יְיָ' וְגוֹמֵר (דברים ו ה), בְּהַהוּא דְאִיהוּ חָבִיב עֲלָךְ,</p>\n<p>בְּהַהוּא זִמְנָא כַּמָּה חֵיוָון פָּתְחִין יְדַיְיהוּ, דְאִתְּמַר בְּהוֹן (יחזקאל א ח) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, יָהֲבֵי דוֹרוֹנָא לְנִשְׁמָתָא דְהַהוּא בַר נַשׁ, מִכַּמָּה מַתְּנָן טָבִין, מִכַּמָּה דַרְגִּין דִּנְבוּאָה,</p>\n<p>וְעַל כֻּלְּהוּ יְהִיבַת לֵיהּ שְׁכִינְתָּא מַתְּנָן, דְּאִתְּמַר בָּהּ יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ, בְּגִין (קהלת ג יג) דְּמַתַּת אלהי\"ם הִיא,</p>\n<p>וְהַהוּא דְאִתְּמַר בֵּיהּ (תהלים קמה טז) פּוֹתֵחַ אֶת יָדֶיךָ וכו', יְהִיב לֵיהּ כַּמָּה מַתְּנָן טָבִין, וּפַרְנָסָה לְנִשְׁמָתֵיהּ וּלְגוּפֵיהּ,</p>\n<p>וְכֻלְּהוּ דְעָאלִין, כַּד נָפְקִין מִבֵּי מַלְכָּא, יָהֲבִין תְּלַת פְּסִיעָן לַאֲחוֹרָא, דְלָא חָזְרִין כִּתְפַיְיהוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>דְלֵית דּוֹרוֹנָא חֲבִיבָא קֳדָם קוּדְשָׁא בְּרִיךְ הוּא כְּדוֹרוֹנָא דִשְׁכִינְתָּא.</p>\n<p>זַכָּאִין אִינוּן דְּרוֹעִין דְּסָלְקִין לָהּ לְגַבֵּיהּ, תְּפִלִּין עַל יְדַיְיהוּ וְעַל רֵישַׁיְיהוּ,</p>\n<p>זַכָּאִין אִינוּן רַגְלִין וְגוּפָא וִידַיִן וְכָל אֵבֶר וְאֵבֶר, דְּבֵיהּ סָלִיק דּוֹרוֹנָא לְקוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>דְלֵית דּוֹרוֹנָא חֲבִיבָא קֳדָם קוּדְשָׁא בְּרִיךְ הוּא כְּדוֹרוֹנָא דִשְׁכִינְתָּא,</p>\n<p>זַכָּאָה אִיהוּ אֵבֶר דְּעָבִיד בֵּיהּ מִצְוָה לְקוּדְשָׁא בְּרִיךְ הוּא, דִבְגִינָהּ נָחִית קוּדְשָׁא בְּרִיךְ הוּא לְשַׁרְיָיא בְּכָל אֵבֶר דִּילֵיהּ, וְעַל הַאי בַּר נַשׁ מַכְרִיזִין לְעִילָא, הָבוּ יְקָר לְדִיּוֹקְנָא דְמַלְכָּא.</p>\n<p>בְּרֵישׁ הוּרְמָנוּ דְמַלְכָּא, בּוֹצִינָא דְקַרְדִּינוּתָא, לָא חִוָּור וְלָא סוּמָק וְלָא יָרוֹק וְלָא אוּכָּם כְּלָל.</p>\n<p>וְהַאי בּוֹצִינָא אִיהוּ קַו הַמִּדָּה, דְאִיהוּ אִתְלַבַּשׁ בְּאַוִּירָא,</p>\n<p>וְכַד אִיהִי בְאַוִּירָא. אִיהִי סְתִימָא וְלָא אִתְחַזְיָיא כְלָל,</p>\n<p>וְכַד אִתְפַּשְּׁטַת לְאִתְגַּלְיָא, נָפִיק מֵהַאי אַוִּירָא נְקוּדָה חֲדָא, וּמַה דְּאִשְׁתָּאַר אִיהוּ אוֹר, וְהַאי אִיהוּ אוֹר קַדְמָאָה דְעוֹבָדָא דִבְּרֵאשִׁית, הֲדָא הוּא דִכְתִיב (בראשית א ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר, יְהִי י' אַוִּיר, וְרָזָא דָא לְחַכִּימֵי לִבָּא אִתְמַסַּר.</p>\n<p>וְהַאי נְקוּדָה בָתַר דְּאִתְפַּשַּׁט מֵהַאי אוֹר, אִתְלַבְּשַׁת בְּגַּוָּונִין אַרְבַּע עִלָּאָה, וּמָאי אִיהִי בּ וַעֲלָהּ אִתְּמַר (משלי כד ג) בְּחָכְמָה יִבָּנֶה בָּיִת,</p>\n<p>וְרָזָא דְהַאי נְקוּדָה אִיהִי מָדִיד חָמֵשׁ גַּוָּונִין, וַעֲלַיְיהוּ אִתְּמַר (ישעיה מ יב) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְדָא אָ, וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן וְדָא אִ, וְכָל בַּשָּׁלִישׁ עֲפַר הָאָרֶץ וְדָא אְ, (נ\"א א), וְשָׁקַל בַּפֶּלֶס הָרִים וְדָא אֵ, וּגְבָעוֹת בְּמֹאזְנָיִם וְדָא אֻ,</p>\n<p>דָּא סָלִיק בְּאַוִּירָא, וְדָא אָזִיל לְצָפוֹנָא, וְדָא לְדָרוֹמָא, הֲדָא הוּא דִכְתִיב (קהלת א ו) הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, תְּרֵין אָחֳרָנִין סוֹבֵב סוֹבֵב לְגַבֵּי מִזְרָח וּמַעֲרָב, דְּאִינוּן כֻּלְּהוּ נְקוּדֵי כְּגַלֵּי יַמָּא, דָּא סָלִיק וְדָא נָחִית.</p>\n<p>וְאִינוּן כְּחוּטָא חִוְורָא דְעִינָא, דְאִיהוּ אַסְחַר עִינָא, וּכְחוּטָא יְרוֹקָא וְאוּכְמָא וְסוּמָקָא וְתִכְלָא,</p>\n<p>אִלֵּין גַּלְגַּלִּין כֻּלְּהוּ סָחֲרִין לְהַהוּא נְקוּדָה, וְאִיהִי מִדָּה לְכֻלְּהוּ, אִיהִי בְּאַרְבַּע, וְסָלְקָא בְעִִשֶׂר, וְרָזָא דְמִלָּה יהו\"ה יו\"ד ה\"א וא\"ו ה\"א, אִלֵּין אִינוּן אַרְבַּע גַּוָּונִין דְּסָלְקִין בְּעִִשֶׂר,</p>\n<p>וְאִנּוּן כֻּלְּהוּ לַהֲבִיּוֹת אִשִּׁיּוֹת, וַעֲלֵיהוֹן אִתְּמַר (דברים ד כד) כִּי יהו\"ה אלהי\"ך אֵשׁ אֹכְלָה הוּא,</p>\n<p>שֶׁבַע אִינוּן מֵהַאי עִִשֶׂר, וְאִינוּן לָקֳבֵל שִׁבְעָה רְקִיעִין, וְאִינוּן שֶׁבַע סְפִירָאן, וּבֵין כָּל חַד וְחַד חֲמֵשׁ מְאָה שְׁנִין,</p>\n<p>וְהָכִי פוּתְיָא דְכָל רְקִיעָא וּרְקִיעָא חֲמֵשׁ מְאָה שְׁנִין עַד דְּסָלְקִין כֹּלָּא לְמִדָּה יְדִיעָא דְּאִיהִי נְקוּדָה חֲדָא, לִחְשִׁבַּן יְדִיעָא,</p>\n<p>וְהָכִי אִיהוּ רָזָא דְחוּשְׁבָּנָא כְּגַוְונָא דָא [ציור]</p>\n<p>תֵּשַׁע נְקוּדִין אִינוּן לְכָל סְטַר, דְּאִתְכְּלִילָן בִּנְקוּדָה דְחָלָל דִּילָהּ, וּבְגִינָהּ אִתְּמַר (שמות לא יד) מְחַלֲלֶיהָ מוֹת יוּמָת וכו'.</p>\n<p>קָם הַהוּא סָבָא וְאָמַר לוֹ רַבִּי רַבִּי בְּאוֹמָאָה עֲלָךְ בְּהַאי נְקוּדָה טְמִירָא עִלָּאָה, נְחִית הָכָא לְגַלָּאָה רָזָא טְמִירָא, וְלָא לִיקָרָא דִילִי עֲבִידְנָא, אֶלָּא לִיקָרָא דִשְׁכִינְתָּא, לְאַחֲזָאָה יְקָרָא דְהַאי נְקוּדָה טְמִירָא גְנִיזָא, דְאִתְּמַר בָּהּ (איוב כח כא) וְנֶעִִלְמָה מֵעִינֵי כָל חָי, וַעֲלָהּ אִתְּמַר נָתִיב לֹא יְדָעוֹ עָיִט וְגוֹמֵר,</p>\n<p>אַדְהָכִי הָא רַבִּי סָלִיק לְעִילָא בְאַוִּירָא לְנַטְלָא רְשׁוּ מֵהַהִיא נְקוּדָה דְאִיהִי גְנִיזָא תַמָּן,</p>\n<p>וְהָא קָא נָחִית בְּעַמּוּדָא דְאֶשָּׁא דְאִיהִי הֲבַל דְּפוּמָא, דְּבֵיהּ חֵיוָון רָצִין וְשָׁבִין, הֲדָא הוּא דִכְתִיב (יחזקאל א יט) וְהַחַיּוֹת רָצוֹא וָשׁוֹב וְגוֹמֵר,</p>\n<p>וְאָמַר בְּרֵאשִׁית תַּמָּן בַּ\"ת.</p>"],[9500011075,"<p>בְּרֵאשִׁית תַּמָּן בַּ\"ת, וְהַאי בַּת נְקוּדָה סְתִימָא בְאַוִּירָא, עֲלָהּ אִתְּמַר (תהלים יז ח) שָׁמְרֵנִי כְּאִישׁוֹן בַּת עָיִן, אִיהִי וַדַּאי גְּנִיזָא בְאוֹר, וּבָהּ אִתְעֲבִיד אַוִּיר,</p>\n<p>וּבְגִינָהּ אִתְּמַר (שמות ג ב) וַיֵּרָא מַלְאַךְ יהו\"ה אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה, חָמֵשׁ זִמְנִין אַדְכִּיר סְנֶה, וְחָמֵשׁ זִמְנִין אוֹר אִינוּן לְקִבְלַיְהוּ בְעוֹבָדָא דִבְּרֵאשִׁית, וְאִינוּן (בראשית א ג ד) יְהִי אוֹר, וַיְהִי אוֹר, אֶת הָאוֹר כִּי טוֹב, וַיַּבְדֵל אלהי\"ם בֵּין הָאוֹר, וַיִּקְרָא אלהי\"ם לָאוֹר.</p>\n<p>וְאִינוּן חָמֵשׁ תִּקּוּנִין דְּמִדָּה, דְאִינוּן לְקִבְלַיְיהוּ אָאֵאֹאִאֻ,</p>\n<p>וַעֲלַיְיהוּ אִתְּמַר (ישעיהו מ יב) מִי מָדַד בְּשָׁעֳלוֹ מַיִם דָּא חֶסֶד, וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן מָאי זֶרֶת דָּא גְּבוּרָה, וְכָל בַּשָּׁלִישׁ דָּא עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ תְּלִיתָאֵי, וְשָׁקַל בַּפֶּלֶס הָרִים דָּא נֶצַח, וּגְבָעוֹת בְּמֹאזְנָיִם דָּא הוֹד,</p>\n<p>וְאִינוּן בְּרָזָא דְאָת ה', דְּהַאי נְקוּדָה מָדִיד בְּהוֹן ה' נְקוּדִין. דְּאִיהִי דְּנָפִיק מִגּוֹ אַוִּירָא דַכְיָא, דְאִיהוּ כֶתֶר עִלָּאָה, וּבְגִין דְּאִלֵּין חָמֵשׁ מְדִידִין אִינוּן בְּרָזָא דְה' עִלָּאָה, אִיהוּ אָזִיל בְּהוֹן חֲמֵשׁ מְאָה שְׁנִין בֵּין כָּל חַד וְחַד,</p>\n<p>וְרָזָא דְמִלָּה עִץ הַחַיִּים מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה, וּבֵין כָּל חַד וְחַד חֲמֵשׁ מֵאוֹת שָׁנָה, וּבְעוֹבִי דְכָל חַד וְחַד חֲמֵשׁ מֵאוֹת שָׁנָה, דְּכֻלְּהוּ סָלְקִין בְּמַתְקְלָא דְחָמֵשׁ חָמֵשׁ לְכָל סִטְרָא.</p>\n<p>וְרָזָא דְמִלָּה וְעָשִׂיתָ בְרִיחִם עֲצֵי שִׁטִּים חֲמִשָּׁה לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הָאֶחָד, וַחֲמִשָּׁה בְרִיחִם לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הַשֵּׁנִית, וַחֲמִשָּׁה בְרִיחִים לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן לַיַּרְכָתַיִם יָמָּה (שמות כו כו), לַיַּרְכָתַיִם אִינוּן יַרְכֵי קְשׁוֹט, יָמָּה, מָאי יָמָּה דָא שְׁכִינְתָּא עִלָּאָה, הַהוּא דְאִתְּמַר בֵּיהּ (יחזקאל א כב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ.</p>\n<p>וְאִיהוּ דְאוּקְמוּהוּ אֵין בֵּין מַיִם הָעִִלְיוֹנִים לַמַּיִם הַתַּחְתּוֹנִים אֶלָּא כִּמְלֹא נִימָא, וְהַאי נִימָא עֲלֵיהּ אִתְּמַר אֵין מַלְכוּת נוֹגַעַת בַּחֲבֵרְתָּהּ אֲפִילוּ כִּמְלֹא נִימָא, וּבָהּ קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק עִם צַדִּיקַיָּיא אֲפִילוּ כְּחוּט הַשַּׂעֲרָה, וְהַאי חוּט אִיהוּ חוּט דְּסָחִיר לְאוֹת בְּרִית מִילָה, וּבְרִית אִיהִי נִימָא,</p>\n<p>וַוי לוֹן מָאן דְּאַפְרִישׁ אוֹת בְּרִית בֵּין מַיִם לַמַּיִם, וּמָנַע זַרְעָא מִנֵּיהּ, דְּאַחְזַר עָלְמָא לְתֹהוּ וָבֹהוּ, וְרָזָא דְמִלָּה (ישעיהו מח יח) לֹא תֹהוּ בְרָאָהּ לָשֶׁבֶת יְצָרָהּ וַדַּאי,</p>\n<p>מַיִם עִִלְיוֹנִים אוֹרַיְיתָא דְבִכְתָב, מַיִם תַּחְתּוֹנִים אוֹרַיְיתָא דִבְעַל פֶּה, נִימָא דְאִיהוּ בֵין תַּרְוַיְיהוּ דָא יְסוֹד, דְּאִיהוּ רָזָא דְאוֹרַיְיתָא, וְאִיהוּ יְסוֹדָא וְעִקָּרָא דְתַרְוַיְיהוּ.</p>\n<p>וּמָאן דְּמָנַע רָזָא דְעִקָּרָא דִתְרֵי תוֹרוֹת, כְּאִלּוּ אַהְדַּר עָלְמָא לְתֹהוּ וָבֹהוּ, וְאִלֵּין אִינוּן דְּאָמְרִין דְּלָא אוֹרַיְיתָא אֶלָּא כִּפְשָׁטָה, וְלֵית בָּהּ רָזָא אָחֳרָא,</p>\n<p>וְאִינוּן דּוּ פַּרְצוּפִין, אִיהוּ גַ\"ן סְדָרִים דְּאִתְּמַר בָּהּ (שיר ד יב) גַּן נָעוּל אֲחוֹתִי כַלָּה, גַּן נָעוּל מִסִּטְרָא דְם' סְתוּמָה,</p>\n<p>ו' אִיהוּ נָעוּל בְּשִׁית יוֹמֵי דְשָׁבוּעַ, הֲדָא הוּא דִכְתִיב (יחזקאל מו א) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ,</p>\n<p>וּבְשַׁבָּת בְּגִין דְּלָא תְהֵא כְּנוֹעִל דֶּלֶת בִּפְנֵי לָוִוין, דְּאִתְּמַר בְּהוּ לְווּ עָלַי וַאֲנִי פוֹרֵעַ, אִיהִי פְּתִיחָא לְגַבַּיְיהוּ דְאִינוּן נִשְׁמָתִין יְתֵירִין. וּבְאִלֵּין דְּלָא מַלְוִוין לָהּ וְלָא אוֹסִיפִין לְשַׁבָּתוֹת וּלְיָמִים טוֹבִים, אִיהִי סְתִימָא לְהוֹן, וּבְגִין דָּא כָּל הַמּוֹסִיף מוֹסִיפִין לֵיהּ, וְדָא תוֹסֶפֶת נִשְׁמָתָא יְתֵירָא, וְאִיהִי תוֹסֶפֶת רוּחָא דִקְדוּשָׁה, וְכָל הַגּוֹרֵעַ גּוֹרְעִין לֵיהּ הַהִיא נְשָׁמָה יְתֵירָה, וְאִשְׁתָּאַר עָנִי, וְאִם הוּא חָכָם אִסְתַּלַּק מִנֵּיהּ חָכְמָתֵיהּ, וְאִם הוּא עָשִׁיר בְּמָמוֹנָא אִסְתַּלַּק מִנֵּיהּ, וְאִשְׁתָּאַר עָנִי יָבֵשׁ, כְּמָה דְאִיהוּ</p>"],[9500011076,"<p>מָנַע מִלְּעִילָא נִשְׁמָתָא יְתֵירָה דְאִיהוּ נִשְׁמַת כָּל חַי, וְאִשְׁתָּאַר יוֹם הַשַּׁבָּת עָנִי וּשְׁכִינְתָּא יְבֵשָׁה, הָכִי אִתְמַנַּע בִּרְכָאָן מִנֵּיהּ, וְאִיהוּ מִדָּה כְּנֶגֶד מִדָּה,</p>\n<p>וְכָל מָאן דְּאוֹסִיף בְּשַׁבָּת, אָז וּכְגַנָּה זֵרוּעִִיהָ תַצְמִיחַ (ישעיהו סא יא). אוּף הָכִי נַמִּי אַצְמִיחַ טוֹבָה דִילֵיהּ,</p>\n<p>וּמָאן זֵרוּעִִיהָ דִשְׁכִינְתָּא לְעִילָא, אִינוּן נְשָׁמוֹת יְתֵירוֹת דְּזַרְעִין מִנֵּיהּ, וְיֶחדוּן לוֹן לְיִשְׂרָאֵל לְתַתָּא מִזִּיו כְּבוֹדָהּ.</p>\n<p>וּבְזִמְנָא דְהַהִיא ם' סְתִימָא אִתְפַּתְּחַת, לָא אִתְפַּתְּחַת אֶלָּא בְּפִיּוּסָא, כְּמָה דְאַתְּ אָמַר (שיר ה ב) פִּתְחִי לִי אֲחוֹתִי רַעִִיָתִי יוֹנָתִי תַמָּתִי שֶׁרֹאשִׁי נִמְלָא טָל,</p>\n<p>וְהַאי פִּיּוּסָא לְגַבֵּי ו' דְּאִיהוּ מַפְתְּחָא דְסָתִים לָהּ, וּבְגִין דָּא פִּתְחִי לִי בְיוֹמָא קַדְמָאָה, לְמָאן לְאָת י' דְּאִיהִי נְקוּדָה דְקָמֵ\"ץ, כַּד אִתְפַּתְּחַת אִתְפַּתְּחַת בְּפַתָח דְּאִיהוּ ו', כַּד סָתִים סָתִים בְּקָמֵ\"ץ, וְאִיהוּ י\"ו טִפָּה וְזֶרַע דְּאִתְמַשַּׁךְ מִנֵּיהּ.</p>\n<p>וּבְגִין דָּא פִּתְחִי לִי בְיוֹמָא קַדְמָאָה לְאָת י' דְּאִיהִי נְקוּדָה דְקָמֵץ, אֲחוֹתִי בְיוֹמָא תִנְיָינָא, רַעִִיָתִי בְּיוֹמָא תְלִיתָאָה, דְאִיהוּ רַעִִיָא מְהֵימְנָא, יוֹנָתִי בְיוֹמָא רְבִיעָאָה, תַמָּתִי בְיוֹמָא חֲמִשָּׁאָה, תַּם עֲוֹנֵךְ בַּת צִיּוֹן, שֶׁרֹאשִׁי בְיוֹמָא שְׁתִיתָאָה, דְאִתְּמַר (בראשית מז לא) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה דְאִיהוּ יוֹם הַשִּׁשִּׁי, נִמְלָא טָל בְּיוֹמָא שְׁבִיעָאָה, דָא טִפָּה י' וַדַּאי, וְדָא נְקוּדָה דְאָת ב'.</p>\n<p>וּבְגִין דָּא זִוּוּגָא דְתַלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת, לְיַרְתָא הַהִיא טִפָּה דְאִיהִי חָכְמָה, טַ\"ל תּוֹרָה לִבְנַיְיהוּ, וְלַאו לְמַגָּנָא אוּקְמוּהוּ זִכְרוֹנָם לִבְרָכָה, כָּל הָעוֹסֵק בְּטַל תּוֹרָה טַל תּוֹרָה מְחַיֵּיהוּ.</p>\n<p>גַּל נָעוּל (שיר ד יד) גַּל אִיהוּ כְּמוֹ גַלְגַּל, אִיהוּ רְמִיז דְּבֵיהּ מַעִִיָן חָתוּם דְּאִיהִי י', וּמִיַּד הַשְׁקוּ הַצֹּאן דְּאִינוּן אֵבָרִין קַדִּישִׁין, דְּאִתְּמַר בְּהוֹן (יחזקאל לד לא) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, כֻּלְּהוּ רוֹעִים, וּמֹשֶׁה עַל כֻּלְּהוֹן, דִּכְתִיב (שמות ב טו) וַיֵּשֶׁב עַל הַבְּאֵר, וּכְתִיב (תהלים צ א) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאלהי\"ם וכו',</p>\n<p>אִיהוּ שׁוּלְטָנוּתֵיהּ בְּשִׁבְעָה רְקִיעִין. צַדִּיק אִיהִי רָקִיעַ דְּפַלִּיג בֵּין מַיָּא לְמַיָּא, בֵּין יָם עִלָּאָה דְאִיהִי אִימָּא עִלָּאָה, וּבֵין יָם תַּתָּאָה דְאִיהִי אִימָּא תַּתָּאָה,</p>\n<p>וַעֲלֵיהּ אִתְּמַר אֵין בֵּין מַיִם הָעִִלְיוֹנִים לְמַיִם הַתַּחְתּוֹנִים אֶלָּא כִּמְלֹא נִימָא, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, וְהַאי נִימָא אִיהוּ צַדִּיק, וְלַאו לְמַגָּנָא אוּקְמוּהוּ קַדְמָאִין, דְּקוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים אֲפִילוּ כְּחוּט הַשַּׂעֲרָה.</p>\n<p>וְלֵית נִימָא וְנִימָא דְשַׂעֲרָה דְעַתִּיקָא קַדִּישָׁא דְלָא נָפְקָא מִמַּבּוּעָא עִלָּאָה, וְהַאי נִימָא אִיהוּ ו', מַבּוּעָא דִילֵיהּ י', דְּסָלְקָא בְאַוִּירָא עַד אֵין סוֹף וְנָחְתָא עַד אֵין תַּכְלִית.</p>\n<p>וְאִיהִי עִִשֶׂר, וּבְגִינָהּ אִתְּמַר (שמות כו טז) עִִשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, אַמּוֹ\"ת אִינוּן מֵאוֹ\"ת בְּהִפּוּכָא, וְאַמָּה וַחֲצִי הָאַמָּה רֹחַב הַקֶּרֶשׁ הָאֶחָד, דָּא רָזָא דְשִׁעוּר קוֹמָה, דְאִיהוּ אָזִיל עַל קַ\"ו הַמִּדָּה, מַאי קַ\"ו דָּא אָת ו', דְּאִיהוּ מִדָּה לְכָל שִׁעוּרָא דְגוּפָא.</p>\n<p>אִיהוּ מִדָּה בֵּין עִינָא לְעִינָא, וַעֲלָהּ אִתְּמַר (שם ה טו) אֶצְבַּע אלהי\"ם הִיא, אִיהוּ שִׁיעוּרָא דְאוּרְכָא דְחוֹטָמָא וְאִיהִי שִׁעוּרָא דְכָל אֶצְבְּעָא וְאֶצְבְּעָא וְשִׁעוּרָא בֵּין אֶצְבְּעָא לְאֶצְבְּעָא ו' (נ\"א י').</p>\n<p>י' אִיהִי מִדָּה דְשָׂפָה, וּמִדָּה דְכָל עִינָא וְעִינָא בְּעִגּוּלָא, וּמִדָּה דְפַן וּפַן דְּאַנְפִּין, וּמִדָּה דְקָמֵ\"ץ סָתִים,</p>\n<p>וְכַד אִתְפַּתַּח קָמֵ\"ץ אִתְפַּתַּח בְּחָמֵשׁ אֶצְבָּעִין בְּרָזָא דְה', דִּבְהוֹן הַאי קַו אָזִיל חֲמֵשׁ מְאָה שְׁנִין.</p>\n<p>וְכַד (ס\"א ו' כד) נָחִית לְתַתָּא לְגַבֵּי צַדִּיק אִתְקְרֵי שִׁיעוּר, וְכַד סָלִיק לְעִילָא לְגַבֵּי אִימָּא עִלָּאָה אִתְקְרֵי קוֹמָה,</p>\n<p>וְרָזָא דְמִלָּה (שם טז יח) וַיָּמֹדּוּ בָעֹמֶר דָּא שְׁכִינְתָּא עִלָּאָה, דְאִיהִי עֹמֶר לַגֻּלְגֹּלֶת, דְּאִיהִי גֻלְגַּלְתָּא דְרֵישָׁא,</p>\n<p>וּשְׁכִינְתָּא תַּתָּאָה אִיהִי סְפִירַת הָעוֹמֶר, דְּבָהּ מָנֵי שֶׁבַע יוֹמִין דְּאִינוּן שֶׁבַע שַׁבָּתוֹת, דְּאִית בְּהוֹן אַרְבָּעִין וּתְרֵין יוֹמִין דְּשִׁיתָּא דְכָל שָׁבוּעַ, וְשֶׁבַע</p>"],[9500011077,"<p>שַׁבָּתוֹת</p>\n<p>הָא מ\"ט (נ\"א דמטטרו\"ן), דְּאִינוּן מ\"ט אַנְפִּין טָהוֹר, שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד,</p>\n<p>דִּבְהוֹן אִתְדַּכִּיאַת שְׁכִינְתָּא תַּתָּאָה לְגַבֵּי בַּעִִלָהּ, בְּמִקְוְה דִּילָהּ, דְּאִיהוּ מִקְוִה יִשְׂרָאֵל יהו\"ה,</p>\n<p>וְאִיהוּ שִׁיעוּר קוֹמָה, דְּהָכִי אִינוּן אַתְוָון דְּמִקְוְה קוֹמָה, וְאִינוּן ם סְתִימָא בְרָזָא דָא, [ציור]</p>\n<p>וְאִינוּן לְקִבְלַיְיהוּ תְּרֵין שִׂפְוָון דְּאִתְקְרוּן אֲפִיקֵי מָיִם, וּמָאן נִינְהוּ נֶצַח וָהוֹד, דְּאִתְקְרוּן שִׁקְתוֹת הַמָּיִם, וְתַרְוַיְיהוּ אִתְשַׁקְיָין עַל יְדָא דְצִנּוֹרָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא דִכְלִיל כֹּלָּא, וְאִיהוּ בְּרִית דִּכְלִילָן בֵּיהּ כָּל אֵבָרִין דְּגוּפָא, כָּל צִנּוֹרִין אִינוּן אִתְשַׁקְיָין מִן אָת ו', דְּאִיהוּ נָהָר דְּנָגֵיד וְנָפֵיק מֵעִדֶן, וְאִיהוּ צִנּוֹר דְּנָפִיק מִמַּעֲיָנָא דְמַיָּא דְאִיהוּ י', וּמִנֵּיהּ אִתְפַּשְׁטָא ה' דְּאִיהִי יָם עִלָּאָה.</p>\n<p>דְתֵשַׁע נְקוּדִין לְכָל סְטַר, בִּנְקוּדָה דְאֶמְצָעִיתָא אִשְׁתַּלִּימוּ לְאַרְבָּעִים סָאִין, אִיהוּ שִׁיעוּרָא דְמִקְוְה, דְּבֵיהּ אִתְדַּכִּיאַת אִתְּתָא לְבַעִִלָהּ.</p>\n<p>וְקֳדָם דְּאִתְדַּכִּיאַת, צָרִיךְ לְמַנָּאָה שִׁבְעָה יוֹמִין דְּדַכְיוּ, לְאַשְׁלָמָא בְּהוֹן מ\"ט פָּנִים דַּכְיוּ דְאוֹרַיְיתָא,</p>\n<p>וּבְהוֹן אִתְחַבְּרַת אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה בְּיוֹמָא דְשָׁבוּעוֹת, דְּאִינוּן דּוּ פַּרְצוּפִין דְּאָדָם, וְחִבּוּרָא דְתַרְוַיְיהוּ רֶחֶ\"ם, דְּאִיהוּ רְמַ\"ח פִּקּוּדִין דַּעֲשֵׂה,</p>\n<p>וְרָזָא דְמִלָּה (שמות יג ב) קַדֶּשׁ לִי כָל בְּכֹר פֶּטֶר כָּל רֶחֶם, בְּהַאי חִבּוּרָא דְשָׁבוּעוֹת מִתְקָרְבִין כָּל פִּקּוּדִין דַּעֲשֵׂה, כַּעֲצָמִים בְּבֶטֶן הַמְּלֵאָה (קהלת יא ה).</p>\n<p>וּבְהַהוּא זִמְנָא, כָל אִינוּן אֵבָרִין מְקַבְּלִין עַל יְדֵי צִנּוֹרִין דָּא מִן דָּא, הֲדָא הוּא דִכְתִיב (שמות כו ה) מַקְבִּילוֹת הַלֻּלָאוֹת אִשָּׁה אֶל אֲחֹתָהּ,</p>\n<p>וְכַד אִינוּן מְקַבְּלִין, כָּל סְפִירָאן מְקַבְּלִין דָּא מִן דָּא, וּמַלְאָכִין לְתַתָּא מְקַבְּלִין דֵּין מִן דֵּין, כְּמָה דְאַתְּ אָמַר וּמְקַבְּלִין דֵּין מִן דֵּין, וְכָל חַד וְחַד יָהִיב רְשׁוּ לְחַבְרֵיהּ, לְאַעָלָא בִּתְחוּמָא דְחַבְרֵיהּ, כְּמָה דְאַתְּ אָמַר וְנוֹתְנִין רְשׁוּת זֶה לָזֶה.</p>\n<p>וּמָאן גָּרִים דָּא, יִשְׂרָאֵל כַּד מְקַבְּלִין דָּא מִן דָּא, בֵּין בְּאוֹרַיְיתָא בֵּין בְּמָמוֹנָא, גָּרְמִין לְקַבְּלָא לְעִילָא דָא מִן דָּא, וּלְאַשְׁפָּעָא דָא לְדָא, וְכֹלָּא עַל יְדֵי צִנּוֹרִין, הֲדָא הוּא דִכְתִיב (תהלים מב ח) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךָ וְגוֹמֵר,</p>\n<p>וּמַאי אַמְרֵי דָא לְדָא, אַבַּע מֵימֶיךָ. קוֹל שְׁנֵי רֵיעִים אֲנִי שׁוֹמֵעַ.</p>\n<p>וְאִינוּן לְקִבְלַיְיהוּ תְּרֵין שִׂפְוָון דְּאִתְקְרוּן אֲפִיקֵי מָיִם, וּמָאן נִינְהוּ נֶצַח וָהוֹד, דְּאִתְקְרוּן שִׁקְתוֹת הַמָּיִם, וְתַרְוַיְיהוּ אִתְשַׁקְיָין עַל יְדָא דְצִנּוֹרָא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא דִכְלִיל כֹּלָּא, וְאִיהוּ בְּרִית דִּכְלִילָן בֵּיהּ כָּל אֵבָרִין דְּגוּפָא,</p>\n<p>כָּל צִנּוֹרִין אִינוּן אִתְשַׁקְיָין מִן אָת ו', דְּאִיהוּ נָהָר דְּנָגֵיד וְנָפֵיק מֵעִדֶן, וְאִיהוּ צִנּוֹר דְּנָפִיק מִמַּעֲיָנָא דְמַיָּא דְאִיהוּ י', וּמִנֵּיהּ אִתְפַּשְׁטָא ה' דְּאִיהִי יָם עִלָּאָה.</p>\n<p>וְתָא חֲזִי תֵּשַׁע נְקוּדִין אִינוּן מִן קָמֵ\"ץ עַד שׁוּרֵ\"ק, וְכֻלְּהוּ אִתְקְרִיאוּ צִנּוֹרִין וּמַבּוּעִין לְאַתְוָון, דְּאִינוּן כְּלִילָן בְּקַרְקַע, דְּאִיהִי שְׁכִינְתָּא תַּתָּאָה, דְּאִתְקְרִיאַת גַּ\"ן, כְּלִילָא מִתְּלַת וְחַמְשִׁין סְדָרִין דְּאוֹרַיְיתָא,</p>\n<p>וַעֲלָהּ אִתְּמַר גַּן נָעוּל אֲחֹתִי כַלָּה, גַּל נָעוּל מַעִִיָן חָתוּם, חָתוּם וַדַּאי, בְּגִין דְּאִיהִי בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ,</p>\n<p>וְאִיהִי חָכְמַת שְׁלֹמֹה, דַעֲלָהּ אִתְּמַר (מלכים א ה ו) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, אִתְרַבִּיאַת מִכָּל שַׁקְיוּ דְכָל סְפִירָה וּסְפִירָה, עַל יְדָא דְהַהוּא צִנּוֹרָא דְאִיהוּ ו', עַד דִּמְטִיאַת לְהַהוּא מַבּוּעָא עִלָּאָה דְאִיהִי י' עִלָּאָה חָכְמַת כָּל בְּנֵי קֶדֶם, וּבְהַהוּא זִמְנָא אִתְעֲבִידַת אִיהִי תַּגָּא בְּרֵישָׁא דְאָת ו'.</p>\n<p>וְתָא חֲזִי, שְׁכִינְתָּא תַּתָּאָה כַּד אִיהִי אִתְשַׁקְיָא מִן נְקוּדִין, אִתְקְרֵי חִרֵ\"ק חֹלֵ\"ם שׁוּרֵ\"ק, לְמָאן לְהַהוּא צִנּוֹר דְּאִיהוּ ו', דִּכְלִילָן שִׁית צִנּוֹרִין, דְּכֻלְּהוֹן מִשִּׁית אַתְוָון, דְּאִינוּן אבגית\"ץ וכו', שִׁית צִנּוֹרִין אִינוּן דְּתַלְיָין מִנֵּיהּ, וְאִיהוּ כְּלִיל שִׁית אָחֳרָנִין, וְכֻלְּהוּ סָלְקִין לְמ\"ב, אִתְקְרִיאַת חִרֵ\"ק חֹלֵ\"ם שׁוּרֻ\"ק דְּהַהוּא צִנּוֹר, כְּגַוְונָא דָא וִֹּ.</p>\n<p>וְהָכִי אִתְקְרִיאַת לְגַבֵּי י', וְהָכִי לְגַבֵּי ה', וְרָזָא דְמִלָּה אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וכו',</p>\n<p>וּלְזִמְנִין אִיהִי עֲטָרָה עַל רֵישָׁא דְאָת ו', כְּגַוְונָא דָא [ציור] וְרָזָא דְמִלָּה נוֹטֶה שָׁמַיִם כַּיְרִיעָה, וְדָא רָזָא דְרֵישָׁא דְאָת א,</p>\n<p>וּלְזִמְנִין נָחִית תְּחוֹתוֹי כְּגַוְונָא דָא א קָמֵ\"ץ,</p>\n<p>כַּד סָלְקָא עַל רֵישָׁא אִתְקְרִיאַת תַּגָּא זַרְקָ\"א, בְּהַהוּא זִמְנָא אִתְּמַר בָּהּ (משלי יב ד) אֵשֶׁת חַיִל עֲטֶרֶת בַּעִִלָהּ, וְאִתְקְרִיאַת חֹלֵ\"ם, וְכַד נָחְתַת תְּחוֹתֵיהּ אִתְקְרִיאַת חִירֵ\"ק, וְאִיהִי</p>"],[9500011078,"<p>לֶחֶ\"ם, דְּהָכִי אִיהוּ חֹלֵ\"ם בְּהִפּוּךְ אַתְוָון לֶחֶ\"ם, וְדָא אִיהוּ לֶחֶם אַבִּירִים אָכַל אִישׁ (תהלים עח כה), דְּאִתְּמַר בֵּיהּ (שמות טו ג) יהו\"ה אִישׁ מִלְחָמָה,</p>\n<p>מִסִּטְרָא דְחָכְמָה אִתְקְרִיאַת חֹלֵ\"ם, וּמִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִתְקְרֵי שׁוּרֻ\"ק, כְּמָה דְאַתְּ אָמַר (ירמיהו ג כא) וְאָנֹכִי נְטַעִִתִּיךְ שׂוֹרֵ\"ק כֻּלֹּה זֶרַע אֱמֶת, הַהוּא דְאִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב,</p>\n<p>מִסִּטְרָא דִילֵיהּ אִתְקְרִיאַת חִרֵ\"ק, וּבְהִפּוּךְ אַתְוָון חֵקֶ\"ר, וּבְגִינָהּ אִתְּמַר (איוב יא ז) הַחֵקֶר אֱלוֹהַּ תִּמְצָא, וְאִיהִי קֶרַח הַנּוֹרָא, דְאִיהוּ שְׁמָא תְּלִיתָאָה דִצְלוֹתָא, דְּאִתְּמַר בֵּיהּ הָאֵ\"ל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, הַנּוֹרָא אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>וְשׁוּרֻ\"ק אִיהוּ טָמִיר וְגָנִיז, מִסִּטְרָא דְצַדִּיק דְּאִיהוּ בְרִית, אוֹר גָּנוּז. דְּאִיהוּ רָ\"ז כְּחוּשְׁבַּן אוֹר,</p>\n<p>כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, אוֹר זָרוּעַ לַצַּדִּיק, וְדָא הוּא אוֹר הַגָּנוּז לְצַדִּיקַיָּא,</p>\n<p>דְּחָמֵשׁ אוֹר דִּלְעִילָא מִנֵּיהּ כֻּלְּהוֹן אִינוּן בְּאִתְגַּלְיָיא. וּמַאי נִיהוּ, תְּלַת אוֹר סֶגוֹ\"ל, וּתְרֵין אוֹר שְׁבָ\"א, כַּד סָלְקָא עַל גַּדְפַיְיהוּ דִתְרֵין נְקוּדִין דְּאִינוּן שְׁבָ\"א, אִתְעֲבִידַת שׁוּרֵ\"ק,</p>\n<p>וְרָזָא דְמִלָּה (שיר ב ה) סַמְּכוּנִי בָאֲשִׁישׁוֹת, וְכַד נָחְתַת אִיהִי תְּחוֹת צֵרִ\"י אִתְעֲבִידַת סֶגוֹ\"ל וַעֲלַיְהוּ אִתְּמַר רַפְּדוּנִי בַּתַּפּוּחִים,</p>\n<p>וּמַאי נִיהוּ אִלֵּין אֲשִׁישׁוֹת, אִינוּן תְּרֵי אֵשׁוֹת, דְּאִינוּן אִישׁ וְאִשָּׁה, אֶשָּׁא חִוְורָא, וְאֶשָּׁא סוּמְקָא, דְתַמָּן אָב וָאֵם, דְּאִינוּן י\"ה, וְאִינוּן אַנְפֵּי דִינָא וְאַנְפּוֹי דְרַחֲמֵי.</p>\n<p>אַמָּאי בָּעָאת לְאִסְתַּמְכָא תַמָּן, בְּגִין דְּאִינוּן תְּרֵין גַּוְונִין דְּשׁוֹשַׁנָּה, חִוָּור וְסוּמַק, רַחֲמֵי וְדִינָא, דְּאִינוּן חֶסֶד וּגְבוּרָה,</p>\n<p>וְתַמָּן רֵיחָא דְשׁוֹשַׁנָּה, וְדָא אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וּבְגִין דְּאָרְחַת בֵּיהּ, אָמְרַת סַמְּכוּנִי בָּאֲשִׁישׁוֹת,</p>\n<p>וּבֵיהּ אִתְעֲבִידַת סֶגוֹ\"ל, כַּד נָחְתָא רַפְּדוּנִי בַּתַּפּוּחִים, אִלֵּין אִינוּן תְּרֵי סַמְכֵי קְשׁוֹט, דְּאִינוּן חִוָּור וְסוּמַק, וּבְגִין דְּאָרְחַת בְּאָת ו' דְּאִיהִי בִּבְרִית, אָמְרַת רַפְּדוּנִי בַּתַּפּוּחִים.</p>\n<p>וְכַד אִתְחַבְּרַת בֵּיהּ אִתְעֲבִידַת סֶגוֹ\"ל, מַה דַּהֲווֹ צֵרִ\"י אִתְעֲבִיד צִיֵּיר, הֲדָא הוּא דִכְתִיב (בראשית ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹמֵר,</p>\n<p>וַיַּצְמַח יהו\"ה אלהי\"ם מִן הָאֲדָמָה כָּל עִץ נֶחְמָד לְמַרְאֶה וְגוֹמֵר, דָּא צַדִּיק אִיהוּ עִץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ, וּבְהַאי אֲתַר אִיהוּ רְחִימוּ דִילָהּ בְּחִבּוּרָא וְיִחוּדָא דְבַעִִלָהּ, וּבְגִין דָּא אָמְרַת (שיר ב ה) כִּי חוֹלַת אַהֲבָה אָנִי.</p>\n<p>וְכַד יִשְׂרָאֵל חָאבִין בִּבְרִית מִילָה, אִתְפַּסִּיק נְבִיעוּ דִנְקוּדִין מֵאַתְוָון, דִּכְלִילָן בִּשְׁכִינְתָּא תַּתָּאָה, וְאִשְׁתְּאָרַת יַבָּשָׁה, בְּהַהוּא זִמְנָא מַה כְּתִיב בְּשׁוּרֻ\"ק חִירֵ\"ק, שָׁרְקוּ וַיַּחַרְקוּ שֵׁן אָמְרוּ בִּלָּעִִנוּ (איכה ב טז),</p>\n<p>קָמֵץ פַּתָּ\"ח דָּא סָגִיר וְדָא פָּתַח, אִלֵּין תְּרֵין אִינוּן דְּסָגְרִין וּפָתְחִין מַבּוּעִין דְּאִינוּן נְקוּדִין, לְגַבֵּי אַתְוָון,</p>\n<p>וְאָת ו' כַּד אִיהוּ נָטוּי עַל רֵישֵׁי אַתְוַון עִלָּאִין אִתְקְרֵי רָפֵ\"ה, וְכַד אִיהוּ בִּמְצִיעוּ דְאַתְוָון אִתְקְרֵי דָגֵ\"שׁ,</p>\n<p>אַתְוָון אִלֵּין אִינוּן חֵיוָון, דְּאִתְּמַר בְּהוֹן (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, רָצוֹא בְדָגֵ\"שׁ וָשׁוֹב בְּרָפֵ\"ה.</p>\n<p>כִּתְרִין דְּאַתְוָון דְּאִינוּן תַּלְיָין בְּמַחֲשָׁבָה, דְאִינוּן כְּגַוְונָא דְתַגִּין,</p>\n<p>נְקוּדִין תַּלְיָין בְּדִבּוּרָא, אַתְוָון תַּלְיָין בְּעוֹבָדָא,</p>\n<p>שֶׁבַע זַיְינִין אִינוּן כְּגַוְונָא דָא [ציור] [ציור]</p>\n<p>י\"ו אִיהוּ ז', לָא צְרִיכִין תַּגִּין, דְּאִינוּן אַתְוָון אִתְקְרוּן תַּגִּין כְּגַוְונָא דָא יהו\"ה.</p>\n<p>תַּגִּין תַּלְיָין בְּמַחֲשָׁבָה דְלִבָּא וּמוֹחָא, נְקוּדִין בְּדִבּוּרָא דְפוּמָא, אַתְוָון בְּעוֹבָדָא דְאֵבָרִין,</p>\n<p>דְאֵבָרִין, וּמֵאִלֵין נְקוּדִין וְטַעֲמֵי וְאַתְוָון, עָבִיד הַהוּא סָתִים וְגָנִיז כָּרְסַיָּיא טְמִירָא עִלָּאָה, וַעֲלֵיהּ אִתְּמַר (איכה ה יט) אַתָּה יהו\"ה לְעוֹלָם תֵּשֵׁב וכו', מַאי אַתָּה, הַהוּא דְאִתְּמַר בֵּיהּ (ישעיהו כה א) יהו\"ה אלה\"י אַתָּה אֲרוֹמִמְךָ,</p>\n<p>בְּהַהוּא דְאִתְּמַר בֵּיהּ (חבקוק ג ו) רוֹם יָדֵיהוּ נָשָׂא, וּבְגִינֵיהּ אִתְּמַר לְמִי נוֹשְׂאִין כַּפַּיִם לְרוּם הַשָּׁמַיִם, הֲדָא הוּא דִכְתִיב רוֹם יָדֵיהוּ נָשָׂא, וּמַאי נִיהוּ יו\"ד ה\"א וא\"ו ה\"א, דְאִיהוּ חָכְמָה כֹּ\"חַ מָ\"ה, וַעֲלֵיהּ אִתְּמַר</p>"],[9500011079,"<p>(תהלים קיא ו) כֹּ\"חַ מַ\"עֲשָׂיו הִ\"גִּיד לְעַמּוֹ,</p>\n<p>וְהַאי אִיהוּ כ\"ח פִּרְקִין דִּיְדִין דְּמַלְכָּא עִלָּאָה, דְּאִינוּן כוז\"ו במוכס\"ז כוז\"ו, כִּנּוּיִין דְּיִחוּדָא עִלָּאָה, דְאִיהוּ יהו\"ה אלהינ\"ו יהו\"ה, וּבְגִין דְּאִסְתַּלַּק הַאי חֵילָא מִיִּשְׂרָאֵל, אִתְּמַר בְּהוֹן (איכה א ו) וַיֵּלְכוּ בְלֹא כֹחַ לִפְנֵי רוֹדֵף.</p>\n<p>יו\"ד ה\"א וא\"ו ה\"א, אִינוּן עֲשַׂר אֶצְבְּעָאן, דְּאִתְּמַר בְּהוֹן (שיר ח יד) יָדָיו גְּלִילֵי זָהָב, דִּבְהוֹן כ\"ח פִּרְקִין, דְּאִינוּן כ\"ח אַתְוָון דְּעוֹבָדָא דִבְּרֵאשִׁית,</p>\n<p>וּבְגִין דָּא יהו\"ה אלה\"י אַתָּה, וּמַאי אַתָּה, הַהוּא דְאִתְּמַר בֵּיהּ (תהלים צג ב) נָכוֹן כִּסְאֲךָ מֵאָז מֵעוֹלָם אָתָּה,</p>\n<p>וּמַאי נָכוֹן, דָּא נֶאֱמָן יוֹשֵׁב וְנֶאֱמָן עוֹמֵד בְּאֶמְצַע, הֲדָא הוּא דִכְתִיב (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, וּמַאי מֵאָז, אֶלָּא הַהוּא דְאִתְּמַר בֵּיהּ (שם נח ט) אָז תִּקְרָא וַיהו\"ה יַעֲנֶה, וּמַאי אָ\"ז אִלֵּין תְמַנְיָא אַתְוָון דְּאִינוּן יאהדונה\"י דְסָלְקִין לְחוּשְׁבַּן אָמֵ\"ן.</p>\n<p>וְדָא אִיהוּ הָעוֹנֶה אָמֵן בְּכָל כֹּחוֹ, בְהַהוּא כ\"ח, וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, הָעוֹנֶה אָמֵן בְּכָל כֹּחוֹ קוֹרְעִין לוֹ גְזַר דִּינוֹ שֶׁל שִׁבְעִים שָׁנָה,</p>\n<p>וּבְגִינֵיהּ אִתְּמַר (תהלים צג ב) נָכוֹן כִּסְאֲךָ מֵאָז מֵעוֹלָם אָתָּה, וּבֵיהּ (איכה ה יט) אַתָּה יהו\"ה לְעוֹלָם תֵּשֵׁב, אַתָּה, הַהוּא דְאִתְּמַר בֵּיהּ אָבִינוּ מַלְכֵּנוּ אָבִינוּ אָתָּה, וּמַאי נִיהוּ אָבִינוּ אָב הָרַחֲמָן.</p>\n<p>וְאִיהוּ כְלִיל כָּל אַתְוָון דְּאוֹרַיְיתָא, וּמַאי נִיהוּ אוֹרַיְיתָא דְבִכְתָב עַמּוּדָא דְאֶמְצָעִיתָא, וַעֲלֵיהּ אִתְּמַר בָּרוּךְ אַתָּה,</p>\n<p>וְכַד יִשְׂרָאֵל קַיְימִין בַּעֲמִידָה דִצְלוֹתָא, אִיהוּ יְתִיב עַל כָּרְסַיָּיא, וּבְגִינֵיהּ אִתְּמַר בְּהַהוּא זִמְנָא אַתָּה יהו\"ה לְעוֹלָם תֵּשֵׁב כִּסְאֲךָ לְדוֹר וָדוֹר, וּמַאי נִיהוּ לְדוֹר וָדוֹר, אֶלָּא הַהוּא דְאִתְּמַר בֵּיהּ (קהלת א ד) דּוֹר הוֹלֵךְ וְדוֹר בָּא וְהָאָרֶץ לְעוֹלָם עֹמָדֶת,</p>\n<p>וְלֵית דּוֹר פָּחוּת מִשִּׁשִּׁים רִבּוֹא, וּמַאי נִיהוּ, מֹשֶׁה דְשָׁקוּל לְשִׁתִּין רִבּוֹא מִיִשְׂרָאֵל, וְדַרְגָּא דִילֵיהּ אַסְפַּקְלַרְיָאָה דְנַהֲרָא.</p>\n<p>בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ (ויקרא טז ג),</p>\n<p>תָּא חֲזִי אֵין אָדָם מֵפִיק רְצוֹנוֹ מֵיהו\"ה אֶלָּא בְזֹאת, דַּעֲלָהּ אִתְּמַר (משלי יח כב) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵיהו\"ה,</p>\n<p>וְדָא הִיא עִת לַעֲשׂוֹת לַיהו\"ה (תהלים קיט קכו), וְכַמָּה עִתּוֹת יֵשׁ, וַעֲלַיְיהוּ אִתְּמַר (ויקרא טז ב) וְאַל יָבֹא בְכָל עִת, וּשְׁלֹמֹה אָמַר (קהלת ג ד) עִת לִשְׂחוֹק וכו', דְּאִינוּן כ\"ח עִת,</p>\n<p>וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא אָמַר וְאַל יָבֹא בְכָל עִת אֶל הַקֹּדֶשׁ, דְּאִיהוּ קֹדֶשׁ יִשְׂרָאֵל לַיהו\"ה.</p>\n<p>וְכַד שְׁכִינְתָּא דְאִתְקְרִיאַת זֹאת עִם יִשְׂרָאֵל, כְּמָה דְאַתְּ אָמַר (ויקרא כו מד) וְאַף גַּם זֹאת בִּהְיוֹתָם וכו', מַאי אִינוּן אָמְרִין לָהּ (שיר ו א) אָנָה הָלַךְ דּוֹדֵךְ הַיָּפָה בַּנָּשִׁים, אָנָה פָּנָה דוֹדֵךְ וּנְבַקְשֶׁנּוּ עִמָּךְ, בְּכַמָּה תַחֲנוּנִים וּצְלוֹתִין, בַּצִּיצִית וּבִתְפִלִּין, בְּשַׁבָּתוֹת וּבְיוֹמִין טָבִין, דַּעֲלַיְיהוּ אִתְּמַר (שמות לא יז) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעוֹלָם, אוֹת בְּרִית מִילָה, אוֹת דְּשַׁבָּת וְיֹמִין טָבִין, וְאוֹת דִּתְּפִלִּין.</p>\n<p>עֲלָהּ אִתְּמַר (תהלים לב ו) עַל זֹאת יִתְפַּלֵּל כָּל חָסִיד אֵלֶיךָ לְעִת מְצֹא, מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵיהו\"ה (משלי יח כב),</p>\n<p>וְיַעֲקֹב בָּרֵיךְ לִבְנוֹי בְּזֹאת, הֲדָא הוּא דִכְתִיב (בראשית מט כח) וְזֹאת אֲשֶׁר דִּבֶּר לָהֶם אֲבִיהֶם,</p>\n<p>וְדָוִד בְּזֹאת הֵפִיק רְצוֹנוֹ מֵיהו\"ה כְּשֶׁנִּלְחַם עִם אוֹיְבָיו, כְּמָה דְאַתְּ אָמַר (תהלים כז ג) אִם תַּחֲנֶה עָלַי מַחֲנֶה וכו', בְּזֹאת אֲנִי בוֹטֵחַ,</p>\n<p>וְהַנָּבִיא כְּשֶׁרָאָה אֶת יִשְׂרָאֵל בַּגָּלוּת, לֹא רָאָה לָהֶם מְנוּחָה אֶלָּא בַעֲבוּר זֹאת, וּפוּרְקָנָא דְיִשְׂרָאֵל לָא יֵיתֵי אֶלָּא בְזֹאת, הֲדָא הוּא דִכְתִיב (איכה ג כא) זֹאת אָשִׁיב אֶל לִבִּי עַל כֵּן אוֹחִיל,</p>\n<p>וִיהוּדָה לָא אִתְבָּרֵיךְ אֶלָּא בְזֹאת, הֲדָא הוּא דִכְתִיב (דברים לג ז) וְזֹאת לִיהוּדָה,</p>\n<p>וּמֹשֶׁה לָא בָּרֵיךְ יָת יִשְׂרָאֵל אֶלָּא בְּזֹאת (שם א) וְזֹאת הַבְּרָכָה,</p>\n<p>וּמִי שֶׁלֹּא שָׁת לִבּוֹ גַּם לָזֹאת, עֲלֵיהּ כְּתִיב (תהלים צב ז) אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת.</p>\n<p>וְכֵיוָן שֶׁהָאָדָם בָּהּ יָפִיק רְצוֹנוֹ, וּבָהּ מַשִּׂיג הַשֵּׁם, שֶׁזֶּהוּ סוֹד עַל זֹאת יִתְפַּלֵּל כָּל חָסִיד, עַל זֹאת וַדַּאי, לְשֵׁם יהו\"ה שֶׁהוּא עַל זֹאת,</p>\n<p>לָמָּה תִּקְנוּ בְּשַׁחֲרִית לְמִדָּה יְדוּעָה, וְכֵן בַּמִּנְחָה לְמִדָּה יְדוּעָה, וְכֵן בְּעַרְבִית לְמִדָּה יְדוּעָה, וְכֵן בְּשַׁבָּת לְמִדָּה יְדוּעָה, וְכֵן בְּיוֹם טוֹב לְמִדָּה יְדוּעָה, וְכֵן בַּעֲשֶׂרֶת יְמֵי תְשׁוּבָה לְמִדָּה יְדוּעָה,</p>\n<p>אֶלָּא מַה שֶּׁאָמַר עַל זֹאת, הוּא מוֹרֶה שֶׁהֲוַיָּ\"ה הִיא עַל כָּל סְפִירָה</p>"],[9500011080,"<p>וּסְפִירָה, כְּמוֹ שֶׁאָמַר דָּוִד (ד\"ה א כט יא) לְךָ יהו\"ה הַגְּדוּלָה וְהַגְּבוּרָה וְגוֹמֵר,</p>\n<p>וְאֵין לָךְ פְּעוּלָה בַּתַּחְתּוֹנִים אֶלָּא עַל יְדֵי מַלְכוּת, שֶׁנֶּאֱמַר בָּהּ (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה,</p>\n<p>אֲבָל בִּזְמָן שֶׁצָּרִיךְ קוּדְשָׁא בְּרִיךְ הוּא לְהַצְדִּיק לַצַּדִּיק, וְלַעֲשׂוֹת עִמּוֹ צְדָקָה שֶׁהִיא מַלְכוּת, עִם הַתַּחְתּוֹנִים, נִכְלָלִים בּוֹ כָל הַסְּפִירוֹת, וְנִקְרָאִין צַדִּיקִים עַל שְׁמוֹ, יהו\"ה נִקְרָא עַל שְׁמוֹ צַדִּיק, שֶׁנֶּאֱמַר (תהלים קמה יז) צַדִּיק יהו\"ה בְּכָל דְּרָכָיו, וּמְרַחֵם עַל בִּרְיוֹתָיו בִּצְדָקָה,</p>\n<p>אֵין צְדָקָה אֶלָּא תְפִלָּה, צ' אֲמֵנִים, ד' קְדוּשׁוֹת, ק' בְּרָכוֹת, ה' חֲמִשָּׁה חוּמְשֵׁי תוֹרָה,</p>\n<p>וְזֶהוּ צְדָקָה תְרוֹמֵם גּוֹי (משלי יד לד), וְעָלָיו נֶאֱמַר לְאַבְרָהָם (בראשית טו ו) וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה, וּכְשֶׁהוּא רוֹצֶה בָּהּ נֶאֱמַר בָּהּ (ישעיה נט יז) וַיִּלְבַּשׁ צְדָקָה כַּשִּׁרְיָן.</p>\n<p>מִצַּד ה הִיא צְדָקָה, וּמִצַּד י הִיא כּוֹבַע עַל רֹאשׁ צַדִּיק אוֹת בְּרִית, עֲטָרָה בְּרֹאשׁ כָּל צַדִּיק, וּמִצַּד ו נֶאֱמַר בָּהּ (איוב יא ט) אֲרוּכָּה מֵאֶרֶץ מִדָּהּ, מִצַּד ה עִִלְיוֹנָה וּרְחָבָה מִנִּי יָם.</p>\n<p>וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַמְשִׁיךְ נְבוּאָה, כָּל הַסְּפִירוֹת כְּלוּלִים בָּהֶם, וְנִקְרָאִים נְבִיאִים,</p>\n<p>וּמַלְכוּת הִיא דִמְיוֹן כֻּלָּם, שֶׁנֶּאֱמַר (הושע יב יא) וּבְיַד הַנְּבִיאִים אֲדַמֶּה, כְּמוֹ שֶׁאָמַר הַנָּבִיא (שם) וְדִבַּרְתִּי עַל הַנְּבִיאִים וְגוֹמֵר, שֶׁהִיא כְמוֹ הָאַסְפַּקְלַרְיָאָה שֶׁכָּל הַפָּנִים נִרְאִין בָּהּ, כֵּן כָּל הַסְּפִירוֹת מַרְאִין בָּהּ כֹּחָם וְדִמְיוֹנָם וְצוּרֹתָם, לְכָל נָבִיא כְּפִי הַשָּׂגָתוֹ לְמַעִִלָה,</p>\n<p>וּכְמוֹ כֵּן לְמַטָּה הִיא מִתְלַבֶּשֶׁת בַּכִּסֵּא הַכָּבוֹד, וּבְכָל הַמַּלְאָכִים, וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ, וּבְכָל הָרְקִיעִים, וְהַכִּסְאוֹת שֶׁבָּהֶם, וְהַמַּלְאָכִים הַתְּלוּיִם מֵהֶם,</p>\n<p>שֶׁיֶּשׁ מַלְאָכִים גְּבוֹהִים עֲלֵיהֶם, שֶׁנֶּאֱמַר (קהלת ה ז) כִּי גָבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר וּגְבוֹהִים עֲלֵיהֶם,</p>\n<p>וְכֵן בְּכָל כּוֹכָב וּמַזָּל, כְּמוֹ שֶׁכָּתוּב (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, וְזֶהוּ וּבְיַד הַנְּבִיאִים אֲדַמֶּה (הושע יב יא),</p>\n<p>וּלְכָל אֶחָד נִדְמֶה כְּפִי כֹּחוֹ שֶׁהִיא נִשְׁמָתוֹ, וְהָבֵן אָמֵן בְּכָל כֹּחוֹ.</p>\n<p>יהו\"ה הוּא בְכֶתֶר, שֶׁהָיָה קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם הוּא וּשְׁמוֹ לְבָד בַּכֶּתֶר, כְּשֶׁבָּרָא הָעוֹלָם בְּמִדַּת רֵאשִׁית יָרַד עָלָיו, וְלֹא הָיָה חָסֵר מִלְּמָעִִלָה, וְכֵן בְּכָל סְפִירָה, כְמַדְלִיק נֵר מִנֵּר וְאֵינוֹ חָסֵר מִן הָרִאשׁוֹנָה וְלֹא מֵחֲבֶרְתָּהּ, עַד אֵין סוֹף וְאֵין תַּכְלִית.</p>\n<p>וּמִי שֶׁמַּכִּיר אוֹתוֹ בְזֹאת, כְּמוֹ שֶׁמַּכִּיר אוֹתוֹ בָעִִלְיוֹנִים וּבַתַּחְתּוֹנִים, בַּעֲבוּר שֶׁהִיא כְלוּלָה מֵהָעִִלְיוֹנִים, וְאִיהִי יִחוּד וְקֶשֶׁר כֻּלָּם, וְהִיא מִתְלַבֶּשֶׁת בַּתַּחְתּוֹנִים,</p>\n<p>וְעַל זֶה אָמַר הַנָּבִיא (ירמיה יט כג) אַל יִתְהַלֵּל הַמִּתְהַלֵּל כִּי אִם בְּזֹאת,</p>\n<p>הִיא אִתְקְרִיאַת נְבוּאָה מִסִּטְרָא דִנְבִיאַיָּא, חָכְמָה מִסִּטְרָא דְחַכִּימַיָּיא, דְכָל סְפִירָן אִתְקְרִיאוּ חֲכָמִים.</p>\n<p>וְכ\"ח אַתְוָון אִינוּן לְכָל עוֹבָדָא דִבְּרֵאשִׁית, וְכֻלְּהוֹן אִינוּן בֵּין לִכְתִיבָה בֵּין לְכָל מִלָּה דְיִתְעֲבִיד בַּיְדִין, דְּעוֹבָדָא דְכ\"ח פִּרְקִין אִינוּן בַּעֲשַׂר אֶצְבְּעָאן,</p>\n<p>וְדָא אִיהוּ רָזָא מֵהַכֹּחַ אֶל הַפּוֹעִל, וְכֹלָּא בְחָכְמָה, וְרָזָא דְמִלָּה (תהלים קד כד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>\n<p>אִית חָכְמָ\"ה מִסִּטְרָא דְאַתְוָון, וְאִית חָכְמָה מִסִּטְרָא דִנְקוּדִין, דְּאַתְוָון אִינוּן בַּת קוֹל, וּבְהוֹן רָזָא דְדִבּוּרָא לִדְרָשָׁא וּלְכָל מִלָּה דְתַלְיָיא בִדְרָשָׁא,</p>\n<p>תַּגִּין אִינוּן לְמַחֲשָׁבָה, וְאִינוּן בְּרָזָא דְהַאי קְרָא (שמות לא ד) וְלַחֲשׁוֹב מַחֲשָׁבוֹת וכו', וְכֻלְּהוֹן תַּלְיָין בִּשְׁכִינְתָּא תַתָּאָה, וְאִיהִי כְלָלָא דְכֻלְּהוּ.</p>\n<p>וּבְרָזָא דְא תִשְׁכַּח טַעֲמִין וּנְקוּדִין וְאַתְוָון, וְהָכִי בְּכָל אָת וְאָת,</p>\n<p>וְרָזָא דְמִלָּה [ציור] תְּלַת תַּגִּין לְעִילָא כְּמוֹ זַיְינִין דְּסֵפֶר תּוֹרָה, בָּהּ רְשִׁימִין (ס\"א רמיזין) כִּתְרִין וּנְקוּדִין וְאַתְוָון, וְהָכִי בְכָל אָת וְאָת,</p>\n<p>ש שַׁבָּת הַגָּדוֹל בִּינָה, שַׁבָּת הַקָּטָן מַלְכוּת, ב' תְּרֵין דְּרוֹעִין גְּדוּלָה גְבוּרָה, ת' תִּפְאֶרֶת, בֵּיהּ שְׁקִיל שַׁבָּת לְכָל אוֹרַיְיתָא, תְּלַת כִּתְרִין דְש תְּלַת סְפִירָן עִלָּאִין, וְכֻלְּהוּ כְּלִילָן בִּתְיוּבְתָּא. דְּאִיהִי שְׁכִינְתָּא עִלָּאָה, וַעֲלָהּ אִתְּמַר תְּפִלַּת כָּל פֶּה.</p>\n<p>וְהָא עַמּוּדָא דְאֶמְצָעִיתָא אִתְקְרֵי תְּפִלַּת כָּל פֶּה, אֶלָּא (כל) אִיהוּ בֶ\"ן י\"ה מִן בִּינָ\"ה, וְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, אִיהוּ מְמוּצָע בִּתְּלַת אַתְוָון דְּאִינוּן יה\"ו, דְאִתְכְּלִילָן בְּבִינָה, וְאִיהוּ מְמוּצָע כְּגוּפָא בֵּין תְּרֵין דְּרוֹעִין, וְאִיהוּ</p>"],[9500011081,"<p>אוֹת בַּצַּדִּיק, דְּאִיהוּ כְּלִיל בְּא\"ת, דְּאִיהִי שְׁכִינְתָּא תַּתָּאָה כְּלִילָא מֵא' וְעַד ת',</p>\n<p>וְאִיהוּ כְּלִיל תְּלַת בִּרְכָאָן דִּצְלוֹתָא קַדְמָאִין, וּתְלַת בַּתְרָאִין, וְאִיהוּ כְּלִיל תְּרֵין ו'ו' דְּאִתְּמַר בְּהוֹן (שמות כח ז) עַל שְׁתֵּי קְצוֹתָיו וְחֻבָּר, דְּאִינוּן (נ\"א ואינון) י\"ב בִּרְכָאָן דִּצְלוֹתָא דְּאִתְקְרִיאוּ אֶמְצָעִיּוֹת, וְכֻלְּהוּ חַ\"י בִּרְכָאָן דְּאִתְכְּלִילָן בְּה דְּאִינוּן תְּלַת וָוִי\"ן, (נ\"א דאתמר בהון יו\"ד ה\"א וא\"ו ה\"א), דְּאִיהוּ דוּ פַּרְצוּפִין,</p>\n<p>וְדָא אִיהוּ שִׁעוּר קוֹמָה, דְאִתְּמַר בֵּיהּ (שם כו טז) עִִשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, בְּמַאי סָלְקַת לְעִִשֶׂר בְּאָת י'.</p>\n<p>קָם סָבָא חַד פָּתַח וְאָמַר, וַדַּאי ה' אִית בָּהּ תְּלַת וָוִי\"ן, דְּאִינוּן חַ\"י בִּרְכָאָן, כְּגַוְונָא דָא [ציור], דְּאִתְּמַר בְּהוֹן (משלי י ו) וּבְרָכוֹת לְרֹאשׁ צַדִּיק,</p>\n<p>מַאי רֹאשׁ צַדִּיק דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְּבֵיהּ שַׁרְיָין חַ\"י בִּרְכָאָן דְּה' עִלָּאָה, וּמִנֵּיהּ אִתְמְשִׁיכוּ לְה' זְעִירָא עַל יְדָא דְצַדִּיק,</p>\n<p>וּבְגִין דָּא גוּף וּבְרִית חַשְׁבִינָן חַד.</p>\n<p>ו' דְּאִיהוּ בִמְצִיעוּת ה\"ה, אִיהוּ שִׁעוּר קוֹמָה, וְאִיהוּ אַמָּה, וְסָלִיק (נ\"א דסליק) בְּאָת י' לְעִִשֶׂר אַמּוֹת, דְּאִתְּמַר בֵּיהּ (שמות כו טז) עִִשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, וְאַמָּה וַחֲצִי הָאַמָּה רֹחַב הַקֶּרֶשׁ הָאֶחָד, דָּא ו' י', דְּאִיהוּ בְרָזָא דְז', דְּכָל תַּגִּין בֵּיהּ אִתְקְרִיאוּ.</p>\n<p>שְׁתֵּי כְתֵפֹת (שם כח ז) חֹבְרֹת דָּא כָתֵף עִלָּאָה וְכָתֵף תַּתָּאָה, דְאִינוּן יְמִינָא וּשְׂמָאלָא, וְאִינוּן ה\"ה, אֶל שְׁנֵי קְצוֹתָיו אִינוּן ו' ו', וּבְהוֹן אִתְעֲבִיד ה' ה' בְּחִבּוּרָא, וּבְגִין דָּא אֶל שְׁנֵי קְצוֹתָיו וְחֻבָּר (שם).</p>\n<p>בְּכָל אֲתַר אַמָּה אִיהִי ו', וּבְגִין דָּא אִיהִי בַּת שִׁשָּׁה טְפָחִים, וַחֲצִי הָאַמָּה דָא י', דִּתְרֵין יוּדִי\"ן אִינוּן שִׁעוּרָא דְאַמָּה, וְאָת י' שִׁעוּרָא דִילָהּ תְּלַת טְפָחִים, וְדָא ג',</p>\n<p>וְעִִשֶׂר אַמּוֹת דָּא אִיהוּ שִׁעוּרָא דְגוּפָא דְבַר נַשׁ, לָקֳבֵל עֲשָׂרָה דְבָרִים דְּאִתְּמַר בְּכוֹס שֶׁל בְּרָכָה, וְלָא אִשְׁתָּאַר בְּזִמְנָא דָא אֶלָּא אַרְבַּע (ס\"א דאסתלק ו' ואשתאר ד' מן דו פרצופין, ושעורא דכלא ו', באת י' סליק לעשר), כְּמָה דְאוּקְמוּהָ.</p>\n<p>וְכֻלְּהוּ רְמִיזֵי בְגוּפָא כְּגַוְונָא דָא, בִּדְרוֹעָא יְמִינָא תְרֵין אַמִּין מִן פִּרְקָא לְפִרְקָא, וְכֵן בִּדְרוֹעָא שְׂמָאלָא תְּרֵין, הָא אַרְבַּע, וְכֵן בִּתְּרֵין שׁוֹקִין ד' הָא ח', וּבְגוּפָא תְּרֵין הָא עִִשֶׂר, דָּא אִיהוּ עִִשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, הַקֶּשֶׁ\"ר אִיהוּ בְהִפּוּךְ אַתְוָון, בֵּין קֶשֶׁר לְקֶשֶׁר.</p>\n<p>וַחֲמִשָּׁה בְרִיחִים לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הָאֶחָת (שם כו כז), אִינוּן חָמֵשׁ אֶצְבְּעָאן דְּיָד יָמִין, וַחֲמִשָּׁה בְרִיחִים לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הַשֵּׁנִית חָמֵשׁ אֶצְבְּעָאן דְּיָד שְׂמָאלָא,</p>\n<p>וְאִינוּן חָמֵשׁ אֶצְבְּעָאן כֻּלְּהוּ מִדָּה לַבְּרִיחִים, וְאִינוּן מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְגוֹמֵר (ישעיה מ יב), וְהָא אוּקְמוּהוּ, וְאִינוּן אָ אֵ אֹ אִ אֻ חָמֵשׁ נְקוּדִין אִלֵּין, דְּאִנּוּן קָמֵ\"ץ צֵרִ\"י חֹלֵ\"ם חִירֵ\"ק שֻׁרֵ\"ק, אִינוּן בְּרָזָא דְאלהי\"ם, דְּהָכִי סְלִיק בְּחֻשְׁבַּן, וְרָזָא דְאלהי\"ם מָלֵא י\"ה, וְדָא אִיהוּ (נ\"א יה\"ו) בִּינָה וַדַּאי. וְהָכִי בְרָזָא ה' אַלְפִי\"ן כְּלִילָן בְּה' תַּתָּאָה,</p>\n<p>וְאִלֵּין אַתְוָון אִינוּן תְּלַת נְשָׁמָה רוּחַ וְנֶפֶשׁ,</p>\n<p>ה' זְעִירָא גוּפָא בֵּית קִבּוּל דְּכֻלְּהוּ, פְּתִילָה (ס\"א פתיל ה') דְּאִתְאַחֲדָן בֵּיהּ תְּלַת גּוּוָנִין דִּשְׁרַגָּא, דְאִיהוּ נֵר יהו\"ה נִשְׁמַת אָדָם (משלי כ כז),</p>\n<p>זַיִת מִזֵּתִים דָּא צַדִּיק, דְּאִתְּמַר בֵּיהּ שֶׁמֶן זַיִת זָךְ, כָּתִית דְּכַתִּישׁ כְּתִישָׁא בְאִינוּן אָתִין (ס\"א זיתין) דְּאִינוּן אֵבָרֵי גוּפָא, וְדָא בְרִית מִילָה, לְגַבֵּי שְׁכִינְתָּא דְאִתְקְרִיאַת גַּד.</p>\n<p>וְרָזָא דְמִלָּה וְהַמָּן כִּזְרַע גַּד הוּא (במדבר יא ז), בְּהַהוּא יוּ\"ד אִתְעֲבִידַת גִּיד, וְאַמַּאי אִתְקְרִיאַת גַּד, בְּגִין דְּאִיהִי כְּלִילָא מִז' סְפִירָאן דְּסָלְקִין לְחוּשְׁבַּן גַּד,</p>\n<p>וְאַמָּאי אִתְקְרִיאַת מָן, בְּגִין דְּכֹלָּא לָא יָדְעוּ מַה הוּא, דְּנָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא מָן דְּאִיהוּ כִּזְרַע גַּד חִוָּור, וְעִינוֹ כְּעִין הַבְּדֹלַח (שם), דְּאִיהוּ חִוָּור מִסִּטְרָא דִימִינָא, וְטַעִִמּוֹ כְּצַפִּיחִית בִּדְבָשׁ (שמות טז לא) מִסִּטְרָא דִשְׂמָאלָא, מַה הוּא, כְלִיל מֵעֲשַׂר אַתְוָון דְּאִינוּן</p>"],[9500011082,"<p>יו\"ד ה\"א וא\"ו ה\"א, וְדָא מַנָּא דְאוֹרַיְיתָא, וְסָלִיק לְחֻשְׁבַּן מ\"ה, וְלָא יָדְעוּ מַ\"ה הוּא.</p>\n<p>וְעִרֶב רַב שְׁאִילוּ בִּשְׂרָא וְיָהִיב לוֹן, וּמַה כְּתִיב (במדבר יא לג) הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם טֶרֶם יִכָּרֵת וְאַף יהו\"ה כו',</p>\n<p>וְהַאי בָּשָׂר הָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין בַּבָּשָׂר הַיּוֹרֵד מִן הַשָּׁמַיִם, דָּא מַנָּא דְאָכְלוּ עִרֶב רַב, וְעִם כָּל דָּא אָמְרוּ עֲלָהּ אֵין דָּבָר טָמֵא (ס\"א רע) יוֹרֵד מִן הַשָּׁמַיִם.</p>\n<p>וְרָזָא דְהַאי בָּשָׂר מַאי נִיהוּ, אֶלָּא כְּמָה דְאַתְּ אָמַר (בראשית ו ג) בְּשַׁגָּם הוּא בָשָׂר,</p>\n<p>וְרָזָא דָא לְחַכִּימֵי לִבָּא אִתְמַסַּר, וְהַאי בָשָׂ\"ר בְּהִפּוּכָא שֶׁבֶ\"ר, וַעֲלֵיהּ אִתְּמַר (שם מב יט) שֶׁבֶר רַעֲבוֹן בָּתֵּיכֶם, אִם זָכוּ בָּשָׂר קֹדֶשׁ, דְּאִתְּמַר בֵּיהּ (איוב יט כו) וּמִבְּשָׂרִי אֶחזֶה אֱלוֹ\"הַ,</p>\n<p>וְאִם לָא נָטְרִין בְּהַאי בָּשָׂ\"ר אוֹת בְּרִי\"ת, אִתְהַפַּךְ לוֹן בַּשֶּׁבֶ\"ר.</p>\n<p>(ס\"א מצאתי) וְתָא חֲזִי</p>\n<p>כָּל שְׁמָא דְאִיהִי מִן תְּרֵין אַתְוָון כְּגוֹן כִּי בְּיָ\"הּ יהו\"ה צוּר עוֹלָמִים (ישעיה כו ד) תַּלְיָא מִן חָכְמָה, וּמִן תְּלַת אַתְוָון תַּלְיָין מִן בִּינָה, וּמִן אַרְבַּע תַּלְיָן מִן שְׁכִינְתָּא תַּתָּאָה, וּמִן חָמֵשׁ תַּלְיָין בְּחָמֵשׁ סְפִירָן, וּמִן שִׁית תַּלְיָין מִן צַדִּיק, וּמִן שֶׁבַע וְתִשְׁעָה בֵּיהּ,</p>\n<p>מִן עִִשֶׂר בִּשְׁכִינְתָּא תַּתָּאָה, דְּאִיהִי עֲשִׂירִית הָאֵיפָה סֹלֶת, וּבָהּ מְעַשְּׂרִין, וּבְגִין דְּאִיהִי כְלִילָא מֵעִִשֶׂר, אִתְּמַר בָּהּ אֵין שְׁכִינָה שׁוֹרָה בְּפָחוּת מֵעֲשָׂרָה</p>\n<p>(כאן חסר).</p>\n<p>זַרְקָ\"א הַאי תַּגָּא אִיהִי י', וְחוּטָא דִילָהּ ו', וְהָא אוּקְמוּהוּ כּוֹרְכִין אֶת שְׁמַע עִם וְאָהַבְתָּ אֵת וְלָא הֲווֹ מַפְסִיקִין, בְּגִין דְּאָת י' אִיהִי אַבְנָא מַרְגְּלִיתָא קַדִּישָׁא יְקָרָא,</p>\n<p>קִירְטָא אִיהִי שָׂפָה, כְּלִילָא מֵחָמֵשׁ תִּקּוּנִין דְּאִינוּן אחה\"ע בומ\"ף וְגוֹמֵר, וְדָא ה' זְעִירָא,</p>\n<p>חָמֵשׁ אַבְנִין דְּקִירְטָא דָא ה' עִלָּאָה, דְאִינוּן שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה,</p>\n<p>אִתְעֲבִידוּ ה' אַבְנִין אֶחָד. כְּרִיכוּ דְכוּלְהוּ ו' דְאִיהוּ כְלִיל שִׁית תֵּיבִין דְּיִחוּדָא, דְאִינוּן שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד (דברים ו ד),</p>\n<p>וּבְהַהוּא כְּרִיכוּ צָרִיךְ לְסַחֲרָא קִירְטָא וּלְאָרְכָא בָּהּ, הַאי אַבְנָא כְּלִילָא מֵחָמֵשׁ, (נ\"א מעשר), עַד דְּסָלִיק לָהּ עַד אֵין סוֹף, וְרָזָא דְמִלָּה לְמַעַן יַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ (שם יז כ).</p>\n<p>כַּד הַאי אַבְנָא בָּעַאת לְמֶעֱבַד דִּינָא בַּעֲמָלֵק, אוֹ בְּסִטְרִין אָחֳרָנִין, וְכֵן בְּחַיָּיבִין, נָטְלָא מִגְּבוּרָה, וְאִתְכְּלִילָן בָּהּ כָּל סְפִירָאן, וְאִתְקְרִיאוּ בָּהּ כֻּלְּהוּ גְבוּרוֹת, וְכַד בָּעַאת לְמֶעֱבַד חִנָּא וְחִסְדָּא בְּעָלְמָא, נָטְלָא מֵחֶסֶד, וְכֻלְּהוּ סְפִירָן אִתְכְּלִילָן בָּהּ וְאִתְקְרִיאוּ חֲסָדִים, וְכַד בָּעַאת לְרַחֲמָא עַל עָלְמָא, נָטְלָא מֵעַמּוּדָא דְאֶמְצָעִיתָא, וְכֻלְּהוּ סְפִירָן אִתְכְּלִילוּ בָּהּ, וְאִתְקְרִיאוּ רַחֲמֵי. וְהַאי י' אִיהִי בְּכָל סִטְרָא,</p>\n<p>אִם כֵּן בְּמַאי אִשְׁתְּמוֹדְעַת כַּד נָטְלָא מֵאֲבָהָן, אֶלָּא בִּנְקוּדָה, כַּד אִיהִי נְקִידָא מִסִּטְרָא דְקמ\"ץ נַטְלָא מֵחֶסֶד, וְכַד אִיהִי נְקִידָא מִסִּטְרָא דִשְׁבָ\"א נַטְלָא (ס\"א ינקא) מִגְּבוּרָה, וְכַד נְקִידָא מֵחֹלֵ\"ם אִיהוּ מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, דִתְלַת נְקוּדִין אִלֵּין אִינוּן מַיָּא וְאֶשָּׁא וְרוּחָא</p>\n<p>(כאן חסר והוא בתקוז\"ח דף כ\"ד ע\"ג).</p>\n<p>וַיֹּאמֶר אֵי הֶבֶל אָחִיךָ (בראשית ד ט),</p>\n<p>תָּא חֲזִי תְּרֵין אַתְוָון אִלֵּין דְּאִסְתַּלְקוּ מִנֵּיהּ, דִּבְהוֹן חָב, גָּרְמוּ לֵיהּ מִיתָה, א' אָמוֹן מוּפְלָא וּמְכוּסֶה, י' מַחֲשָׁבָה,</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, וְהָא כַּמָּה מַחֲשָׁבִין אִינוּן, שְׁכִינְתָּא תַּתָּאָה אִתְקְרֵי מַחֲשָׁבָה, חָכְמָה עִלָּאָה אִתְקְרֵי מַחֲשָׁבָה, וּלְעִילָא לְעִילָא מַחֲשָׁבָה, וּלְעִילָא מִכֻּלְּהוּ מַחֲשָׁבָה, דְלֵית לְעִילָא מִנָּהּ, וְהִיא סְתִימָא דְכָל סְתִימִין, עִלָּאָה דְכָל עִלָּאִין,</p>\n<p>אִי תֵימָא דְסָלִיק מַחֲשַׁבְתֵּיהּ דְּאָדָם תַּמָּן, לָא, דְהָא אִתְּמַר בֵּיהּ (בראשית ג י) וָאִירָא כִּי עִירוֹם אָנֹכִי וָאֵחָבֵא, דְּהַאי עִרוֹם אַחֲזֵי דְאִתְפַּשַּׁט מַלְבּוּשֵׁיהּ, וּבְגִין דָּא אִתְּמַר בְּאַבָּא וָאֵחָבֵא, וּבִבְרָא וַיַּסְתֵּר מֹשֶׁה (שמות ג ו).</p>\n<p>אָמַר לֵיהּ בְּרִי בְּכֹלָּא חָאב, בְּמַחֲשָׁבָה דְאִיהִי לְבוּשָׁא לְמַחֲשָׁבָה סְתִימָא, וּבְמַחֲשָׁבָה סְתִימָא,</p>\n<p>וְדָא הֲוָה מִיתָה דִילֵיהּ, דְּאִסְתַּלַּק מַחֲשָׁבָה סְתִימָא דְכָל סְתִימִין מִנֵּיהּ, דְּאִיהוּ חַ\"י הַחַיִּי\"ם, דְּבַאֲתַר דְּאִיהוּ תַמָּן לֵית מִיתָה תַמָּן, וְחָאב בְּמַחֲשָׁבָה סְתִימָא וְאִשְׁתָּאַר</p>"],[9500011083,"<p>עִרוֹם מִינָהּ, מִכָּל מַה דִּלְעִילָא מִן אִימָּא עִלָּאָה דְאִיהִי תְּשׁוּבָה חָאב, וְאִסְתַּלְקוּ מִנֵּיהּ,</p>\n<p>וְאִי לַאו דְּקָמַת עִמֵּיהּ תְּשׁוּבָה וְגָלַת עִמֵּיהּ, הֲוָה אִתְאֲבִיד מִכָּל וָכֹל, וּבְגִין דָּא (תהלים קל ג) אִם עֲוֹנוֹת תִּשְׁמָר י\"ה אדנ\"י מִי יַעֲמוֹד, מִי יַעֲמוֹד וַדַּאי,</p>\n<p>וּבְגִין דָּא וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם (ישעיהו נ א), הַהִיא דְאִתְּמַר בָּהּ (דברים כב ז) שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם, אֶת לְאַסְגָּאָה שְׁכִינְתָּא תַּתָּאָה עִמָּהּ.</p>\n<p>אִימָּא עִלָּאָה קָמַת בְּאָדָם, וְאִימָּא תַּתָּאָה בְּהֶבֶל, דְּחוֹבָא דְאָדָם רַב הֲוָה מִדְּהֶבֶל, וּבְגִין דָּא בְרִי א\"י מִן אהי\"ה, אִיהוּ א\"י דְחָב בֵּיהּ הֶבֶל, וְאִסְתַּלְקוּ וְאִשְׁתְּאָרַת (נ\"א קין ואסתלק ואשתארו), ה\"ה,</p>\n<p>וּבְגִין דָּא אֵ\"י הֶבֶל אָחִיךָ, וְאִיהוּ א\"י מִן אדנ\"י, וְאִשְׁתָּאַר ד\"ן מִן אדנ\"י, חוֹבָא דְאָדָם גָּרַם דְּאִסְתַּלַּק י\"ו מִן יהו\"ה, וְאִשְׁתָּאַר ה\"ה.</p>\n<p>אָמַר לֵיהּ אַבָּא וְהָא י\"ו הֲוָה לֵיהּ לְמֶהֱוֵי ו\"י,</p>\n<p>אָמַר לֵיהּ בְּרִי וַדַּאי דָּא רָזָא דְחָב בְּמַחֲשָׁבָה עִלָּאָה, דְּאִסְתַּלַּק י' מִן א, וְאִשְׁתְּאָרַת ו\"י, בְּגִין דְּאִסְתַּלַּק מִתַּמָּן עִלַת הָעִלּוֹת דְּאִיהוּ מַחֲשָׁבָה סְתִימָא בְאָת י' מִן א, דְּלֵית יִחוּדָא (ס\"א מחשבה) בַּר מִנֵּיהּ,</p>\n<p>וְהָכָא רָזָא דְלָא אִתְגַּלְיָיא עַד הַשְׁתָּא,</p>\n<p>וְדָא אִיהוּ כִּי יָדַע שְׁמִי יִקְרָאֵנִי וְאֶעֱנֵהוּ (תהלים צא יד),</p>\n<p>שֵׁם י', דְּלֵית לְעִילָא מִנֵּיהּ כְּלָל, אֶלָּא הַהוּא דְבָרָא כֹלָּא, וְלֵית מָאן דְּבָרָא לֵיהּ, דְּאִית בּוֹרֵא דְאִתְבְּרִי, כְגוֹן מַיָּא דְאִיהוּ בֹּרֵא לַעֲשַׂבִּים וְגָדֵל לוֹן וְאִיהוּ אִתְבְּרִי, אֲבָל הַאי בָּרָא וְלָא אִתְבְּרִי, אִיהוּ דְלֵית אֱלֹ\"הַ לְעִילָא מִנֵּיהּ.</p>\n<p>אָמַר לֵיהּ אַבָּא מַאי או\"י הו\"י,</p>\n<p>אָמַר לֵיהּ בְּרִי הַאי אִיהוּ כַּד אִסְתַּלַּק א מִן אהי\"ה, עִם י\"ו מִן יהו\"ה, אִתְעֲבִיד או\"י,</p>\n<p>אָמַר לֵיהּ, אִי הָכִי הַאי א דְתַמָּן ו\"י לְעִילָא מִן א' מִן אהי\"ה אִיהִי, וּמִכָּל שְׁמָהָן,</p>\n<p>אָמַר לֵיהּ בְּרִי אִית א' דְאִיהִי בְדִיּוֹקְנָא דָא יוּ\"ד, י' לְעִילָא ו' בְּאֶמְצַע ד' לְתַתָּא, וְדָא א' מִן אהי\"ה, א' מִן אדנ\"י,</p>\n<p>אֲבָל הַאי א סוֹפָהּ כִּתְּחִלָּתָהּ וּתְחִלָּתָהּ כְּסוֹפָהּ, וּבָהּ אָמַר עִלַּת הָעִלּוֹת אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן (ישעיהו מד ו), וּבְאָת ו' דְאֶמְצָעִיתָא וּמִבַּלְעָדַי אֵין אלהי\"ם.</p>\n<p>אָמַר לֵיהּ הָא וַדַּאי אִתְגַּלְיָא לִי מַה דְּלָא יְדַעִִנָא עַד הַשְׁתָּא, וְלָא עָתִיד לְאִתְגַּלְיָא עַד יוֹמִין דְּיֵיתֵי מַלְכָּא מְשִׁיחָא,</p>\n<p>אָמַר לֵיהּ אִי הָכִי אִשְׁתְּמוֹדָע דְּאִית אָדָם קַדְמוֹן לְכָל קְדוּמִים, וְאִית אָדָם אָחֳרָא,</p>\n<p>אָמַר לֵיהּ בְּרִי הָכִי הוּא וַדַּאי, אָדָם דְּבָרָא לֵיהּ עִלַת הָעִלּוֹת בְּדִיּוֹקְנָא דִילֵיהּ סָתִים וְגָנִיז, הַאי גָּרַם דְּאִסְתַּלַּק עִלַּת הָעִלּוֹת,</p>\n<p>אָדָם תִּנְיָינָא חָאב בְּמַחֲשָׁבָה, וְאָדָם תְּלִיתָאָה חָאב בְּמַעֲשֶׂה, דִּתְלַת אָדָם אִינוּן, אָדָם דִּבְּרִיאָה, אָדָם דִּיְצִירָה, אָדָם דַּעֲשִׂיָּה, דְּלַאו כָּל חוֹבִין שָׁוִין.</p>\n<p>אָמַר לֵיהּ בְּרִי עִם כָּל דָּא הֲוָה ה' קַיְימָא קַמֵּיהּ דְּאָדָם,</p>\n<p>בָּתַר דְּאָתוּ עִרֶב רַב וְעָבְדוּ יַת עִִגְלָא, גָרְמוּ דְאִסְתַּלַּק ה' לְגַבֵּי ו\"י, וְאִתְעֲבִיד הו\"י, וּמָאן גָּרַם דָּא, הוֹי גּוֹי חוֹטֵא (ישעיהו א ד),</p>\n<p>וְאִשְׁתְּאָרַת ה' בַּתְרָאָה יְחִידָה, הֲדָא הוּא דִכְתִיב (איכה א׳:א׳) אֵיכָה יָשְׁבָה בָדָד, דִּבְקַדְמֵיתָא וַתֵּלַכְנָה שְׁתֵּיהֶן (רות א יט) ה\"ה,</p>\n<p>לְבָתַר אִסְתַּלְּקַת ה' עִלָּאָה, אִשְׁתְּאָרַת ה' תַּתָּאָה בַּתְרָאָה יְחִידָה, בָּתַר דְּאִתְעָרְבוּ טוֹב עִם רָע, מַה דְּאַפְרִישׁ קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (בראשית א ד) וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ,</p>\n<p>גָּרְמוּ דְגָלַת שְׁכִינְתָּא וְאִתְעָרְבַת בֵּין אוּמִין דְּעָלְמָא, (ס\"א בין אומין דעלמא ובנהא עמה) וּמְנַטְרָא לוֹן (ס\"א לנטרא לה) בְּגָלוּתָא,</p>\n<p>בְּהַהוּא זִמְנָא נָחִית קוּדְשָׁא בְּרִיךְ הוּא בְּכָל אַתְווֹי דְּאִסְתַּלְקוּ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (ישעיה מב ח) אֲנִי יהו\"ה הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן כו'.</p>"],[9500011084,"<p>בְּרֵאשִׁית בָּרָא אלהי\"ם,</p>\n<p>אלהי\"ם מִ\"י אֵלֶּ\"ה, עֲלֵיהּ אִתְּמַר (ישעיהו מ כו) שְׂאוּ מָרוֹם עִינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּ\"ה.</p>\n<p>בְּרֵאשִׁית, נָחְתוּ תַמָּן תְּרֵין סָבִין, וְאָמְרִין אִתְעֲסַקְנָא בְּמַה דַּהֲוִיתוּן וַאֲנַן לָא הֲוִינָן (נ\"א ולא הוינן), וְדָא ב' תְּרֵין רֵאשִׁית.</p>\n<p>הָא סָבָא עִלָּאָה קָא נָחִית בֵּינַיְיהוּ, אָמַר הָא אֲנַן חַד, וּתְלַת הֲוִינָן וּכְעַן אֲנַן חַד, אלהי\"ם וַדַּאי מִ\"י בָרָא אֵלֶּה, מִ\"י בָרָא בְאִלֵּין תְּלַת, וְאִיהִי רְבִיעָאָה, וּשְׁבִיעָאָה, (ס\"א וחמשאה), (וס\"א ותשיעאה).</p>\n<p>בְּרֵאשִׁית אִינוּן שִׁית סָבִין, וּמָאן נִינְהוּ אֶת הַשָּׁמַיִם, וְאֶת הָאָרֶץ, הָא אֲנַן שִׁבְעָה וּתְלַת גְּנִיזִין עֲלַיְיהוּ. בְּאִלֵּין שִׁבְעָה סָבִין וּבַת שְׁבַּת יְחִידָה לְקִבְלַיְהוּ שִׁבְעָה, וּבְגִין דָּא הָא אֲנַן שִׁבְעָה שָׁבוּעוֹת,</p>\n<p>חַד עוּלֵימָא הֲוָה מְזַנֵּב אַבַּתְרַיְיהוּ,</p>\n<p>וְאִלֵּין סָבִין אַעִִרְעוּ בְּבוֹצִינָא קַדִּישָׁא וְחַבְרוֹי, אָמְרוּ לֵיהּ רַבִּי רַבִּי, אַנְתְּ וַחֲבֵרָךְ אַשְׁכַּחְתּוּן חַד עוּלֵימָא דְאִיהוּ בְאָרְחָא מְזַנֵּב אַבַּתְרַיְיכוּ.</p>\n<p>אָמַר לוֹן, אַעִִרַעִִנָא בְמַשִּׁרְיָין סַגִּיאִין דַּהֲווֹ קָא אַתְיָין מִקְּרָבָא דְחִוְיָא, וְאִנּוּן מַשִּׁרְיָין דְּמַלְאָכִין דְּנָחְתִין מְזַרְזָן לְקַבְּלָא צְלוֹתִין, מִסִּטְרָא דְחַמְשִׁין אַתְוָון דִּמְיַחֲדִין יִשְׂרָאֵל בְּכָל יוֹמָא, דִּבְהוֹן וַחֲמוּשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם (שמות יג יט),</p>\n<p>דְּמַלְאָכִין דְּנָחֲתִין לְאַגָּחָא קְרָבָא, דְקָא מְמַנָּן עַל צְלוֹתִין, כֻּלְּהוּ הֲוה נָחֲתִין (ס\"א סלקין) בְּתוּקְפָא דִגְבוּרָה, כַּד נָצְחִין לְחִוְיָא, וְכַמָּה חֲיָלִין דִּילֵיהּ דְּקָא רָדְפִין אַבַּתְרַיְיהוּ, בְכַמָּה חוֹבִין דְּיִשְׂרָאֵל,</p>\n<p>וְאִינוּן מָארֵי צְלוֹתִין, וּמִסְתַּכְּלִין בְּשֵׁם יהו\"ה דְּאִיהִי בִינָה, דְנָחְתָא עֲלַיְיהוּ בְתוּקְפָא דִגְבוּרָה,</p>\n<p>כֻּלְּהוּ נָפְלִין מִקִּיּוּמַיְהוּ, וְאִתְקַיַּים בְּהוּ סוּס וְרֹכְבוֹ רָמָה בַיָּם (שם טו א), דָּא יָם נ' שַׁעֲרֵי בִינָה, חַמְשִׁין אַתְוָון דִּקְרִיאַת שְׁמַע.</p>\n<p>אָמְרוּ לֵיהּ וּלְחַבְרַיָּא הֲוָה לְכוּ לְעַיְינָא לְאִסְתַּכְּלָא בָתַר הַהוּא דִמְזַנֵּב בָּתַר צְלוֹתִין דְּאִינוּן חַלָּשִׁין, וְלֵית לוֹן רְשׁוּ לְסַלְקָא עִם אָחֳרָנִין וּלְפָרְחָא עִמְּהוֹן לְעִילָא, וּבְגִין אִינוּן צְלוֹתִין חַלָּשִׁין אִתְּמַר (דברים כה יח) וַיְזַנֵּב בְּךָ כָּל הַנֶּחשָׁלִים אַחֲרֶיךָ, (ישעיה יא ו) דְּנַעַר קָטָן נוֹהֵג בָּם.</p>\n<p>דְּאִלֵּין עִִשֶׂר סָלְקִין בְּיו\"ד ה\"א וא\"ו ה\"י, וְכָל חַד אִית לֵיהּ צְלוֹתֵיהּ, וְאִם חָסֵר חַד מִנַּיְיהוּ אֲפִילוּ בַתְרָאָה, לָא סָלִיק צְלוֹתָא דִילֵיהּ עִמֵּיהּ, בְּגִין דְּאִיהוּ עַנְיָא, וְלֵית לֵיהּ רְשׁוּ לְסַלְקָא צְלוֹתֵיהּ עִם אָחֳרָנִין, כֻּלְּהוּ צְלוֹתִין מִתְעַכְּבָן לְסַלְקָא, עַד דְּהַהִיא צְלוֹתָא דְעַנְיָא סְלִיקַת,</p>\n<p>וּבְגִין דָּא תְּפִלָּה לְעָנִי כִי יַעֲטוֹף (תהלים קב א), דְּכֻלְּהוּ מִתְעַטְּפִין בְּגִינָהּ, עַד דְּאִיהִי סָלְקָא עִמְּהוֹן, דְּלֵית פִּרוּדָא בָּהּ מִנַּיְיהוּ.</p>\n<p>וּצְלוֹתָא דְעָנִי אִיהוּ שְׁכִינְתָּא,</p>\n<p>מָאן עָנִי דָא צַדִּיק,</p>\n<p>וְהַאי צְלוֹתָא אִתְקְרִיאַת עָקֵב לְגַבֵּי צְלוֹתִין אָחֳרָנִין, וּבְגִינָהּ אִתְּמַר אֲפִילוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק, אַף עַל גַּב דְּסָחִיר לָהּ לְהַאי נְקוּדָה דְאִיהִי קוֹצָא דְאָת ד', בְּכַמָּה חוֹבִין לְאוֹלָפָא קַטֵּיגוֹרָא עַל בְּנוֹי דִּשְׁכִינְתָּא, לֹא יַפְסִיק לְהַהִיא נְקוּדָה,</p>\n<p>דְּאִם יַפְסִיק, בְּגִינֵיהּ אִסְתַּלַּק קוֹצָא מִן ד' מִן אֶחָד, וְאִשְׁתָּאַר אַחֵר, דְּאִיהוּ נָחָשׁ כָּרוּךְ בַּעֲקֵבוֹ, דִּבְגִין חִוְיָא לָא יַפְסִיק, וְלָא אִסְתַּלַּק קוֹצָא דְאָת ד' מִן אֶחָד,</p>\n<p>אֲבָל בְּגִין עַקְרָב אִסְתַּלַּק, וְאִיהוּ פּוֹסֵק, וּבָרַח מִנֵּיהּ, הֲדָא הוּא דִכְתִיב (בראשית לט יב) וַיַּעֲזוֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה.</p>\n<p>אַדְהָכִי הָא עוּלֵימָא דְקָא אִזְדַּמַּן לְגַבַּיְיהוּ, מְחַמֵּר אַחֵר בְּעִירָן, אָמַר לוֹן מַהוּ וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ,</p>\n<p>אֶלָּא עַקְרָב אִיהִי עָקַר ב', דְּעָקְרַת בֵּיתָא דִשְׁכִינְתָּא,</p>\n<p>וְדָא אִיהוּ בִּגְדוֹ דְחִוְיָא דַעֲבוֹדָה זָרָה, כַּד חִוְיָא אַתְיָא לְאִתְחַבְּרָא עִם גּוּף אָדָם יָשָׁן, דְּאָמְרַת שִׁכְבָה עִמִּי, חֲצוּפָה זוֹנָה, אִתְּמַר בְּאוֹת בְּרִית וַיָּנָס וַיֵּצֵא הַחוּצָה.</p>\n<p>(נ\"א כ\"י ובגין דא אפילו נחש כרוך על עקבו לא יפסיק, אף על גב דסתיר לה לההיא נקודה דאת ד' לא יפסיק, דאי יפסיק בגיניה אסתלק קוצא מן ד' דאחד ואשתאר אחר דאיהו נחש כרוך בגין דחויא לא יפסיק ולא אסתלק, ואיהו פוסק וברחת מניה, אבל עקרב יפסיק, כמה דעבד יוסף צדיקא הדא הוא דכתיב וינח בגדו אצלה וינס וכו'.</p>\n<p>אדהכי הא עולימא קא אזדמן לגבייהו מחמר בתר בעירן, אמר לון מאי וינח בגדו אצלה וכו', אלא עקרב עקר ב', דעקר ביתא דשכינתא, כד בעיא לאתחברא עם צדיקייא צריך לאפסקא מניה, ולא יתהני מיניה ואפילו</p>"],[9500011085,"<p>ממשכא דיליה, לך לך אמרי נזירא סחור סחור לכרמא לא תקרב הדא הוא דכתיב וינח בגדו אצלה, משכא דיצר הרע, ודא בגדו דחוייא עבודה זרה, כד איהו קא אתייא לאתחברא עם צדיקייא ואמרה שכבה עמי חצופה זונה, איתמר באות ברית וינס ויצא החוצה).</p>\n<p>אָמְרוּ לֵיהּ מָאן אַנְתְּ,</p>\n<p>אָמַר לוֹן אֲנָא אִיהוּ בְרָא דְנוּנָא חֲדָא, דְשָׁט בְּיַמָּא רַבְרְבָא, וּבָלַע כָּל נוּנִין דְּיַמָּא וְאַפֵּיק לְהוֹן חַיִּים לְבָר, וּלְזִמְנִין אִיהוּ נָפִיק בְּיַבֶּשְׁתָּא, לְקַיְימָא בֵּיהּ (בראשית מח טז), וְיִדְגּוּ לָרוֹב בְּקֶרֶב הָאָרֶץ, תַּוְוהוּ,</p>\n<p>אָמְרוּ לֵיהּ, בָּתַר דְּלֵית רְעוּתָךְ לְגַלָּאָה מָאן אַנְתְּ וּבְרָא דְמָאן אַנְתְּ, מָאן אִיהוּ (נ\"א מאי איהו) אֲתַר דְּדוּכְתָּךְ,</p>\n<p>אָמַר לוֹן אֲתַר דְּדוּכְתִּי אִיהוּ מַגְדְּלָא חָדָא דְפָרַח בַּאֲוִירָא תַּוְוהוּ.</p>\n<p>אָמְרוּ לֵיהּ לָא תֵימָא לָן מִדֵי (ס\"א מלי), מַאי אִיהוּ אָבוּךְ,</p>\n<p>אָמַר לוֹן אַבָּא דִילִי אִיהוּ חַד נוּנָא רַבְרְבָא, דְכַד צָחֵי, אַפְתַּח פּוּמֵיהּ וּבָלַע מַיָּא דְיַמָּא, וְעַד שַׁבְעִין (ס\"א שבעה) שְׁנִין לָא הֲדַר יַמָּא לְתוּקְפֵיהּ, וְרָזָא דְמִלָּה יִבְטַח כִּי יָגִיחַ יַרְדֵּן אֶל פִּיהוּ (איוב מ כג), וְאִיהוּ בָלַע כָּל כַּךְ מִן יַמָּא, וְאַתּוּן לָא אִשְׁתָּאַבְתּוּן מִנֵּיהּ אֶלָּא כַּד חַד, דְּאִיהוּ כ\"ד סִפְרֵי דְאוֹרַיְיתָא, אֵיךְ לָא אִשְׁתְּמוֹדַעִִתּוּן בֵּיהּ.</p>\n<p>בְּהַהוּא זִמְנָא אִדְכַּר רַבִּי אֶלְעָזָר וְאָמַר וַדַּאי אַנְתְּ אִיהוּ בְרָא דְרַב הַמְנוּנָא סָבָא,</p>\n<p>חָדוּ בֵּיהּ, וְאָמְרוּ. בְּוַדַּאי אִי אַנְתְּ הֲוִית בְּהַאי עָלְמָא, הֲוִינָן קָא נָחֲתִין מִסּוּסְוָון דִּילָן, וַהֲוִינָן אֲנַן מְחַמְּרִין בָּתַר בְּעִירָךְ.</p>\n<p>אָמַר לוֹן, הַהוּא חִוְיָא דְאַתּוּן מַגִּיחִין קְרָבָא בֵיהּ אֵיךְ אִשְׁתֵּזַבְתּוּן מִנֵּיהּ, דְּאִיהוּ בָלַע וְקָטִיל, וְלָא עוֹד אֶלָּא דְאִיהוּ קָטִיל לְאָדָם קַדְמָאָה, וּלְכָל דָּרִין דְּקָא אַתְיָין אַבַּתְרֵיהּ,</p>\n<p>וּבְרַתָּא אִיהִי עַל מַגְדְּלָא דְפָרַח בַּאֲוִירָא, וּמַכְרִיזִין בְּכָל יוֹמָא בִרְקִיעָא, דְכָל מָאן דְּקָטִיל לְהַאי חִוְיָא, דְיָהֲבִין לֵיהּ לְאִנְתּוּ בַת מֶלֶךְ פְּנִימָאָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ,</p>\n<p>וְהַאי זָהָב אִיהוּ ז' יְמֵי בְרֵאשִׁית, ה' חָמֵשׁ אוֹר, ב' אִיהִי ב' מִן בְּרֵאשִׁית, עֲלָהּ אִתְּמַר (שיר ז י) יָפָה כַלְּבָנָה, תּוֹרָה שֶׁבְּעַל פֶּה קְרָאָן לָהּ בִּמְתִיבְתָּא.</p>\n<p>וּבְגִין דָּא כָרוֹזָא כְרִיז,</p>\n<p>כַּמָּה גִבָּרִין, כַּמָּה מָארֵי תְרִיסִין, אִתְכַּנְשׁוּ בְּבֵי מֶדְרָשָׁא, לְאַגָּחָא קְרָבָא עִם חִוְיָא בְגִינָהּ, וְכַמָּה תְרִיסִין אִתְעֲבִידוּ פְּסָקוֹת בְּגִינָהּ דִּבְרַתָּא דְמַלְכָּא,</p>\n<p>וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ (שמות ב יב), לֵית בְּהוֹן דְּקָטִיל לְחִוְיָא, עַד דְּיֵיתֵי הַהוּא דְאִתְּמַר בֵּיהּ וַיִּפֶן כֹּה וָכֹה וַיַּךְ אֶת הַמִּצְרִי, וּבְגִין דָּא אִתְּמַר (בראשית מט י) עַד כִּי יָבֹא שִׁילֹ\"ה, שִׁילֹ\"ה מֹשֶׁ\"ה, דְּאִיהִי מוֹרָשָׁה דִילֵיהּ, וּבְגִין דָּא בְּגִינֵיהּ אִתְּמַר בֵּיהּ עַד כִּי יָבֹא שִׁילֹ\"ה, דִילֵיהּ (נ\"א דילה) וַדַּאי,</p>\n<p>אִיהוּ קָטִיל לְחִוְיָא.</p>\n<p>וְל\"וֹ יִקְּהַ\"ת עַמִּי\"ם (שם), בְּגִין דְּאִיהוּ בֶּן יִצְהָר בֶּן קְהָ\"ת בֶּן עַמְרָ\"ם, בֶּן עַמָּא רָמָא, דְאִתְּמַר בֵּיהּ (דהי\"א כג יז) וּבְנֵי רְחַבְיָה רָבוּ לְמָעִִלָה,</p>\n<p>וְקָטִיל לְחִוְיָא, וְחֵילֵיהּ בְּיַמָּא וּבְיַבֶּשְׁתָּא וּבִרְקִיעָא,</p>\n<p>וְכַמָּה מָארֵי קְרָבִין אַגָּחוּ עִמֵּיהּ קְרָבָא עַל יַמָּא, כְּמָה דְאַתְּ אָמַר (תהלים קד כו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן בְּיַמָּא דְאוֹרַיְיתָא, דְּאִינוּן אֳנִיּוֹת עַיְינִין דְּמִסְתַּכְּלִין בְּאוֹרַיְיתָא, וְכַמָּה אֳנִיּוֹת מִנַּיְיהוּ אִתַּבְּרוּ וְנָפְלוּ בְּיַמָּא. עַד דְּיֵיתֵי מוֹרָשָׁה דִילָהּ, וְקָרַע יַמָּא דְאוֹרַיְיתָא, וְסוּס וְרוֹכְבוֹ רָמָה בַיָּם, דְּאִיהוּ חִוְיָא וּבַת זוּגֵיהּ, דְּאִיהִי סוּסְיָא דִילֵיהּ,</p>\n<p>וְאִיהוּ אַעֲבַר עֲלָהּ לְיִשְׂרָאֵל דְּלָא טָבְעִין בָּהּ, הֲדָא הוּא דִכְתִיב (שמות יד כט) וּבְנֵי יִשְׂרָאֵל הָלְכוּ בַּיַּבָּשָׁה בְּתוֹךְ הַיָּם.</p>\n<p>בְּקַדְמֵיתָא בְיַמָּא בְּהַהוּא חֹמֶר, בְּפוּרְקָנָא בַתְרַיְיתָא כֹּלָּא בְיַמָּא דְאוֹרַיְיתָא,</p>\n<p>מַטֶּה דִילֵיהּ דְּקָרַע בֵּיהּ יַמָּא דָא קוֹלְמוֹס, בְּגִין דַּעֲלֵיהּ אִתְגַּלְיָיא זְרוֹעַ יהו\"ה, דְּאִתְּמַר בֵּיהּ (ישעיה נג א) וּזְרוֹעַ יהו\"ה עַל מִי נִגְלָתָה.</p>\n<p>בְּהַהוּא זִמְנָא דְאִתְעֲבַר הַהוּא חִוְיָא בִּישָׁא מִן יַמָּא, שַׁלִּיט חִוְיָא קַדִּישָׁא,</p>\n<p>וּבְהַהוּא זִמְנָא (שם רמש ואין מספר חיות קטנות עם גדולות), אָזְלִין אֳנִיּוֹת בְּהַבְטָחָה בְיַמָּא דְלָא טָבְעִין, דְּהָא רוּחַ סְעָרָה אִתְעֲבַר שָׁלְטָנוּתֵיהּ מִן יַמָּא דְאוֹרַיְיתָא, וּבְהַהוּא זִמְנָא שָׁם רֶמֶשׂ וְאֵין מִסְפָּר וְגוֹמֵר, שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ (תהלים קד כה כו), וִיהֵי חָדֵי עִמְּהוֹן,</p>\n<p>הֲדָא הוּא דִכְתִיב (תהלים מח יד) שִׁיתוּ לִבְּכֶם לְחֵילָה וְגוֹמֵר, לְחוֹלָה כְּתִיב, וְכֻלָּם אֵלֶיךָ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ, (דאינון עתותי דאורייתא כמו שאמרו חכמינו זכרונם לברכה קבעת עתים לתורה) דְּאִיהוּ עִתּוֹ דְצַדִּיק, תִּתֵּן לָהֶם יִלְקוֹטוּן (שם קד כח) דָּא מַנָּא, דְאִתְּמַר בֵּיהּ (שמות טז כו) שֵׁשֶׁת יָמִים תִּלְקְטוּהוּ וְגוֹמֵר, מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ כְּלִיל שִׁית סִטְרִין,</p>\n<p>לִוְיָתָן לְעִילָא דָא צַדִּיק דְּאִיהוּ כְּדָג</p>"],[9500011086,"<p>קָטָן עַל כֵּיף יַמָּא,</p>\n<p>נָחָשׁ בָּרִיחַ, דָּא הַהוּא דְאִתְּמַר בֵּיהּ (שמות כו כח) הַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים, וְדָא עַמּוּדָא דְאֶמְצָעִיתָא דְאִתְקְרֵי תִּיכוֹן, בְּגִין דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, תְּרֵין גַּדְפוֹי יְמִינָא וּשְׂמָאלָא, דְמִתַּמָּן אוֹרַיְיתָא אִתְיְהִיבַת, תְּרֵין קַשְׂקַשּׂוֹי תְּרֵין סַמְכֵי קְשׁוֹט,</p>\n<p>שְׁכִינְתָּא עִלָּאָה אִיהִי יַמָּא, שְׁכִינְתָּא תַּתָּאָה אִיהִי (משלי ל יט) דֶרֶךְ אֳנִיָּה בְּלֵב יָם, דְּאִיהוּ ל\"ב אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית,</p>\n<p>שָׁם רֶמֶשׂ וְאֵין מִסְפָּר, כְּמָה דְאַתְּ אָמַר (שיר ו ח) וַעֲלָמוֹת אֵין מִסְפָּר וכו', וְאִינוּן הֲלָכוֹת פְּסוּקוֹת, דְּאִינוּן (תהלים מה טו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ דִשְׁכִינְתָּא.</p>\n<p>חַיּוֹת קְטַנּוֹת אִלֵּין אַתְוָון דְאדנ\"י, עִם גְּדוֹלוֹת אִינוּן אַתְוָון דְיהו\"ה, דְּאִינוּן מֶרְכָּבוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ,</p>\n<p>אָתוּ כֻּלְּהוּ חַבְרַיָּא לְנַשְׁקָא לֵיהּ, פָּרַח וְלָא חָזוּ לֵיהּ וְלָא מִידֵי.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, אַבָּא, וְהָא שֶׁבַע יַמִּים אִינוּן, וְיָם עִלָּאָה אִיהוּ עַל כֻּלְּהוּ, וַעֲלַיְיהוּ אִתְּמַר (דברים לג יט) כִּי שֶׁפַע יַמִּים יִנָּקוּ, לְמָאן אִינוּן יוֹנְקִים,</p>\n<p>אָמַר לֵיהּ בְּרִי שִׁבְעָה בְּשִׁבְעָה אִינוּן מוּצָקוֹת, וְהָכִי אִינוּן רְקִיעִים שִׁבְעָה בְּשִׁבְעָה, וְהָכִי אִינוּן טוּרִין שִׁבְעָה בְּשִׁבְעָה, וְהָכִי אִינוּן אַרְעִין שִׁבְעָה בְּשִׁבְעָה, יִשּׁוּבִין שִׁבְעָה בְּשִׁבְעָה, וְרָאשִׁין דִּלְהוֹן תְּרֵין, וְרָזָא דְמִלָּה שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה, וְכֻלְּהוּ זָכָר וּנְקֵבָה, וּלְעִילָא חַד גָּנִיז וְטָמִיר, וְהָכִי אִינוּן שֶׁבַע כָּרְסְיָין שִׁבְעָה בְּשִׁבְעָה, שֶׁבַע הֵיכָלִין שִׁבְעָה בְּשִׁבְעָה, וְהָכִי מְמַנָּן אִינוּן שִׁבְעָה וְשִׁבְעָה.</p>\n<p>לִוְיָתָן דְּיַמָּא דָא צַדִּיק, רֵישָׁא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, מָטֵי עַד יַמָּא שְׁבִיעָאָה דְאִיהִי רֵישָׁא דְכֻלְּהוּ, וּתְרֵין גַּדְפוֹי וּתְרֵין קַשְׂקַשִּׂין בְּאַרְבַּע יַמִּים שִׁעוּרַיְיהוּ,</p>\n<p>שִׁעוּר דִּזְנָבָא דְחִוְיָא מָטֵי עַד יַמָּא שְׁבִיעָאָה בַּתְרָאָה, דְאִיהוּ כְּלִילָא שֶׁבַע יַמִּים, דַּעֲלֵיהּ אִתְּמַר (תהלים קיט קסד) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךָ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּרִי, הָא מָארֵי תְרִיסִין קָא נָחֲתִין מִלְּעִילָא, מְלוּבָּשִׁין שִׁרְיָין, קַשְׁתּוֹתֵיהוֹן קַשְׁתֵּי אֵשׁ, וְרוּמְחֵיהוֹן אֶשָּׁא, וְסַיְיפֵיהוֹן לֶהָבָה,</p>\n<p>כֻּלְּהוּ מָארֵי עַיְינִין, בְּוַדַּאי הָא מָארֵי תְרִיסִין בְּבֵי מֶדְרָשָׁא, וְאִלֵּין בְּהוֹן יִתְעָרוּן לְאַגָחָא קְרָבָא לְעִילָא.</p>\n<p>וְלָא עוֹד אֶלָּא דְהָא נוּנָא רַבְרְבָא קָא אַתְיָא, רַב הַמְנוּנָא סָבָא, וַדַּאי בְּכַמָּה נוּנִין חֲיָילִין קַדִּישִׁין דְּתַלְמִידֵי חֲכָמִים, דְּמִתְרַבִּין בְּיַמָּא,</p>\n<p>כְּעַן צָרִיךְ לְפָרְשָׁא לוֹן רֶשֶׁת, לְמִיהְוִי בִרְשׁוּת דִּילָן, וּלְמָארֵי תְּרִיסִין מָאנֵי קְרָבָא,</p>\n<p>כְּעַן צָרִיךְ לְאַתְקָנָא בְקִירְטָא בְּאַבְנִין דְּקִירְטָא, בְּקַשְׁתָּא בְגִירִין דְּקַשְׁתָּא, בְּרוּמְחָא, בְּסַיְיפָא, הַחֲזֵק מָגֵן וְצִנָּה (תהלים לה ב),</p>\n<p>דְּאִית מָארֵי תְּרִיסִין דְּאִינוּן מַגִּיחִין בְּסוּסְוָון, וְאִית אָחֳרָנִין דְּאִינוּן רַגְלִין, דַּעֲלַיְיהוּ אִתְּמַר בְּמַפְּקָנוּתָא דְגָלוּתָא דְמִצְרָאֵי, כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי וְגוֹמֵר (שמות יב לז).</p>\n<p>קָם רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, שִׁמְעוּ הָרִים אֶת רִיב יהו\"ה (מיכה ו ב), מָאן רִיב, דָּא שְׁכִינְתָּא, דְאִיהִי רִיב יהו\"ה, דְּאִיהִי רַבִּי רַב, בְּגִין בְּנָהָא, אִיהִי רִיב בְּרַבִּי וְרַבָּן וְרַבָּא,</p>\n<p>רִיב וַדַּאי בְּכֻלְּהוּ תַּנָּאִים וְאֱמוֹרָאִים, דְּאִיהִי מְרִיבַת בְּהוֹן בְּשִׁית סִדְרֵי מִשְׁנָה, בְּגִין בַּעִִלָהּ דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, כְּלִיל שִׁית סִדְרִין. וַעֲלַיְיהוּ אִתְּמַר (ישעיהו כז ה) אוֹ יַחֲזֵק בְּמָעוּזִי, יַעֲשֶׂה שָׁלוֹם לִי, שָׁלוֹם יַעֲשֶׂה לִּי, תְּרֵי שְׁלָמֵי, חַד בְּעַמּוּדָא דְאֶמְצָעִיתָא, וְחַד בְּצַדִּיק, דַּעֲלַיְיהוּ אִתְּמַר (שם נז ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב,</p>\n<p>דִּבְגָלוּתָא אִתְּמַר בְּעַמּוּדָא דְאֶמָצָעִיתָא מֵרָחוֹק יהו\"ה נִרְאָה לִי (ירמיהו לא ב), צַדִּיק קָרוֹב לָהּ, וּבְגִינֵיהּ אִתְּמַר (משלי כז לה) טוֹב שָׁכֵן קָרוֹב מֵאָח רָחוֹק.</p>\n<p>וּבְגִין דָּא שִׁמְעוּ הָרִים אִלֵּין אֲבָהָן, אֶת רִיב יהו\"ה דָּא שְׁכִינְתָּא, דְאִיהִי רִיב עִם אֲבָהָן, בְּגִין דִּמְרַחֲקִין לָהּ מִבַּעִִלָהּ, דְּאִינוּן אִתְקְרִיאוּ אֱמוֹרָאִים, וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ אִלֵּין אִינוּן תַּנָּאִים, וְאִלֵּין תַּנָּאִי\"ם אֵיתָנִי\"ם בְּהִפּוּךְ</p>"],[9500011087,"<p>אַתְוָון, וְאִינוּן נֶצַח וָהוֹד (צדיקים) אֵיתָנֵי עוֹלָם, וְהָא אֵיתָ\"ן בְּהִפּוּךְ אַתְוָון תַּנְיָ\"א דִמְסַיֵּיעַ לֵיהּ בְּגָלוּתָא, וַעֲלָהּ אִתְּמַר (במדבר כד כא) אֵיתָן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּךָ.</p>\n<p>וְהַאי סֶלַע (אתמר בה דלא נפיק אלא טפין טפין דמיא דאורייתא באלין פסקות ובגין ויך משה את הסלע במטהו פעמים (במדבר כ יא) דא גרים ד) לָא נָפִיק מִינָהּ אֶלָּא טִפִּין טִפִּין זְעִיר שָׁם זְעִיר שָׁם,</p>\n<p>וְכַמָּה מַחֲלוֹקוֹת עַל אִלֵּין טִפִּין, וּמָאן גְּרִים דָּא, הַמּוֹרִים, דְּאִתְּמַר בְּהוֹן כָּל הַמּוֹרֶה הֲלָכָה בִּפְנֵי רַבּוֹ חַיָּיב מִיתָה, וּבְגִין דָּא שִׁמְעוּ נָא הַמּוֹרִים, וּבְגִינַיְיהוּ וַיַּךְ מֹשֶׁה אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם,</p>\n<p>דְּאִם לָא דְמָחָא בָּהּ לָא הֲווֹ טָרְחִין יִשְׂרָאֵל וְתַנָּאִים וְאֱמוֹרָאִין בְּאוֹרַיְיתָא דִבְעַל פֶּה דְּאִיהִי סֶלַע, אֶלָּא אִתְּמַר בּוֹ (שם ח) וְדִבַּרְתֶּם אֶל הַסֶּלַע וְנָתַן מֵימָיו בְּלָא טוֹרַח, וְיִהְיֶה מִתְקַיֵּים בְּהוֹן וְלֹא יְלַמְּדוּ עוֹד וְגוֹמֵר (ירמיה לא לג), וַהֲוָה נָפִיק מַיָּא בְּלָא קֻשְׁיָא וּמַחֲלוֹקֶת וּפְסַק,</p>\n<p>בְּגִין דִּשְׁכִינְתָּא דְאִתְּמַר בָּהּ (שם כג כט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם יהו\"ה הֲוָה שָׁרִי בְּפוּמֵיהוֹן דְּיִשְׂרָאֵל, דְּאִיהִי אוֹרַיְיתָא דִבְעַל פֶּה, דְּאִיהִי סֶלַע עַ\"ל ס', דְּאִינוּן שִׁתִּין מַסֶּכְתּוֹת, דְּהָכִי אִיהוּ סֶלַ\"ע עַ\"ל ס'.</p>\n<p>דִּשְׁכִינְתָּא הֲוָה נָח עַל טִנָּרָא, דִּבְכָל אֲתַר דְּבָעִי קוּדְשָׁא בְּרִיךְ הוּא לְמֶעֱבַד נֵס, שְׁכִינְתָּא אַקְדִּמַת לְהַהוּא אֲתַר, וְכֵיוָן דִּשְׁכִינְתָּא הֲוָה תַּמָּן, לָא הֲוָה לֵיהּ לִמְחָאָה בַסֶּלַע, דִּקְלָנָא הֲוַות לִשְׁכִינְתָּא דַהֲוַת תַּמָּן דְּלָא הֲוָה לֵיהּ חֵילָא לְמֵיהַב מַיָּא, וְדָא אִיהוּ עַל אֲשֶׁר לֹא קִדַּשְׁתֶּם אוֹתִי (דברים לב נא), יַעַן לֹא הֶאֱמַנְתֶּם בִּי לְהַקְדִּישֵׁנִי (במדבר כ יב),</p>\n<p>וּבְגִין דָּא אִסְתַּלַּק שְׁכִינְתָּא מִן הַסֶּלַע, דְּאִיהִי י' מִן מיטטרו\"ן, וְאִשְׁתָּאַר מטטרו\"ן יְבֵשָׁה,</p>\n<p>וְרָזָא דְמִלָּה יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְגוֹמֵר (בראשית א ט), אֶחָד אִיהִי מַלְכוּת, וְתֵרָאֶה הַיַּבָּשָׁה דָא סֶלַע מטטרו\"ן, דִּבְגִינֵיהּ אִתְּמַר (שם ב כא) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו וַיִּסְגּוֹר בָּשָׂר תַּחְתֶּנָּה,</p>\n<p>מַאי בָּשָׂר, הַהוּא דְאִתְּמַר בֵּיהּ (שם ו ג) בְּשַׁגָּם הוּא בָשָׂר, וְעַד דְּנָחִית לָהּ לָא עָלָה הַסֶּלַע וְלָא יָהִיב מֵימוֹי.</p>\n<p>וּבָתַר דְּאִסְתַּלַּק הַאי מַבּוּעָא מִתַּמָּן, שַׁלִּיטַת מָרָה בְּאַתְרָהָא, הֲדָא הוּא דִכְתִיב (שמות טו כג) וַיָּבֹאוּ מָרָתָה,</p>\n<p>וְרָזָא דְמִלָּה וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה וְגוֹמֵר (שם א יד), דָּא קוּשְׁיָא, בְּחֹמֶר דָּא קַל וָחֹמֶר, וְהָא אוּקְמוּהוּ.</p>\n<p>וְהָכִי הֲווֹ יִשְׂרָאֵל עַד דְּאַחֲזֵי לוֹן עִץ, הֲדָא הוּא דִכְתִיב (שם טו כה) וַיּוֹרֵהוּ יהו\"ה עִץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם, וְדָא עִץ הַחַיִּים, דְּאִתְרַבִּי עַל הַהוּא מַבּוּעָא דְאִיהִי שְׁכִינְתָּא, י' מַבּוּעָא דְאַשְׁקֵי לְאִילָנָא דְאִיהוּ ו',</p>\n<p>וְהַאי עִץ מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה דְאִינוּן ה', וַיִּמְתְּקוּ הַמָּיִם דָּא ה' בַּתְרָאָה, דְּאִתְּמַר בָּהּ (רות א כ) קְרֶאןָ לִי מָרָה,</p>\n<p>דִּשְׁכִינְתָּא תַּתָּאָה אִיהִי מַעִִיַן גַּנִּים דְּלֵית לֵיהּ פָּסֵק, טִפָּה דְאִתְמַשְׁכָא מִן מוֹחָא, וְכַמָּה טִפִּין אִתְמַשְׁכָאן מִנֵּיהּ, דְּאִינוּן (תהלים מה טו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ.</p>\n<p>קַרְקַפְתָּא אִיהִי סֶלַע, וּמַבּוּעָא מִלְּגָאו דָּא מוֹחָא, עַל אִלֵּין טִפִּין אִתְּמַר (תהלים קכז ה) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם וְגוֹמֵר, אֶת אוֹיְבִים בַּשָּׁעַר, דְּאִיהוּ תַרְעָא דְצַדִּיק אוֹת בְּרִית קֹדֶשׁ, דַּעֲלָהּ אִתְּמַר (שם קיח ב) זֶה הַשַּׁעַר לַיהו\"ה צַדִּיקִים יָבֹאוּ בוֹ.</p>\n<p>וְעוֹד שִׁמְעוּ הָרִים אֶת רִיב יהו\"ה (מיכה ו ב), אִלֵּין תְּלַת יוּדִי\"ן, וְהָאֵיתָנִים מוֹסְדֵי אָרֶץ (שם) אִלֵּין תְּלַת וָוִי\"ן, דְּכֻלְּהוּ אִתְרְמִיזוּ בְּוַיִּסַּע וַיָּבֹא וַיֵּט.</p>\n<p>קוּם אֶלְעָזָר וּנְטֵיל קִירְטָא דְאִיהִי שְׁכִינְתָּא (ואקיף לה תגא), וּזְרֵיק מִנָּהּ אִיהִי אֶבֶן טִפָּה קַדִּישָׁא, דַּעֲלָהּ אִתְּמַר (בראשית ב ו) וְאֵד יַעֲלֶה מִן הָאָרֶץ, (ובגין דא)</p>"],[9500011088,"<p>אִסְתַּלְּקַת עִזְקָא מִן א' מִן זרק\"א, לְקַבְּלָא עֲלָהּ אֶבֶן יְקָרָה דְאִיהִי טִפָּה, וּמִיָּד וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה,</p>\n<p>כַּד סְלִיקַת, סְלִיקַת בְּאִימָּא, דְאִיהוּ א' מִן אדנ\"י אהי\"ה,</p>\n<p>וְעַל מָאן סְלִיקַת, עַל עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ ו', דְּאִיהִי כְּרִיכָא בֵיהּ כְּעִזְקָא בְּאֶצְבְּעָא,</p>\n<p>וּסְלִיקַת בְּד' מִן אדנ\"י, דְּאִינוּן תְּרֵין דְּרוֹעִין וּתְרֵין שׁוֹקִין, עַד דְּסָלִיק לְאָת י' דְּאִיהִי אַבָּא חָכְמָה י' עִלָּאָה, בְּגִין דְּמִתַּמָּן אִתְנְטִילַת, הֲדָא הוּא דִכְתִיב (משלי ג יט) יהו\"ה בְּחָכְמָה יָסַד אֶרֶץ,</p>\n<p>וּנְטִילַת נְבִיעוּ וְשַׁקְיוּ מִנֵּיהּ לְעִילָא, בְּקוֹצָא דִילֵיהּ לְעִילָא, וּבְאֶמְצָעִיתָא, וּבְקוֹצָא דִילֵיהּ לְתַתָּא,</p>\n<p>וְכַד נְחִיתַת, נְחִיתַת כְּלִילָא מִתְּלַת טִפִּין, בְּהַהוּא זִמְנָא אִתְּמַר בָּהּ הוֹלֵךְ סֶגוֹלְתָּ\"א. וְאִתְקְרִיאַת י' י' י' בִּתְּלַת יוּדִי\"ן,</p>\n<p>י' עִלָּאָה אִיהִי עַל רֵישָׁא דְא, דְאִיהִי כֶּתֶר עִִלְיוֹן עַל כָּל עִלָּאִין, וּלְבָתַר נְחִיתַת בְּאֶמְצָעִיתָא וְנָטְלָא מִתַּמָּן (בעמודא דאמצעיתא) (נ\"א באמצע), וּלְבָתַר נְחִיתַת לְתַתָּא בְּאַתְרָהָא י' דְאִיהִי לְתַתָּא מִן א.</p>\n<p>קָם עוּלֵימָא בָּתַר טוּלָא, אָמַר רַבִּי רַבִּי הָא טִפָּה קָא נָחְתָא, טוֹל קֶשֶׁת בִּידָךְ, דְּאִיהוּ כְּגַוְונָא דְאֶצְבְּעָא וְעִזְקָא בֵּיהּ, טוּל לֵיהּ וּדְרֵךְ (ס\"א וזרקה) לֵיהּ לְגַבָּהּ, דְּקַבִּילַת לָהּ עֲלֵיהּ,</p>\n<p>דְּהָא כַּד סְלִיקַת מִתַּתָּא לְעִילָא עַל רֵישָׁא דְאָת ו', אִיהוּ כְּרוּמְחָא ו', אִתְאָרְכַת בֵּיהּ כְּשַׁרְבִיטָא דְכֹכָבָא,</p>\n<p>וְכַד סְלִיקַת לְעִילָא שַׁרְיָא עֲלָהּ י' וְאִתְעֲבִידַת ז', וַדַּאי תַּגָּא עַל רֵישָׁא דְסֵפֶר תּוֹרָה,</p>\n<p>כֵּיוָן דְּנָחְתַת, צָרִיךְ לְמִדְרַךְ קֶשֶׁת לְגַבָּהּ דְּאִיהוּ צַדִּיק, וּמִנֵּיהּ נְחִיתַת וְאִזְדְּרִיקַת בְּאַתְרָהָא.</p>\n<p>וְחַרְבָּא דְאִיהִי (דהאי) טִפָּה אִיהִי חַתִּיכַת לָהּ לִתְלַת טִפִּין, בְּגִין דְּאַזִּילַת סֶגוֹלְתָּא,</p>\n<p>דְכַד נְחִיתַת עֲלָהּ הֲוָה י', וּלְבָתַר חַתִּיכַת לָהּ לִתְלַת, לְמֶהֱוֵי תַּגָּא וַעֲטָרָה בְרֵישָׁא דִתְלַת אֲבָהָן, דִּתְהֵא כֶתֶר תּוֹרָה וְכֶתֶר כְּהוּנָה וְכֶתֶר מַלְכוּת, וְדָא רָזָא דְ [ציור] תְּלַת תַּגִּין עֲלָהּ.</p>\n<p>דְּרֵישָׁא דְחַרְבָּא אִיהִי י', גּוּפָא דְחַרְבָּא ו', תְּרֵין פִּיפִיּוֹת דִּילָהּ ה\"ה, נַרְתְּקָא דִילָהּ אדנ\"י,</p>\n<p>(וחרבא יהו\"ה),</p>\n<p>וְכַד אִיהִי יהו\"ה בַּר מִשְּׁכִינְתֵּיהּ, אִיהוּ דִין דְּחַתִּיךְ מִכָּל סִטְרָא, כַּד עָאל בְּנַרְתְּקָהּ אִתְעֲבִיד רַחֲמֵי וְלָא חַתִּיךְ דִּינִין, וְרָזָא דְחַרְבָּא בְּנַרְתְּקָהּ, יאהדונה\"י הָכִי וַדַּאי.</p>\n<p>וּבְזִמְנָא דְיהו\"ה בַּר מִשְּׁכִינְתֵּיהּ, אִתְּמַר בֵּיהּ (דברים ד כג) כִּי יהו\"ה אלהי\"ך אֵשׁ אֹכְלָה הוּא, דְּנָטִיל מִגְּבוּרָה לְאוֹקָדָא עָלְמָא, י' אִתְעֲבִיד גַּחֶלֶת, ו' שַׁלְהוֹבָא דְגַחֶלֶת, ה' ה' חַד חָמֵשׁ גַּוָּונִין, תִּנְיָינָא חָמֵשׁ נְהוֹרִין דְּנַהֲרִין בְּהוֹן,</p>\n<p>וּבְזִמְנָא דְה' עִלָּאָה אִסְתַּלְּקַת מֵה' תַּתָּאָה, אִיהִי אָמְרָה (שיר א ו) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, וּבְזִמְנָא דְאִיהִי נַהֲרָא בְּגַוְּונָהָא, אִתְּמַר בָּהּ (בראשית ט טז) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם,</p>\n<p>קָמוּ תַּנָּאִים וְאֱמוֹרָאִים דִּלְעִילָא, וְאָמְרוּ רַבִּי רַבִּי כַּמָּה תַקִּיפָא קִירְטָא דִילָךְ, דִּי סְלִיקַת לָהּ עַד אֵין סוֹף, וּנְחִיתַת לָהּ עַד אֵין תַּכְלִית.</p>\n<p>פָּתַח כְּמִלְּקַדְמִין וְאָמַר, שִׁמְעוּ הָרִים אֶת רִיב יהו\"ה (מיכה ו ב),</p>\n<p>אָמַר לוֹן אֲבָהָן אֲבָהָן טוּרִין רַבְרְבִין, שְׁמָעוּ, דְּהַאי אֶבֶן דְּאִתְגְּזֶרֶת מֵאִלֵּין טוּרִין דִּלְכוֹן, דְּאִיהִי כִּתְרָא בְרֵישָׁא דְכֻלְּהוּ, וְהָאֵיתָנִים דְּאִיהִי כִּתְרָא עַל כֻּלְּהוּ, אִיהִי סְלִיקַת רִיב עֲלַיְיכוּ, בְּגִין בַּעִִלָהּ,</p>\n<p>דְּאִיהִי מַבּוּעָא סְתִימָא כַּסֶּלַע, עַד דְּיֵיתֵי בַּעִִלָהּ לָא יַהֲבָא מֵימוֹי, דְּהָא לִישָׁנִין אִינוּן כַּפַּטִּישִׁין דִּמְחָאָן בְּהַהוּא סֶלַע, וְלֵית חַד מִנַּיְיהוּ דְאַפִּיק מִינָהּ נְבִיעוּ, בַּר מִבַּעִִלָהּ דְּיָדַע לְאַמְשָׁכָא לָהּ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, זַכָּאָה אִיהוּ מָאן דִּמְצַלֵּי וְיָדַע לְסַלְקָא רְעוּתֵיהּ לְעִילָא, דְּהָא פִּימוֹי אַפִּיק שְׁמָהָן, וְאֶצְבָּעוֹי כָּתְבִין רָזִין,</p>\n<p>וְכַד סָלְקִין שְׁמָהָן</p>"],[9500011089,"<p>מִפִּימוֹי, כַּמָּה עוֹפִין פָּתְחִין גַּדְפַיְיהוּ לְעִילָא לְקַבְּלָא לוֹן, וְכַמָּה חֵיוָון דְּמֶרְכַּבְתָּא, כֻּלְּהוּ מִזְדַּמְּנִין לְגַבַּיְיהוּ לְנַטְלָא לוֹן,</p>\n<p>כָּל שֶׁכֵּן אִם שְׁכִינְתָּא שַׁרְיָא בִּצְלוֹתֵיהּ, וְאִסְתַּלְּקַת לְקוּדְשָׁא בְּרִיךְ הוּא, וְרָזָא דְמִלָּה אִם תִּשְׁכְּבוּן בֵּין שְׁפַתָּיִם, (תהלים סח יד), אַל תִּקְרֵי אִם אֶלָּא אֵם,</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּסָלִיק לָהּ בִּצְלוֹתֵיהּ דִּמְצַלֵּי בְשִׂפְווֹי, לְעִילָא לְגַבֵּי בַעִִלָהּ.</p>\n<p>בִּצְלוֹתָא דְשַׁחֲרִית סָלְקָא בִשְׁמָא דְאִתְקְרֵי אֵ\"ל, הָאֵ\"ל הַגָּדוֹל וַדַּאי,</p>\n<p>בִּצְלוֹתָא דְמִנְחָה סְלִיקַת בִּשְׁמָא דְאִתְקְרֵי אלהי\"ם,</p>\n<p>בִּצְלוֹתָא דְעַרְבִית סְלִיקַת בִּשְׁמָא דְאִתְקְרֵי יהו\"ה,</p>\n<p>וְרָזָא דְמִלָּה אֵ\"ל אלהי\"ם יהו\"ה דִּבֶּר וַיִּקְרָא אָרֶץ (שם נ א).</p>\n<p>וְאָמְרוּ מָארֵי מַתְנִיתִין, דְּצָרִיךְ בַּר נַשׁ בִּצְלוֹתֵיהּ לִשְׁהוֹת שָׁעָה אַחַת קֳדָם דִּמְצַלֵּי, וְשָׁעָה אַחַת לְבָתַר דִּמְצַלֵּי,</p>\n<p>וְרָזָא דְמִלָּה דְיִשְׁהֵא בִצְלוֹתֵיהּ שַׁעִִתָּא חֲדָא, בְּגִין דְּאִתְּמַר (בראשית כד כא) וְהָאִישׁ מִשְׁתָּאֵה לָהּ מַחֲרִישׁ, הַהוּא דְאִתְּמַר בֵּיהּ (שמות טו ג) יהו\"ה אִישׁ מִלְחָמָה,</p>\n<p>וּלְבָתַר דְּשָׁהָא לֵיהּ בַּר נַשׁ וְצַלִּי, אִם שְׁגוּרָה תְּפִלָּתוֹ בְּפִיו וַדַּאי אִתְקַבַּל צְלוֹתֵיהּ.</p>\n<p>וְרָזָא דְמִלָּה בַר נַשׁ צָרִיךְ לְמִשְׁהֶא וְאִתְּתָא לְאַקְדָּמָא, כְּמָה דְאַתְּ אָמַר (ויקרא יב ב) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר,</p>\n<p>(ורזא דמלה אשה מזרעת תחלה יולדת זכר, ועוד (תהלים קלו כג) שבשפלנו זכר לנו, ורזא דמלה שבשפלותו של אדם זכור יזכרנו לטובה).</p>\n<p>וְעוֹד אִם שְׁגוּרָה תְּפִלָּתוֹ בְּפִיו, אִיהוּ רָזָא וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יוֹצֵאת (בראשית כד טו), וְרָזָא דְמִלָּה וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה, עוֹד הֵם מְדַבְּרִים וַאֲנִי אֶשְׁמָע (ישעיהו סה כד),</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּלָא מְעַכֵּב מַטְרוֹנִיתָא לְסַלְקָא לְמַלְכָּא, דְּכָל מָאן דְּאִיהוּ צְלוֹתֵיהּ שְׁגוּרָה בְּפִימוֹי בְּלָא עִכּוּבָא, הַהוּא מְמַהֵר מַטְרוֹנִיתָא לְמַלְכָּא,</p>\n<p>וַוי לוֹן לִבְנֵי נָשָׁא דְאִינוּן אֲטִימִין לִבָּא וְעַיְינִין, דְּלָא מִשְׁתַּדְלִין לְמִנְדַּע בִּיקָרָא דְמָארֵיהוֹן לְרַצּוּיֵי לֵיהּ בִּשְׁכִינְתֵּיהּ, בְּכַמָּה תַּחֲנוּנִים וּפִיּוּסִים, לְנַחֲתָא לֵיהּ לְגַבֵּי שְׁכִינְתָּא,</p>\n<p>כָּל שֶׁכֵּן לְאַתְעָרָא בֵיהּ רְחִימוּ לְגַבָּהּ, כְּמָה דְתַקִּינוּ הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה.</p>\n<p>וְכַד קַיְימִין קֳדָמֵיהּ, צָרִיךְ לְמֵיקַם קֳדָמֵיהּ בִּדְחִילוּ,</p>\n<p>זַכָּאִין אִינוּן יִשְׂרָאֵל דְּיָדְעִין לְפַיְיסָא לְמָארֵיהוֹן כִּדְקָא יָאוּת, וּלְחַבְּרָא בְּפִימַיְיהוּ בִּצְלוֹתְהוֹן תְּרֵין שְׁמָהָן אִלֵּין דְּאִינוּן יאהדונה\"י,</p>\n<p>דִּבְהַהוּא זִמְנָא אָ\"ז תִּקְרָא וַיהו\"ה יַעֲנֶה (ישעיהו נח א), וַיהו\"ה הוּא וּבֵית דִּינוֹ, וְדָא שְׁכִינְתָּא (נ\"א ודא חכמתא עלאה ושכינתא) (נ\"א חכמה) עִלָּאָה וְתַתָּאָה,</p>\n<p>וְדָא אִיהוּ רָזָא אִם תִּשְׁכְּבוּן בֵּין שְׁפַתָּיִם (תהלים סח יד), דְּאִיהִי קָרְבָּנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְוַדַּאי שְׁכִינְתָּא אִיהִי קָרְבָּנָא דִילֵיהּ, וּבְגִין דָּא תַּקִּינוּ צְלוֹתָא בְּקָרְבָּנָא.</p>\n<p>הִיא הָעוֹלָה, הָעוֹלָה וַדַּאי,</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּסָלִיק לָהּ לְגַבֵּיהּ כִּדְקָא יָאוּת, דְּאִיהוּ שְׁאִיל בְּגִינָהּ (שיר ח ה) מִי זֹאת עוֹלָה, עוֹלָה וַדַּאי, מִן הַמִּדְבָּר, מִן הַמְּדַבֵּר וַדַּאי, דְּפִימוֹי חָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא כְּטוּרָא דְסִינַי, וּבְגִין דָּא מִי זֹאת עוֹלָה מִן הַמִּדְבָּר וְגוֹמֵר. מְקֻטֶּרֶת מֹר (שם ג ו) דָּא צְלוֹתָא דְשַׁחֲרִית דְּתַקִּין אַבְרָהָם דְּהוּא מֹר,</p>\n<p>וְעוֹד מְקֻטֶּרֶת מֹר, (שם א יג) צְרוֹר הַמֹּר דּוֹדִי לִי, וְדָא נֶצַח דְּסָלִיק לָהּ בִּימִינָא, הֲדָא הוּא דִכְתִיב (תהלים טז יא) נְעִימוֹת בִּימִינְךָ נֶצַח, וּלְבוֹנָה דָא הוֹד, דְּסָלִיק לָהּ בִּגְבוּרָה, מִכֹּל אַבְקַת רוֹכֵל דָּא צַדִּיק, דְּסָלִיק לָהּ בְּעַמּוּדָא דְאֶמְצָעִיתָא,</p>\n<p>וְאִם לָא סָלְקָא שְׁכִינְתָּא בִצְלוֹתֵיהּ, קָרְבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא, הָא כַּלְבָּא קָא נָחִית לְמֵיכַל קָרְבָּנָא דִילֵיהּ, וַוי לֵיהּ טַב לֵיהּ דְּלָא אִתְבְּרִי בְּעָלְמָא, וַעֲלֵיהּ אִתְּמַר (משלי יט כג) גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב.</p>\n<p>וְכַד סָלְקָא שְׁכִינְתָּא בִּצְלוֹתֵיהּ, כַּמָּה חֵיוָון וּמֶרְכַּבְתָּא וְגַלְגַּלֵּי דְכוּרְסַיָּיא, כֻּלְּהוּ יִתְעָרוּן לְגַבָּהּ בְּנִגּוּנָא בְּחֶדְוָה, וְכֻלְּהוּ גַדְפַיְיהוּ פְּתִיחָן לְקַבְּלָא לָהּ, וְהָא אוּקְמוּהוּ (יחזקאל א יא) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמָעִִלָה.</p>\n<p>וְכַד סָלְקָא סָלְקָא כְּיוֹנָה, וְכַד נָחֲתַת נָחֲתַת כְּנִשְׁרָא, דְאִיהִי מַטְרוֹנִיתָא, דְלָא דְחִילַת מִכָּל עוֹפִין דְּעָלְמָא,</p>\n<p>וְנָחְתָא בְּכַמָּה מְזוֹנִין לִבְנָהָא, הֲדָא הוּא דִכְתִיב (דברים לב יא) כְּנֶשֶׁר יָעִיר קִנּוֹ עַל גּוֹזָלָיו יְרַחֵף,</p>"],[9500011090,"<p>מָאן גּוֹזָלָיו, אִלֵּין אִינוּן יִשְׂרָאֵל, דְּאִינוּן כְּגוֹזָלַיָּיא מְצַפְצְפִין לָהּ בְּכַמָה צִפְצוּפִין דִּצְלוֹתָא, וְנָחֲתַת לְגַבַּיְיהוּ, לְכָל חַד נָחְתָא לֵיהּ מְזוֹנָא כִּדְקָא יָאוּת לֵיהּ, לְמָאן נָחְתָא מְזוֹנָא דְאוֹרַיְיתָא דְאִיהִי מְזוֹנָא דְנִשְׁמָתָא, לְמָאן נָחְתָא מְזוֹנָא דְגוּפָא, לְכָל חַד כְּפוּם רְעוּתֵיהּ.</p>\n<p>דָּבָר אַחֵר אֵם תִּשְׁכְּבוּן, דָּא אִימָּא עִלָּאָה, דְאִיהִי צְלוֹתָא דְשַׁבָּת, דִּצְרִיכִין שִׂפְוָון לְקַבְּלָא לָהּ בְּעִִרֶב שַׁבָּת, דְּאִיהִי נִשְׁמַת כָּל חַי, אִיהִי נָחְתָא עַל רֹאשׁ צַדִּיק דְּאִיהוּ יוֹם הַשְּׁבִיעִי,</p>\n<p>לְשׁוֹן לִמּוּדִים קָרִינָן לֵיהּ, וְאִיהִי שַׁרְיָא עֲלֵיהּ בֵּין תְּרֵין שִׂפְוָון דְּאִינוּן נֶצַח וָהוֹד.</p>\n<p>וְשַׁבָּת אִיהִי פֶה, (נ\"א פתח) דְּאִתְפַּתְּחָא בְּעִִרֶב שַׁבָּת לְקַבְּלָא לָהּ בְּהַאי צְלוֹתָא דְשַׁבָּת,</p>\n<p>דְּהָא צְלוֹתָא דְשַׁבָּת אִתְקְרִיאַת קַבָּלָה, וּמִינָהּ מְקַבְּלִין כָּל סְפִירָאן דֵּין מִן דֵּין, וּבָהּ צְלוֹתָא דְבַר נַשׁ מְקוּבֶּלֶת קֳדָם יהו\"ה,</p>\n<p>וְאִיהִי צְלוֹתָא דַעֲשֶׂרֶת יְמֵי תְּשׁוּבָה, וְאִיהִי ה' עִלָּאָה, דְתַקִּינוּ בָּהּ חָמֵשׁ צְלוֹתִין בְּיוֹמָא דְכִפּוּרֵי.</p>\n<p>אֲבָל שַׁבָּת אִיהִי שְׁכִינְתָּא תַּתָּאָה, כְּלִילָא מִתְּלַת אֲבָהָן, דְּאִינוּן תְּלַת עַנְפִין דְּש' דְּשַׁבָּ\"ת,</p>\n<p>בַּ\"ת יְחִידָה אִיהִי נְקוּדָה בֶּחָלָל דִּילָהּ, וְאִיהִי חַג דְּכָל (נ\"א דכליל כל) יוֹמִין טָבִין, עֲלָהּ אִתְּמַר (ישעיהו מ כב) הַיּוֹשֵׁב עַל חוּג הָאָרֶץ.</p>\n<p>אֲבָל נִשְׁמָתָא יְתֵירָא בְּשַׁבָּת וּבְיוֹמִין טָבִין וּבְכָל מוּסָפִין, אִיהִי אִימָּא עִלָּאָה, תּוֹסֶפֶת רוּחַ הַקֹּדֶשׁ,</p>\n<p>צְלוֹתָא דְשִׁית יוֹמִין דְּחוֹל תְּלַת זִמְנִין בְּכָל יוֹמָא, אִיהִי שְׁכִינְתָּא תַּתָּאָה, כְּלָלָא דְתַמְנֵי סְרֵי צְלוֹתִין, תְּלַת זִמְנִין בְּיוֹמָא, סָלְקִין בְּשִׁית יוֹמִין חַ\"י, וְעַל שְׁמֵיהּ אִתְקְרֵי תְּפִלַּת כָּל פֶּ\"ה,</p>\n<p>בְּיוֹמִין דְּחוֹל אַיְיתֵי לָהּ מְזוֹנָא עַל יְדֵי שְׁלִיחַ, אֲבָל בְּשַׁבָּת וְיוֹמִין טָבִין אַיְיתֵי לָהּ מְזוֹנָא עַל יְדָא דְקוּדְשָׁא בְּרִיךְ הוּא, וַוי לְאִתְּתָא דְאִתְפַּרְנְסַת עַל יְדֵי שְׁלִיחָא,</p>\n<p>וְהָא אוּקְמוּהוּ בְיוֹנָה, דְאִתְּמַר (בראשית ח יא) וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ, וְאַמַּאי עֲלֵה זַיִת, אֶלָּא אָמְרַת יוֹנָה, רִבּוֹן עָלְמִין, תְּהֵא מְזוֹנָא דִילִי מְסוּרָה בִּידָךְ וּתְהֵא מְרִירָא כַּזַּיִת, וְלָא תְּהֵא מְתוּקָה וּמְסוּרָה בְיַד שְׁלִיחַ, וּשְׁלִיחַ בְּהַאי אֲתַר דָּא מטטרו\"ן,</p>\n<p>וְעוֹד שְׁכִינְתָּא אִתְקְרִיאַת צְלוֹתָא דְפִסְחָא מִסִּטְרָא דִימִינָא, צְלוֹתָא דְרֹאשׁ הַשָּׁנָה מִסִּטְרָא דִשְׂמָאלָא, צְלוֹתָא דְשָׁבוּעוֹת מִסִּטְרָא דְאֶמְצָעִיתָא, יהו\"ה אִיהִי בְכָל אֲתַר לְקַבְּלָא לָהּ, (ולתקוני מאני קרבא), דָּבָר אַחֵר שִׁמְעוּ</p>\n<p>שִׁמְעוּ הָרִים אֶת רִיב יהו\"ה (מיכה ו ב), מָאן רִיב יהו\"ה וּמָאן הָרִים, רִיב יהו\"ה דָּא שְׁכִינְתָּא, הָרִים אִלֵּין אֲבָהָן, רִיב אִיהִי קְטָטָה וּמַחֲלֹקֶת לְקוּדְשָׁא בְּרִיךְ הוּא, עַל בְּנָהָא דְאִינוּן בְּגָלוּתָא,</p>\n<p>וּבְזִמְנָא דְלַאו אִינוּן בְּגָלוּתָא, אִיהִי רִיב לְגַבֵּיהּ עַל אִינוּן מִסְכְּנִין דְּאָזְלִין מִתְתָּרְכִין מֵאַתְרַיְהוּ, בְגִין דִּיְרַחֵם עֲלַיְהוּ,</p>\n<p>וּקְרָא אוֹכַח, הֲדָא הוּא דִכְתִיב (ישעיה כז ה) אוֹ יַחֲזֵק בְּמָעוּזִי, יַעֲשֶׂה שָׁלוֹם לִי, שָׁלוֹם יַעֲשֶׂה לִי, תְּרֵי שְׁלָמֵי, חַד עִם שְׁכִינְתָּא דְאִיהִי רִיב לְגַבֵּיהּ עַל מִסְכְּנָא,</p>\n<p>וּמָאן אִיהוּ מִסְכְּנָא דְעָבְדַת רִיב בְּגִינֵיהּ, דָּא מִסְכְּנָא דְאִיהוּ מִסִּטְרָא דְצַדִּיק, וְכָל שֶׁכֵּן כַּד צַדִּיק דְּאִיהוּ חָרֵב וְיָבֵשׁ בְּחַ\"י בִּרְכָאָן דִּצְלוֹתָא, וְצָוְוחִין לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְּמַר לְגַבַּיְיהוּ (משלי א כח) אָז יִקְרָאֻנְנִי וְלֹא אֶעֱנֶה.</p>\n<p>וּכְמָה דִשְׁכִינְתָּא תַּתָּאָה אִיהִי רִיב עַל צַדִּיק דְּאִיהוּ חַ\"י עָלְמִין, חָרֵב וְיָבֵשׁ, (חרב מבי מקדשא ויבש מנסכים ועולות), הָכִי אִיהוּ רִיב שְׁכִינְתָּא עִלָּאָה בְגִינֵיהּ עִם קוּדְשָׁא בְּרִיךְ הוּא,</p>\n<p>וַעֲלַיְיהוּ אִתְּמַר (דברים יז ח) דִּבְרֵי רִיבוֹת בִּשְׁעָרֶיךָ, וּבְזִמְנָא דְתַרְוַיְיהוּ אִינוּן רִיבוֹת בְּגִינֵיהּ עִם קוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא צָוַוח לְגַבֵּי יִשְׂרָאֵל לְתַתָּא, אוֹ יַחֲזֵק בְּמָעוּזִי, יַעֲשֶׂה שָׁלוֹם לִי, שָׁלוֹם יַעֲשֶׂה לִּי (ישעיהו כז ה), תְּרֵי שְׁלוֹמִים, לָקֳבֵל תְּרֵי רִיבוֹת,</p>\n<p>וְקַשְׁיָא אִיהִי לָהּ מִכֹּלָּא, אַפְרָשׁוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא מִינָהּ, וְדָא אִיהוּ מַחֲלוֹקֶת לְשֵׁם שָׁמַיִם.</p>\n<p>וְכַד נְפִילַת, נְפִילַת לְרַגְלוֹי, הֲדָא הוּא דִכְתִיב (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב, וְאִתְנַפְּלַת קֳדָמֵיהּ בִּנְפִילַת אַפַּיִם, בְּגִין צַדִּיק דְּאִיהוּ חַ\"י עָלְמִין עָנִי בְגָלוּתָא,</p>\n<p>וְצַדִּיק כַּד אִיהוּ לְבָר מֵאַתְרֵיהּ אִתְּמַר בֵּיהּ (תהלים ב יב) נַשְׁקוּ בַר פֶּן יֶאֱנַף, וּשְׁכִינְתָּא כַד אִיהִי לְבָר מֵאַתְרָהָא אִתְקְרִיאַת בְּרַיְיתָא,</p>\n<p>אִיהוּ בַר וְאִיהִי בְּרַיְיתָא</p>"]]});
